window.SAPHIA_MARKETS={"method":"v1.2","methodDate":"3 Nov 2026","generated":"2026-11-03","markets":{"art":{"slug":"art","name":"Art","family":"Cellar & Collectibles","grade":3,"label":"Specialist","rated":"Physical","asof":"5 Oct 2026","method":"v1.2","axes":{"concentration":{"s":1,"band":"Low","q":""},"liquidity":{"s":3,"band":"Medium","q":"auction); Low (private)"},"scarcity":{"s":5,"band":"High","q":""},"provenance":{"s":3,"band":"Medium","q":""}},"factors":{"Valuation":2,"Exit":2,"Custody":3,"Title and transfer":3,"Access":3,"Intangible premium":1},"horizon":{"big":"10+ years","text":"Auction houses and advisers cite a decade as the minimum for round-trip costs of 30–40% to be absorbed, and most works are held far longer: 72% of high-net-worth collectors have received art by inheritance or gift, and 75% of heirs kept at least some of it. Reselling within a few years of purchase is penalised by the trade."},"exit":{"routes":"Consignment to auction (Christie's, Sotheby's, Phillips, Bonhams and regional houses); private sale through the auction house or a dealer; sale back to the originating gallery, often expected for living artists. Fractional platforms exist but are not an exit for a work already owned.","activity":"Public auction sales were $20.7 bn in 2025, up 9%, within a $59.6 bn market of 41.5 m transactions. Nine of the year's ten top lots sold in one week in New York; the value of works over $10 m rose 30% while online-only sales fell to their lowest since 2019. Depth exists at the top and at the bottom, thinnest in the middle.","cost":"Sotheby's standard seller's commission is 10% of hammer, negotiable above $500,000 and waived for trophy consignments; the buyer pays 28% on hammer to $2 m (£1.5 m), 22% to $8 m and 15% above since February 2026, which caps the hammer. Add marketing, insurance, shipping and, for unsold lots, a buy-in fee.","time":"Consignment deadlines run two to four months before the sale; marquee sales are twice a year. Sotheby's pays within 45 days of the sale subject to the buyer settling. From decision to cash, four to eight months; a private sale can be faster at a price the dealer sets."},"why":"Value rests on expert appraisal and a few auction comparables; most works have no recent price. Exit means auction scheduling, guarantees and fees, over months. Title, provenance and attribution carry the largest risk of any market here.","regime":"The trophy segment rewrote the record book in November 2025 while the broad market contracted.","regimeAsOf":"5 Oct 2026","since":"Hong Kong modern and contemporary evening sales at Christie’s, Sotheby’s and Phillips (28–30 Sep) made $184.6m, up from $164.9m in spring, but with only one white-glove sale and lots withdrawn before Christie’s sale. A Hong Kong gallery closure over rent arrears points to weakness below the top.","themes":["provenance","sanctions","custody","tax","access","tokenisation","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"old-masters","name":"Old Masters","why":"Attribution, auction cycle"},{"slug":"rare-books","name":"Rare Books","why":"Same houses, same calendar"},{"slug":"watches","name":"Watches","why":"Collector demand, dealer exit"},{"slug":"classic-cars","name":"Classic Cars","why":"Condition and provenance"}],"sources":18,"url":"/art-dashboard","exitLabel":"physical","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"Yes","Wrappers":"Masterworks Reg A shares (>$1.2bn raised, 32 exits, trading venue since Jan 2025); art funds; \"fractional platforms exist but are not an exit for a work\"","Owns":"A security in one painting; exit is the sale of the whole work"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Auction-led; private sale through the same houses","Faces":"Christie's, Sotheby's, Phillips, Bonhams and regional houses; a dealer or the originating gallery for private sale","Cost":"Seller 10%, waived for trophies; buyer 28% to $2 m, 22% to $8 m"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Vault (freeport) or Shelf (the wall)","Where":"On the wall, insured; or in a freeport, duty and VAT suspended","Cost":"Insurance, climate control, shipping; freeport space from about $1,000 a month for a painting","Fails":"Condition; title and provenance, the largest risk of any market here"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Calendar auction","Route":"Consignment to Christie's, Sotheby's, Phillips, Bonhams or a regional house; private sale; back to the originating gallery","Open":"Two main seasons a year","Liquidity":"Medium (auction); Low (private)"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"Low","Regime":"Administered (primary); Calendar auction (secondary)","Who":"The gallery sets the primary price and chooses the buyer; Christie's, Sotheby's and Phillips hammers set the secondary comparable"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"Medium","Claim":"Title, provenance and attribution, the largest risk of any market covered","Verifier":"Catalogue raisonné and artist foundations; auction-house due diligence; restitution databases"}}]},"sanctions":{"title":"Sanctions, tariffs and origin","date":"","rows":[{"section":"The register: live measures","cells":{"Instrument":"Tariff; export control","Measure":"Cross-border shipping and tariff regimes tracked as an indicator; national export controls on cultural property","Effect":"Where a work can be consigned and at what landed cost"}}]},"substitutes":{"title":"Synthetic and substitute pressure","date":"","rows":[{"section":"Substitutes by sector","cells":{"Substitute":"None. The asset is a specific object, not a grade; reproduction is a copy, not a substitute","Stage":"Not applicable","Pressure":"Attribution and originality, which is a provenance question","Survives":"The object; its risk is reattribution, not replacement"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"Work: chattel. Masterworks: a Reg A Tier 2 security in a Delaware LLC. Fund: offshore units","UK":"CGT above £6,000; 5% import VAT; artist's resale right 4% of the first €50,000 on dealer and auction resales, capped at €12,500; conditional exemption and acceptance in lieu for pre-eminent works","US":"28%; no like-kind exchange since 2018; a Masterworks share is a security at ordinary capital-gains rates, not a collectible"}}]}}},"bluefin-tuna":{"slug":"bluefin-tuna","name":"Bluefin Tuna","family":"Rare Foods","grade":2,"label":"Restricted","rated":"Route: ranching and seafood groups","asof":"5 Oct 2026","method":"v1.2","axes":{"concentration":{"s":3,"band":"Medium","q":""},"liquidity":{"s":3,"band":"Medium","q":""},"scarcity":{"s":4,"band":"High","q":"wild Ōma"},"provenance":{"s":3,"band":"Medium","q":""}},"factors":{"Valuation":2,"Exit":2,"Custody":2,"Title and transfer":2,"Access":2,"Intangible premium":2},"horizon":{"big":"Equity · fish 2–3 years in pens","text":"Ranched Pacific bluefin are caught young and fattened in pens for two to three years before sale; wild Ōma fish are sold the day they land. The route is seafood groups and ranching operations, so the practical holding is listed equity (Maruha Nichiro, Nissui, Kyokuyo) with no fixed term, bounded by quota allocations set year to year."},"exit":{"routes":"Fish: the Toyosu auction and regional wholesale markets, licensed buyers only; direct contracts with retailers and sushi chains. Capital: shares in the listed seafood groups through any broker; private sale of a ranching licence and pens, which transfers with the quota.","activity":"Hundreds of tuna sell at Toyosu every morning; superb Ōma bluefin trades at roughly ¥17,000–20,000/kg on an ordinary day against the ¥2.1 m/kg paid at the 5 January 2026 New Year auction (¥510.3 m for 243 kg). Pacific bluefin catch limits were raised 60% for 2025–26 as the stock recovered.","cost":"Market commission and handling at Toyosu; grading on the day by cut and fat, which can halve the price of a fish that looked right in the water. Equity: brokerage and spread. Ranching: feed for two to three years and the mortality that comes with it.","time":"A fish is sold within hours of landing and paid on market terms. Shares exit the same day. A ranching business takes months and needs a licensed buyer, since the quota cannot be sold to anyone else."},"why":"Toyosu auction prices are visible but cover a perishable product. The route is ranching operations and seafood groups, bound by catch quotas set by ICCAT in the Atlantic and by the WCPFC and IATTC in the Pacific. Exit is through corporate equity or private sale.","regime":"Toyosu first-auction records for Ōma bluefin, against a commercial price that has not followed.","regimeAsOf":"5 Oct 2026","since":"Re-checked 5 Oct 2026: no new Toyosu price series or quota decision since the last update; the 2026 New Year record (¥510.3m) and the 2025–26 Pacific catch-limit increase remain the latest data points.","themes":["provenance","substitutes","climate","sanctions","custody","tax","access","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"caviar","name":"Caviar","why":"Perishable, auction-priced"},{"slug":"wagyu","name":"Wagyu","why":"Japanese grading and export"},{"slug":"truffles","name":"Truffles","why":"Season sets the price"}],"sources":6,"url":"/bluefin-tuna-dashboard","exitLabel":"ranching and seafood groups","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"No","Wrappers":"Maruha Nichiro, Nissui, Kyokuyo equity; a ranching licence with quota","Owns":"Diversified seafood groups"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Administered auction (trade only)","Faces":"The Toyosu morning auction, licensed buyers only; the New Year sale is a publicity price","Cost":"Market commission; grading on the day can halve the price"}}]},"climate":{"title":"Climate and supply shock","date":"","rows":[{"section":"The register: exposed markets","cells":{"Driver":"Stock recovery under quota; ocean temperature; ranching mortality","Event":"Pacific catch limits raised 60% for 2025–26 by the IATTC–WCPFC joint group","Storable":"No; equity in the ranching groups is the holding"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Living / perishable","Where":"Fish in pens for two to three years; or listed equity","Cost":"Feed and mortality over the ranching period","Fails":"Grading on the day by cut and fat can halve the price"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Calendar auction","Route":"Fish: Toyosu and regional wholesale markets, licensed buyers only. Capital: listed seafood groups","Open":"Daily auction, closed to private holders; equity daily","Liquidity":"Medium"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"Medium","Regime":"Calendar auction","Who":"Toyosu daily auction among licensed buyers; the New Year fish is a ceremony, not a price"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"Medium","Claim":"Wild Ōma vs ranched; species","Verifier":"Toyosu market and quota documentation; licensed buyers"}}]},"sanctions":{"title":"Sanctions, tariffs and origin","date":"","rows":[{"section":"The register: live measures","cells":{"Instrument":"Quota","Measure":"International catch quotas (ICCAT, WCPFC, CCSBT); Pacific limits raised 60% for 2025–26","Effect":"Supply is a treaty decision; a ranching licence transfers with its quota"}}]},"substitutes":{"title":"Synthetic and substitute pressure","date":"","rows":[{"section":"Substitutes by sector","cells":{"Substitute":"Ranched and full-cycle farmed Pacific bluefin; the sector page's route is the ranching groups themselves","Stage":"Advanced","Pressure":"The sushi-grade commercial market","Survives":"Wild Ōma fish, sold the day they land, rated High"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"Seafood-group equity; a ranching licence with ICCAT quota","UK":"CGT at share rates","US":"Share rates; quota is a licence of the flag state, not property"}}]}}},"breeding-stallions":{"slug":"breeding-stallions","name":"Breeding Stallions","family":"Cellar & Collectibles","grade":2,"label":"Restricted","rated":"Living asset","asof":"20 Oct 2026","method":"v1.2","axes":{"concentration":{"s":5,"band":"High","q":"three studs, two countries"},"liquidity":{"s":2,"band":"Low","q":"shares rarely trade"},"scarcity":{"s":4,"band":"High","q":"at the top, c. 740 sires in North America"},"provenance":{"s":2,"band":"Low","q":""}},"factors":{"Valuation":2,"Exit":1,"Custody":3,"Title and transfer":4,"Access":1,"Intangible premium":3},"horizon":{"big":"10–15 years","text":"A share is bought when the horse retires and is held while he covers 100–200 mares a season for ten to fifteen years; the income is the fee, the capital value is a multiple of it. The first evidence that the multiple was right arrives three to five years in, when yearlings sell and then run. Flightline's fee has been cut three years running while his yearlings sold for six times it."},"exit":{"routes":"Private sale of the share to another member or a buyer the syndicate manager approves; occasionally a public auction, as with the Flightline share at Keeneland November 2022. Annual nominations (the right to one cover) are sold separately and are the liquid instrument. Keeneland's November sale lists shares and seasons.","activity":"Shares change hands a few times a year across the whole industry; one Flightline share ($4.6 m for 2.5%) was news. Nominations trade every autumn when fees are set: Vekoma to $100,000 from $35,000 and Into Mischief at the top of the Spendthrift roster for 2026; Flightline cut to $125,000.","cost":"A share at public auction pays the house 5% of hammer plus entry fee; a private transfer pays the syndicate's transfer terms and legal cost. The running cost is the annual keep and the share of insurance, set against the fee income; fertility insurance is limited and mortality cover priced per horse.","time":"A private sale within a syndicate can close in weeks; a public auction waits for the November sale and pays 35 days after. Exiting at a fair price depends on the horse's next crop, so sellers often wait a season for the evidence."},"why":"A stallion is valued as a multiple of a fee that the stud itself sets and revises every year, on evidence (yearling prices, then runners) that arrives three to five years after the purchase. Shares are held in closed syndicates of forty, sold privately or, exceptionally, at auction to buyers the syndicate manager has pre-approved; there is no secondary market in any ordinary sense. Custody is delegated to the stud, which is a strength, but the asset can lose fertility, break down or die, and insurance against the first is limited. Title is clean. Access is the binding constraint: a share in a leading sire is a seven-figure private placement, and the only retail instrument, an annual nomination, is a consumable, not a holding.","regime":"The one form of bloodstock that pays an income, priced each autumn by a fee the stud sets and the market ratifies or refuses; the best horse of his generation has had his fee cut three years running while his yearlings sold for six times it.","regimeAsOf":"20 Oct 2026","since":"First entry. The 2027 fee lists are being published through October and November; Lane's End has left Flightline's \"to be announced\" pending his first crop's remaining season, the first time the farm has held a headline fee open. Darley, Juddmonte, Coolmore and Spendthrift are due before the Keeneland November and Tattersalls December mares sales, where the new fees will be priced into every mare in foal.","themes":["provenance","climate","custody","tax","access","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"racehorses","name":"Racehorses","why":"Where a stallion comes from"},{"slug":"classic-cars","name":"Classic Cars","why":"Syndicate and provenance"}],"sources":12,"url":"/breeding-stallions-dashboard","exitLabel":"syndicate share","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"Rarely: a share is the unit","Wrappers":"The syndicate share, conventionally one of forty; annual nominations as the retail instrument","Owns":"A right to one cover a season and a share of fee income; transfers need the manager's approval"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Private transfer; public auction rare","Faces":"Another member or a buyer the syndicate manager approves; the Flightline share at Keeneland 2022 was news","Cost":"Syndicate transfer terms and legal cost; 5% plus entry at public auction"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Living","Where":"At stud, for 10–15 years","Cost":"Annual keep and a share of insurance against fee income","Fails":"Fertility insurance is limited; mortality cover priced per horse"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Counterparty","Route":"Private sale of the share to another member or a buyer the syndicate manager approves; a public auction is rare","Open":"On request, subject to approval","Liquidity":"Low; shares rarely trade"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"High; three studs, two countries","Regime":"Administered (fee); Dealer quote (shares)","Who":"The stud sets the covering fee each season; shares trade privately with the syndicate's approval"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"Low","Claim":"—","Verifier":"Stud book and syndicate agreement"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"One of forty shares under a syndicate agreement; a nomination is a one-season contract","UK":"Stallion income is trading income where the holder breeds commercially; the share itself follows the animal as a wasting asset","US":"Depreciable; nomination fees ordinary income; Kentucky sales-tax exemption on stud fees and on horses sold for breeding"}}]}}},"caviar":{"slug":"caviar","name":"Caviar","family":"Rare Foods","grade":2,"label":"Restricted","rated":"Route: sturgeon farms","asof":"5 Oct 2026","method":"v1.2","axes":{"concentration":{"s":3,"band":"Medium","q":"High"},"liquidity":{"s":2,"band":"Low","q":""},"scarcity":{"s":2,"band":"Low","q":"farmed); High (wild)"},"provenance":{"s":4,"band":"High","q":""}},"factors":{"Valuation":2,"Exit":1,"Custody":2,"Title and transfer":2,"Access":2,"Intangible premium":3},"horizon":{"big":"8–10 years · the fish","text":"The route is the farm, and the farm's clock is the sturgeon: females first yield at eight to ten years (longer for beluga), so capital is committed for a decade before the first tin. The caviar itself is perishable and is sold within months of harvest; it is not held."},"exit":{"routes":"Sale of the farm or a stake in it to a trade buyer or private equity; sale of fish stock to another farm; the product itself to importers, brands and restaurants under CITES labelling. No listed pure-play; the largest producer, Kaluga Queen, is private.","activity":"China exported 322 t of caviar worth US$98 m in 2024, 43% of world exports, at an average unit value near US$300/kg; French exporters realised US$750–970/kg a shipment through 2026. Farm transactions are rare and private.","cost":"A farm sale carries M&A costs and a valuation on biomass whose price is falling; product sale carries cold-chain freight, CITES paperwork and distributor margins that take the retail price of €800–4,000/kg down to a few hundred dollars at the farm gate.","time":"Product clears within weeks of harvest; a farm or stake takes months to sell and the buyer universe is a handful of operators. Fish stock cannot be liquidated quickly without destroying its value."},"why":"Farmed caviar has transparent wholesale prices that keep falling as Chinese supply grows. The product is perishable, so the route is sturgeon farms. CITES documentation governs trade.","regime":"Farmed supply expansion pushing prices down since the late 2010s; wild product effectively off-market.","regimeAsOf":"5 Oct 2026","since":"Chinese industry data put China at ~60% of global caviar output; a single Hubei farm ships 10,000+ tins a day, and supermarket tins now sell for under ¥200. The price-deflation regime holds; no new US tariff change since the last update.","themes":["provenance","substitutes","climate","sanctions","custody","tax","access","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"bluefin-tuna","name":"Bluefin Tuna","why":"Perishable, CITES-adjacent"},{"slug":"truffles","name":"Truffles","why":"Grade-driven, short shelf"},{"slug":"wagyu","name":"Wagyu","why":"Farmed scarcity"}],"sources":26,"url":"/caviar-dashboard","exitLabel":"sturgeon farms","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"The farm","Wrappers":"None listed; the largest producer, Kaluga Queen, is private; private equity buys stakes","Owns":"—"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Administered","Faces":"Importers, brands and restaurants under contract; private equity for the farm","Cost":"Cold-chain freight, CITES paperwork, distributor margins"}}]},"climate":{"title":"Climate and supply shock","date":"","rows":[{"section":"The register: exposed markets","cells":{"Driver":"Water quality and temperature on farms; 8–10 years to first yield","Event":"Biomass valued at a falling price; the product clears within weeks of harvest","Storable":"No; the farm is the holding"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Living / perishable","Where":"The sturgeon farm; tins sold within months under cold chain","Cost":"Eight to ten years of farm costs before first yield; cold-chain freight and CITES paperwork","Fails":"Biomass valued at a falling price; the product is perishable"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Counterparty","Route":"Sale of the farm or a stake to a trade buyer or private equity; fish stock to another farm. The tin itself is perishable","Open":"On request; no listed pure play","Liquidity":"Low"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"Medium–High","Regime":"Dealer quote","Who":"Farm-to-importer contracts; Kaluga Queen as the largest producer, private"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"High","Claim":"Species, wild or farmed, origin","Verifier":"CITES labelling on every tin; DNA testing where disputed"}}]},"sanctions":{"title":"Sanctions, tariffs and origin","date":"","rows":[{"section":"The register: live measures","cells":{"Instrument":"Species listing","Measure":"CITES labelling on every tin; the only luxury food with a mandatory international chain-of-custody label","Effect":"Paperwork on every sale; the page records evidence the label is routinely defeated"}}]},"substitutes":{"title":"Synthetic and substitute pressure","date":"","rows":[{"section":"Substitutes by sector","cells":{"Substitute":"Farmed sturgeon; wild trade under CITES control since 1998. The sector page rates farmed scarcity Low and wild High","Stage":"Complete","Pressure":"The whole legal market is now farmed; the substitute became the product","Survives":"Wild caviar as a legal rarity; the farm, not the tin, as the holding"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"A farm company; fish are livestock; the tin is trading stock under CITES labelling","UK":"Share rates on a company sale; income on product","US":"Share rates; CITES Appendix II permits and the universal labelling system on every tin"}}]}}},"champagne":{"slug":"champagne","name":"Champagne","family":"Cellar & Collectibles","grade":4,"label":"Accessible","rated":"Physical, in bond","asof":"20 Oct 2026","method":"v1.2","axes":{"concentration":{"s":5,"band":"High","q":"LVMH houses, a regulated appellation, yield set annually"},"liquidity":{"s":3,"band":"Medium","q":"exchange mid-prices, merchant market"},"scarcity":{"s":2,"band":"Low","q":"for the category, high for named vintages"},"provenance":{"s":2,"band":"Low","q":"in bond; medium for older bottles"}},"factors":{"Valuation":4,"Exit":3,"Custody":4,"Title and transfer":4,"Access":4,"Intangible premium":3},"horizon":{"big":"5–10 years","text":"Prestige cuvées are released six to ten years after harvest and continue to improve in bottle; merchants typically cite a five- to ten-year hold from release. The 2022–25 correction shows the horizon can be set by the cycle rather than the cellar: the Champagne 50 fell about 35% over 31 months from its October 2022 peak."},"exit":{"routes":"Sale through a merchant onto Liv-ex, which trades only between professionals; merchant buy-back or brokerage; auction; iDealwine in Paris for grower labels.","activity":"Champagne was 12.4% of Liv-ex trade by value in Q2 2026, up from 10.9% in Q1 and just below its 2025 average of 12.8%. Across the exchange the bid:offer ratio reached 1.1 in Q1, its highest since October 2022, and 62% of trades were buyer-initiated.","cost":"Merchant commission on sale, typically 10% or more, plus exchange fees charged per unit and not published; storage of a few pounds a case a year in bond. Bottles removed from bond lose verifiable provenance and resell at a discount.","time":"Wine already in the exchange's bonded warehouse changes hands without moving and title passes at once; from a private cellar, weeks to receive, inspect and list. Payment terms follow the merchant."},"why":"Champagne is the most legible of the collectible drinks. Liv-ex publishes a daily index of fifty prestige cuvées and mid-prices for each; bottles are held in bond in a merchant's warehouse with the owner's name on the record; exit is to the merchant or through the exchange in weeks; and the asset is a branded, dated, sealed object whose authenticity is rarely in question. The one material limit is the one Fine Wine carries: transaction costs, 10% or more on each trade and storage of a few pounds a case a year, which on a product that has just fallen a third is the whole return of several years. The houses also set release prices and yields, so the holder's scarcity is partly the producer's decision.","regime":"Three years of correction have taken a third off the prestige index and a sixth off release prices; the houses have cut the 2026 yield to the lowest since the pandemic, and the index has stopped falling.","regimeAsOf":"20 Oct 2026","since":"First entry. The Comité Champagne capped the 2026 marketable yield at 8,800 kg/ha, about 250 m bottles, the lowest since 2020; first-half 2026 shipments were 107.1 m bottles, up 1.2%; the Liv-ex Champagne 50 is up 1.7% from its August 2025 low after falling 4.2% in 2025.","themes":["provenance","climate","custody","tax","access","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"fine-wine","name":"Fine Wine","why":"Shares the Liv-ex route"},{"slug":"port","name":"Port","why":"House and appellation"},{"slug":"scotch-whisky","name":"Scotch Whisky","why":"Brand-owner pricing"}],"sources":25,"url":"/champagne-dashboard","exitLabel":"bottles in bond","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"Yes: in bond","Wrappers":"As for wine; LVMH equity as a diluted proxy","Owns":"Bottles in bond"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Both","Faces":"Merchant onto Liv-ex; merchant buy-back; auction; iDealwine for grower labels","Cost":"Merchant 10%+; exchange fee per unit"}}]},"climate":{"title":"Climate and supply shock","date":"","rows":[{"section":"The register: exposed markets","cells":{"Driver":"Frost, hail and mildew; yield fixed annually by the Comité before harvest","Event":"The marketable yield is a regulated response to the season; release prices fell a sixth in the 2022–25 correction","Storable":"Yes, in bond; prestige cuvées improve for years"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Vault or bond","Where":"Cases in bond","Cost":"A few pounds a case a year in bond; merchant commission 10%+ on sale","Fails":"Bottles out of bond repriced on condition"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Price list","Route":"Merchant onto Liv-ex; merchant buy-back; auction; iDealwine for grower labels","Open":"Daily, through a merchant","Liquidity":"Medium"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"High; LVMH houses, a regulated appellation, yield set annually","Regime":"Trade platform; Administered (yield)","Who":"Liv-ex Champagne 50; the Comité Champagne sets the annual yield, the houses set release"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"Low in bond; medium for older bottles","Claim":"Storage history of bottles out of bond","Verifier":"Bond record; merchant inspection on repricing"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"Bottles in bond: as for wine","UK":"Wasting in the ordinary case; duty on removal","US":"28%"}}]}}},"cigars":{"slug":"cigars","name":"Cigars","family":"Cellar & Collectibles","grade":2,"label":"Restricted","rated":"Boxes","asof":"5 Oct 2026","method":"v1.2","axes":{"concentration":{"s":5,"band":"High","q":""},"liquidity":{"s":2,"band":"Low","q":""},"scarcity":{"s":3,"band":"Medium","q":""},"provenance":{"s":4,"band":"High","q":""}},"factors":{"Valuation":2,"Exit":2,"Custody":2,"Title and transfer":3,"Access":2,"Intangible premium":2},"horizon":{"big":"5–15 years","text":"Boxes are bought at release and aged; the secondary market pays most for Cohiba three to ten years old and for discontinued limited editions. A box must be kept at 65–70% humidity throughout, so the horizon is bounded by the humidor as much as by the market."},"exit":{"routes":"Specialist auctions (C.Gars in London, Online Cigar Auctions, regional houses); private sale through the same dealers, who also buy outright; Habanos' own festival auction for humidors. No route for US sellers of Cuban product.","activity":"Online Cigar Auctions ran over 580 lots in March 2026; a box of 25 Cohiba Esplendidos made £1,600 and 25 Siglo VI £1,400 at a regional house in 2025. At the top, the Festival del Habano humidor auction took €16.25 m in 2026 with a €4.6 m record lot; Cohiba Behike 2010 box codes draw the most bids.","cost":"Auction seller's commission around 10–15% plus a buyer's premium of 15–25% that caps the hammer; dealer buy-in at a discount to retail; humidor storage and insurance throughout. Boxes without intact seals, bands and codes sell at a steep discount or not at all.","time":"Auctions run quarterly; consignment deadlines fall weeks ahead and payment follows the sale by about a month. A dealer purchase can settle in days at a lower price. Three to four months from decision to cash through auction."},"why":"Prices are set by Habanos list prices and grey-market dealers, with little secondary discovery. Boxes need humidity-controlled storage and are vulnerable to counterfeits. Sanctions and US import rules restrict who can buy and sell.","regime":"Habanos at record revenue on lower volume; a levelled boom now absorbing US tariffs.","regimeAsOf":"5 Oct 2026","since":"Re-checked 5 Oct 2026: no new Habanos sales or price data since the last update. Ratings unchanged.","themes":["provenance","climate","sanctions","custody","tax","access","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"scotch-whisky","name":"Scotch Whisky","why":"Monopoly supply, ageing"},{"slug":"pu-erh-tea","name":"Pu-erh Tea","why":"Aged, vintage-dated"},{"slug":"fine-wine","name":"Fine Wine","why":"Collector cellars"}],"sources":40,"url":"/cigars-dashboard","exitLabel":"boxes","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"Yes: boxes","Wrappers":"Allied Cigar Fund holds 57.1% of one Habanos shareholder; private, and sanctioned","Owns":"A stake in the monopoly, not cigars"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Both","Faces":"C.Gars and Online Cigar Auctions; the same dealers buy outright","Cost":"Seller 10–15%, buyer 15–25%; dealer buy-in at a discount to retail"}}]},"climate":{"title":"Climate and supply shock","date":"","rows":[{"section":"The register: exposed markets","cells":{"Driver":"Cuban hurricanes and rain; wrapper leaf shortage","Event":"2025–26 planting target of 12,152 ha missed, cut in September for rain; record revenue on lower volume","Storable":"Yes, in a humidor, for decades"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Conditioned","Where":"Boxes in a humidor at 65–70% humidity","Cost":"Humidor storage and insurance throughout","Fails":"Boxes without intact seals, bands and codes sell at a steep discount or not at all"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Calendar auction","Route":"Specialist auctions (C.Gars, Online Cigar Auctions); dealers who buy outright. No route for US sellers of Cuban product","Open":"Several sales a year","Liquidity":"Low"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"High","Regime":"Administered (release); Calendar auction","Who":"Habanos S.A. sets release and allocation; specialist auctions for aged boxes"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"High","Claim":"Counterfeit boxes; storage history","Verifier":"Habanos seals and box codes; specialist auction inspection"}}]},"sanctions":{"title":"Sanctions, tariffs and origin","date":"","rows":[{"section":"The register: live measures","cells":{"Instrument":"Sanction (embargo)","Measure":"US import rules restrict who can buy and sell Cuban product","Effect":"No route for US sellers of Cuban cigars; the market is Europe, Hong Kong and the Gulf"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"Boxes, duty-paid or in bond: chattel; the Allied fund stake is a sanctioned security","UK":"CGT above £6,000; tobacco duty and 20% VAT on import; the house's cost of carry is the duty","US":"Cuban cigars cannot lawfully be bought or sold (see Sanctions)"}}]}}},"classic-cars":{"slug":"classic-cars","name":"Classic Cars","family":"Cellar & Collectibles","grade":3,"label":"Specialist","rated":"Physical","asof":"5 Oct 2026","method":"v1.2","axes":{"concentration":{"s":1,"band":"Low","q":""},"liquidity":{"s":3,"band":"Medium","q":""},"scarcity":{"s":4,"band":"High","q":"top); Low (base)"},"provenance":{"s":3,"band":"Medium","q":""}},"factors":{"Valuation":3,"Exit":3,"Custody":2,"Title and transfer":3,"Access":3,"Intangible premium":2},"horizon":{"big":"5–15 years","text":"Transaction costs of 20% or more round-trip and running costs of several per cent a year make anything under five years a losing hold unless the model is re-rated. Collectors describe holding periods of a decade or more; the 2026 Monterey results show value migrating by buyer cohort, so the horizon that matters is a generation."},"exit":{"routes":"Consignment to a live auction (RM Sotheby's, Gooding, Bonhams, Broad Arrow) on a fixed calendar; online auction (Bring a Trailer, Collecting Cars) for sub-$500k cars; dealer purchase or brokered private sale; sealed-bid sales for the rarest cars.","activity":"Monterey week 2026 grossed a record $755.6 m across five houses with eleven eight-figure lots; the rest of the year is a dozen comparable sales worldwide. Below the top, online platforms list thousands of cars a month but each model trades a handful of times a year.","cost":"RM Sotheby's charges the seller 10% of hammer and the buyer 12% to $250,000 and 10% above in the US (15%/12.5% plus VAT in Europe); the buyer's premium comes out of what the seller can achieve. Transport, detailing, pre-sale mechanical work and reserve negotiation sit on top; a withdrawn car still pays fees.","time":"Consignment closes six to twelve weeks before the sale; sale proceeds are paid within about 30 business days of settlement. From decision to cash, three to six months at a major house; a dealer sale is faster at a wider discount."},"why":"Auction results give periodic price points for top models; most cars lack comparables. Storage, insurance and maintenance are costly and specialised. Exit through scheduled auctions takes months.","regime":"Post-war \"boomer\" segment softening while modern supercars rise; auction totals flat.","regimeAsOf":"5 Oct 2026","since":"Re-checked 5 Oct 2026: no major auction since Monterey Car Week, which is already recorded here. Ratings unchanged.","themes":["provenance","custody","tax","access","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"watches","name":"Watches","why":"Condition, originality, auction"},{"slug":"vintage-guitars","name":"Vintage Guitars & Instruments","why":"Original parts set the value"},{"slug":"art","name":"Art","why":"Same auction houses"}],"sources":14,"url":"/classic-cars-dashboard","exitLabel":"physical","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"Yes","Wrappers":"Fractional platforms (Rally began with cars); winding down in 2026 (Section IV)","Owns":"A series in one car"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Auction-led; online auction below $500k","Faces":"RM Sotheby's, Gooding, Bonhams, Broad Arrow on the calendar; Bring a Trailer and Collecting Cars online; dealers for consignment","Cost":"Seller 10%; buyer 12% to $250,000 in the US, 15% plus VAT in Europe"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Conditioned","Where":"A climate-controlled garage; driven or exercised","Cost":"Storage, insurance and maintenance, several per cent a year","Fails":"Anything under five years a losing hold unless the model is re-rated"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Calendar auction","Route":"Live auction on a fixed calendar (RM Sotheby's, Gooding, Bonhams, Broad Arrow); online auction below about $500k; dealer or sealed bid","Open":"Monterey, Scottsdale, Paris, Goodwood; online weekly","Liquidity":"Medium"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"Low","Regime":"Calendar auction","Who":"Monterey, Scottsdale and Paris hammers; online auctions below about $500k"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"Medium","Claim":"Matching numbers; continuous history; rebodied cars","Verifier":"Factory build records, marque registries, specialist inspection"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"Machinery: wasting chattel","UK":"CGT-exempt; vehicles over forty years old exempt from vehicle excise duty and MOT; 5% import VAT for collectors' vehicles meeting the historic test","US":"28%; 2.5% duty on cars over 25 years old, exempt from safety and emissions rules at that age"}}]}}},"cocoa":{"slug":"cocoa","name":"Cocoa","family":"Crops","grade":4,"label":"Accessible","rated":"Route: futures","asof":"19 Oct 2026","method":"v1.2","axes":{"concentration":{"s":5,"band":"High","q":"marketing boards"},"liquidity":{"s":5,"band":"High","q":""},"scarcity":{"s":1,"band":"Low","q":""},"provenance":{"s":3,"band":"Medium","q":""}},"factors":{"Valuation":5,"Exit":4,"Custody":5,"Title and transfer":4,"Access":3,"Intangible premium":5},"horizon":{"big":"Contract-bounded","text":"Five delivery months a year (March, May, July, September, December); a position is rolled into the next one or delivered. Index funds roll on a fixed calendar, so the roll, not the crop, sets the return on any hold beyond one contract."},"exit":{"routes":"Close or roll ICE New York (US$/t) or ICE London (£/t) futures and options; a handful of ETFs and ETCs. Physical beans are deliverable only through exchange-licensed warehouses, a trade-house business.","activity":"New York December cocoa traded 25,904 lots on 8 September 2026 and around 17,000–20,000 lots on ordinary days; each lot is 10 t. ICE-certified stocks were 3.41 m bags on 1 September, a two-year high.","cost":"Exchange and clearing fees per lot, broker commission and margin; initial margin on the New York contract was about $9,500 a lot in October 2026, a fifth of contract value. The roll is paid each delivery month.","time":"Exit at the next trade during exchange hours; the position is marked and cleared the same day."},"why":"ICE London and New York futures give continuous pricing and liquid exit. Marketing boards in Côte d'Ivoire and Ghana set farm-gate prices and forward-sell the crop, which shapes the futures curve. Roll costs and extreme volatility are the limits.","regime":"Demand has turned before supply: Q3 grindings rose in Europe and Asia, the two largest regions, for the first time since 2024, while El Niño and a smaller Ivorian crop loom. Futures hold near $5,600, double the April low.","regimeAsOf":"19 Oct 2026","since":"Q3 grindings (15 Oct): Europe +3.2%, the first year-on-year gain in any quarter since 2024; Asia +29% to a record 233,767 t; Ivorian exporters +40%. New York December closed $5,645 on 16 Oct, −4% on the year but 98% above the April low; ICE certified stocks at a 2.25-year high of 3.54 m bags cap rallies. Ghana opened its season on 25 Sep at 42,400 cedis/t (~$3.65/kg), 75% above Ivory Coast's 1,200 CFA, breaking the June harmonisation pledge, and sold its first cocoa bills since default at 11%.","themes":["provenance","substitutes","climate","custody","tax","access","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"coffee","name":"Coffee","why":"Futures, origin premium"},{"slug":"vanilla","name":"Vanilla","why":"Tropical crop, farmgate"},{"slug":"olive-oil","name":"Olive Oil","why":"Weather-driven supply"}],"sources":24,"url":"/cocoa-dashboard","exitLabel":"futures","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"No","Wrappers":"Futures; a handful of ETFs and ETCs","Owns":"Contracts; the roll sets the return"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Exchange","Faces":"ICE through a broker","Cost":"Fees, margin, the roll"}}]},"climate":{"title":"Climate and supply shock","date":"","rows":[{"section":"The register: exposed markets","cells":{"Driver":"West African rainfall, El Niño, swollen-shoot virus, black pod, tree age","Event":"2023/24 deficit of 489–492 kt, the crisis year; a 2024/25 surplus published at four different figures; the El Niño emerging Sept 2026 \"likely among the strongest in 75 years\"","Storable":"Beans yes, in exchange warehouses; a holder is in futures and pays the roll"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Paper","Where":"Futures; beans only in exchange-licensed warehouses","Cost":"Initial margin about $9,500 a lot (a fifth of value); the roll each delivery month","Fails":"Physical is a trade-house business"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Benchmark","Route":"Close or roll ICE New York or London futures; a few ETCs","Open":"Daily","Liquidity":"High"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"High, marketing boards","Regime":"Exchange (world); Administered (farm gate)","Who":"ICE New York and London; the Conseil Café-Cacao and Cocobod set the farm-gate price for the two largest origins"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"Medium","Claim":"Origin and deforestation status of beans","Verifier":"Exchange-licensed warehouses grade deliverable beans; origin traceability is the trade's"}}]},"substitutes":{"title":"Synthetic and substitute pressure","date":"","rows":[{"section":"Substitutes by sector","cells":{"Substitute":"Cocoa-free chocolate from fermented oats, sunflower or grape seed: Voyage Foods ($94m raised; Cargill as exclusive B2B distributor), Planet A Foods ($30m Series B, Dec 2024; capacity 2,000 t rising to 15,000 t)","Stage":"Early","Pressure":"Compound coatings, inclusions and fillings, where cocoa is a cost line; 15,000 t against a world crop measured in millions of tonnes","Survives":"Fine-flavour and single-origin cocoa; the futures market is unaffected so far"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"Futures; ETC","UK":"CGT on futures and ETCs","US":"Section 1256; physical beans are trading stock of a licensed warehouse account"}}]}}},"coffee":{"slug":"coffee","name":"Coffee","family":"Crops","grade":4,"label":"Accessible","rated":"Route: futures","asof":"19 Oct 2026","method":"v1.2","axes":{"concentration":{"s":3,"band":"Medium","q":""},"liquidity":{"s":5,"band":"High","q":""},"scarcity":{"s":1,"band":"Low","q":"Geisha High"},"provenance":{"s":3,"band":"Medium","q":""}},"factors":{"Valuation":5,"Exit":4,"Custody":5,"Title and transfer":4,"Access":3,"Intangible premium":4},"horizon":{"big":"Contract-bounded","text":"Arabica (37,500 lb) and robusta (10 t) futures expire five times a year and are rolled or delivered; index funds roll on a published five-day window. Any hold beyond a contract is a sequence of rolls priced off the spread, which stood at a 31 c premium for the nearby in August 2026."},"exit":{"routes":"Close or roll ICE arabica (New York) or robusta (London) futures and options; a small number of coffee ETCs. Physical green coffee exits through exporters and trade houses, not a portfolio route.","activity":"ICE arabica traded 37,307 lots and robusta 38,611 on 20 October 2026; the quietest arabica session of the year was just over 17,000 lots on 6 April. ICE-certified arabica stocks fell to 226,242 bags in August, near a 27-year low.","cost":"Exchange and clearing fees per lot, broker commission and margin. With certified stocks this thin, the nearby spread has carried a steep backwardation, which pays a long roll but punishes any delivery-month squeeze.","time":"Exit at the next trade during exchange hours; cleared the same day."},"why":"ICE arabica and robusta futures give continuous pricing and quick exit. Roll costs and weather-driven volatility are the limits, and the futures do not track specialty lots. Green coffee itself is not a portfolio holding.","regime":"A surplus year priced like a shortage: record Brazilian and world crops, yet ICE certified stocks near a 27-year low keep arabica above $3 into the December expiry.","regimeAsOf":"19 Oct 2026","since":"Arabica settled $3.056/lb on 16 Oct, a one-month high, as ICE certified stocks sat at 238,976 bags against last month's 27-year low of 217,646 and dealers doubted Brazilian coffee would reach warehouses before the December expiry. Supply is the opposite story: Conab lifted Brazil's 2026 crop to 67.6 m bags with arabica 48.2 m (+35%), above USDA for the first time, and USDA sees a record 189.7 m-bag world crop in 2026/27. The tariff row carried here since launch is corrected below: coffee was exempted from the 50% Brazil tariff on 20 Nov 2025.","themes":["provenance","substitutes","climate","sanctions","custody","tax","access","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"cocoa","name":"Cocoa","why":"Futures, grade and origin"},{"slug":"tea","name":"Tea","why":"Auction-priced leaf"},{"slug":"vanilla","name":"Vanilla","why":"Specialty origin premium"}],"sources":27,"url":"/coffee-dashboard","exitLabel":"futures","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"No","Wrappers":"Futures; a small number of ETCs","Owns":"Contracts; futures do not track specialty lots"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Exchange","Faces":"ICE through a broker; physical lots to exporters","Cost":"Fees, margin; specialty lots do not track the contract"}}]},"climate":{"title":"Climate and supply shock","date":"","rows":[{"section":"The register: exposed markets","cells":{"Driver":"Brazilian drought and heat; frost; Vietnamese rainfall for robusta","Event":"Arabica to an all-time record Oct 2025, then −38%; Brazil arabica down 6m bags on drought and heat in Minas Gerais and São Paulo; five years of falling stocks","Storable":"Green coffee yes, through trade houses; futures for a portfolio"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Paper","Where":"Futures; green coffee through trade houses","Cost":"Exchange fees and margin; steep backwardation pays a long roll","Fails":"Delivery-month squeezes when certified stocks are thin"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Benchmark","Route":"Close or roll ICE arabica or robusta futures; a few ETCs","Open":"Daily","Liquidity":"High"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"Medium","Regime":"Exchange","Who":"ICE arabica and robusta; specialty lots priced by cupping score and direct contract"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"Medium","Claim":"Origin and grade of specialty lots","Verifier":"Exchange grading for deliverable coffee; cupping and farm records for specialty"}}]},"sanctions":{"title":"Sanctions, tariffs and origin","date":"","rows":[{"section":"The register: live measures","cells":{"Instrument":"Tariff","Measure":"50% US tariff on Brazilian goods; coffee exempted on 20 Nov 2025","Effect":"Four months of re-routing and a correction on the sector page"}}]},"substitutes":{"title":"Synthetic and substitute pressure","date":"","rows":[{"section":"Substitutes by sector","cells":{"Substitute":"Beanless coffee from date seeds, chicory and upcycled plant matter: Atomo (founded 2019; $7.8m Series B, Jan 2025; sold as a 50:50 blend with arabica)","Stage":"Early","Pressure":"Trade commentary: rising interest, \"no threat\" to consumption yet; the industry frames it as a hedge against arabica supply loss by 2050","Survives":"Specialty and origin coffee; Geisha, which the sector page rates High"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"Futures; ETC","UK":"CGT","US":"Section 1256; specialty lots are an exporter's trading stock"}}]}}},"coins":{"slug":"coins","name":"Coins","family":"Cellar & Collectibles","grade":3,"label":"Specialist","rated":"Numismatic coins, certified","asof":"19 Oct 2026","method":"v1.2","axes":{"concentration":{"s":1,"band":"Low","q":""},"liquidity":{"s":3,"band":"Medium","q":"common certified coins High"},"scarcity":{"s":4,"band":"High","q":"at the apex; fixed stock"},"provenance":{"s":2,"band":"Low","q":"for slabbed; Medium for raw and ancients"}},"factors":{"Valuation":3,"Exit":3,"Custody":5,"Title and transfer":4,"Access":4,"Intangible premium":2},"horizon":{"big":"5–10 years · slabbed","text":"Certified coins trade sight-unseen against published bid prices, so the holding period is a choice rather than a constraint; collectors and funds cite five to ten years to clear the auction round trip. Bullion-grade coins track the metal day to day. Rarities are held for a generation and priced by the one or two bidders present when they surface."},"exit":{"routes":"Heritage Auctions (over 200,000 numismatic lots a year, weekly online sales plus Signature floor sales), Stack's Bowers, Legend and GreatCollections; dealer networks bidding on the CDN Greysheet; Heritage's fixed-price \"Buy Now\" inventory with no premium. Bullion coins to any dealer at spot plus or minus.","activity":"Heritage handles over $1 bn of numismatic sales a year within $1.87 bn of total 2024 sales, with a free archive of past results that functions as the market's price database. PCGS and NGC population reports count every graded example. Two 1804 dollars and a 1794 dollar made $4.5–6 m each in the past year.","cost":"Heritage raised its US-coin buyer's premium to 22% (minimum $29) from 1 January 2026 and Stack's Bowers matched from 1 April; seller's commission runs 10% on ordinary consignments to zero, or a rebate of the premium, above about $250,000. Dealer bid–ask on common certified coins is a few per cent; grading fees and CAC stickers on top.","time":"Dealer sale: same day at bid. Heritage weekly online sales close within days of consignment; Signature sales are scheduled monthly; settlement 45–60 days after the sale at Heritage, 60–90 at Stack's Bowers."},"why":"Third-party grading gives most US and many world coins something no other collectible has: a sealed, numbered, population-tracked unit that trades sight-unseen against published price guides. For those coins exit is days through a dealer or weeks through a major auction. The grade is the limit: a rarity's value is set by one or two bidders, the slab records an opinion not a fact, and the grading companies' own re-grades move prices. Ancients and raw coins carry the usual authentication and, increasingly, export-law risk.","regime":"The most liquid of the collecting markets, lifted by the gold price beneath it: two 1804 dollars and a 1794 dollar made $4.5–6 m each in the past year, and third-party grading has made a coin in a slab almost a commodity.","regimeAsOf":"19 Oct 2026","since":"First entry. Stack's Bowers sold the James A. Stack 1804 dollar for $6 m in December 2025 and a 1794 Flowing Hair dollar for $4.5 m in November; A-Mark Precious Metals completed its acquisition of Stack's Bowers in 2025, putting the second-largest numismatic auctioneer inside a bullion dealer. All eleven government-held 1933 Double Eagles were shown together at the ANA in Pittsburgh in 2026.","themes":["provenance","sanctions","custody","tax","access","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"stamps","name":"Stamps","why":"Graded, slabbed, catalogued"},{"slug":"gold","name":"Gold","why":"Bullion value floor"},{"slug":"rare-books","name":"Rare Books","why":"Rarity by census"}],"sources":11,"url":"/coins-dashboard","exitLabel":"certified numismatic coins","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"Yes: slabbed","Wrappers":"Funds exist and cite five-to-ten-year holds; bullion coins track metal ETFs","Owns":"A manager's selection of certified coins"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Both: auction for certified rarities, dealers for the rest","Faces":"Heritage (200,000+ lots a year), Stack's Bowers, GreatCollections; dealer networks buying at bid","Cost":"Buyer 22% at Heritage from Jan 2026; seller 10% on ordinary coins, negotiable above"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Shelf","Where":"Slabbed, in a safe or bank box","Cost":"Grading fees and CAC stickers; insurance","Fails":"Raw coins carry the authentication risk the slab removes"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Price list","Route":"Heritage (weekly online, 200,000+ lots a year), Stack's Bowers, GreatCollections; dealers bidding on the CDN Greysheet","Open":"Weekly; sight-unseen for certified coins","Liquidity":"Medium; common certified coins High"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"Low","Regime":"Trade platform","Who":"CDN Greysheet dealer bids for certified coins; Heritage hammers for rarities; the metal price for bullion grades"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"Low for slabbed; Medium for raw and ancients","Claim":"Raw coins: authenticity and grade. Ancients: export law","Verifier":"PCGS and NGC slabbing, with population reports; nothing comparable for raw coins"}}]},"sanctions":{"title":"Sanctions, tariffs and origin","date":"","rows":[{"section":"The register: live measures","cells":{"Instrument":"Export control (cultural property)","Measure":"Ancients subject to cultural-property claims, US State Department MoUs and import restrictions","Effect":"Title risk and seizure on raw and ancient coins; none on slabbed modern coins"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"Sterling legal tender: currency. Other coins: chattel","UK":"Sovereigns and Britannias CGT-exempt whatever the numismatic premium; a 1933 double eagle is a chattel; investment gold coins VAT-exempt","US":"28% on all; dealer sales over $10,000 cash reported on Form 8300"}}]}}},"coloured-gemstones":{"slug":"coloured-gemstones","name":"Coloured Gemstones","family":"Gems & Jewellery","grade":2,"label":"Restricted","rated":"Physical stones","asof":"19 Oct 2026","method":"v1.2","axes":{"concentration":{"s":3,"band":"Medium","q":"High, by stone"},"liquidity":{"s":2,"band":"Low","q":""},"scarcity":{"s":4,"band":"High","q":"top origins"},"provenance":{"s":4,"band":"High","q":""}},"factors":{"Valuation":1,"Exit":2,"Custody":4,"Title and transfer":2,"Access":2,"Intangible premium":2},"horizon":{"big":"10+ years · stones","text":"Fine rubies, sapphires and emeralds are bought for decades and resold through the same two or three auction houses; between sales there is no price. Rough from the mine turns over in weeks through Gemfields' sealed-bid auctions, but that market is open only to licensed cutters. The private holder's horizon is the gap between appearances of a comparable stone."},"exit":{"routes":"Christie's, Sotheby's and Phillips jewellery sales in Geneva, Hong Kong and New York for stones over about $50,000, each with a fresh laboratory report; specialist dealers in Bangkok, Geneva and New York who buy or consign; trade fairs. Rough: Gemfields' auctions, cutters only.","activity":"Gemfields sold 92,153 ct of mixed-quality Montepuez ruby for $52.0 m at $564.54/ct on 5–16 October 2026 (90.9% of lots) and 3.05 m ct of commercial Kagem emerald for $29.6 m at a record $9.72/ct in September, all lots sold, 63 bidders. At the top, a 5.07 ct Burmese ruby ring made HK$18.2 m in Hong Kong in May against a HK$9.6–15 m estimate.","cost":"Auction: seller's commission around 10%, a buyer's premium of 28% on the first $2 m that caps the hammer, and a lab report (SSEF, Gübelin, GRS) at $500–3,000 a stone, which may come back with a different origin or treatment finding than the last one. Dealer buy-in at a third to a half below retail.","time":"Two marquee seasons a year (May, November); consignment closes two to three months before and payment follows 35–45 days after. A dealer sale in days at the dealer's price. Lab testing two to six weeks."},"why":"No benchmark exists; each stone is priced by origin, treatment and laboratory report, and reports can disagree. Exit means a specialist auction or a dealer, over months. Title depends on documented origin and treatment disclosure, which is often incomplete.","regime":"Rough ruby clears at $565/ct and emerald at a record, yet the miner that sets both prices is short of cash: supply tightness and producer fragility in the same quarter.","regimeAsOf":"19 Oct 2026","since":"Gemfields' October mixed-quality ruby auction (5–16 Oct, results 19 Oct) made $52.0m: 90 of 99 lots and 92,153 of 102,099 carats sold at an average $564.54/ct, against 189,620 carats sold in February. The proceeds are described as needed to keep Montepuez operating through \"significant operational and financial constraints\": premium grades at Mugloto fell to 0.02 ct/t in early 2026 and $28.3m of VAT refunds are outstanding. Gemfields' H1 2026 results (30 Sep) carried a $125.2m impairment and a material uncertainty over MRM as a going concern; CEO Sean Gilbertson is stepping down. Kagem's August–September emerald sale had set a record $9.72/ct.","themes":["provenance","substitutes","sanctions","custody","tax","access","tokenisation","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"polished-diamonds","name":"Polished Diamonds","why":"Graded stones, dealer exit"},{"slug":"jade","name":"Jade","why":"Origin and treatment disputes"},{"slug":"signed-jewellery","name":"Signed Jewellery","why":"Where the stones end up"},{"slug":"pearls","name":"Pearls","why":"Laboratory report as title"}],"sources":38,"url":"/coloured-gemstones-dashboard","exitLabel":"physical stones","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"Yes: a stone","Wrappers":"Gemfields equity (the rough miner, short of cash); tokens proposed, not launched","Owns":"A miner's balance sheet"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Both: threshold about $50,000","Faces":"Christie's, Sotheby's and Phillips above it, each with a fresh lab report; specialist dealers below","Cost":"Seller around 10%; buyer 28% on the first $2 m; lab report $500–3,000"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Shelf","Where":"A stone, in a safe, with its last report","Cost":"A fresh laboratory report at $500–3,000 at each sale","Fails":"The new report may differ from the old on origin or treatment"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Calendar auction","Route":"Geneva, Hong Kong and New York jewellery sales for stones over about $50,000, each with a fresh laboratory report; dealers below","Open":"Twice a year per city","Liquidity":"Low"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"Medium–High, by stone","Regime":"Calendar auction (polished); Administered (rough)","Who":"Geneva and Hong Kong hammers for the top; Gemfields' sealed-bid rough auctions, open to licensed cutters only"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"High","Claim":"Origin and treatment, both expert opinions","Verifier":"SSEF, Gübelin, GRS, GIA at $500–3,000 a report; a fresh report expected at each sale; reports can disagree"}}]},"sanctions":{"title":"Sanctions, tariffs and origin","date":"","rows":[{"section":"The register: live measures","cells":{"Instrument":"Tariff","Measure":"2025 decline in US imports read as tariff-related front-loading into 2022–24","Effect":"Timing of imports, not the route; Burmese origin carries its own US history of restriction"}}]},"substitutes":{"title":"Synthetic and substitute pressure","date":"","rows":[{"section":"Substitutes by sector","cells":{"Substitute":"Flame-fusion synthetic ruby and sapphire, commercial since the early 1900s; flux and hydrothermal emerald, ruby and sapphire since mid-century. Lab-grown stones \"exist and trade freely, but have not displaced the natural market\"","Stage":"Latent, a century on","Pressure":"Uncertified commercial stones; one dealer puts the exposed range at $500–3,000 a carat","Survives":"Everything with an origin report. Coloured stones were always priced on origin, so the synthetic never had a commodity tier to take"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"Stone: chattel; Gemfields: equity","UK":"CGT above £6,000; 20% VAT on purchase","US":"28%; Mozambique, Zambia: export royalties; Thailand and Sri Lanka: import of rough duty-free for cutting"}}]}}},"copper":{"slug":"copper","name":"Copper","family":"Metals, Energy & Strategic Materials","grade":4,"label":"Accessible","rated":"Route: futures","asof":"19 Oct 2026","method":"v1.2","axes":{"concentration":{"s":5,"band":"High","q":"refining (mine Medium)"},"liquidity":{"s":5,"band":"High","q":""},"scarcity":{"s":3,"band":"Medium","q":""},"provenance":{"s":1,"band":"Low","q":""}},"factors":{"Valuation":5,"Exit":4,"Custody":5,"Title and transfer":4,"Access":3,"Intangible premium":5},"horizon":{"big":"Contract-bounded","text":"A futures position has no fixed life but must be rolled: LME prompts run daily to three months, weekly to six and monthly to ten years. A holding of any length is a sequence of contracts, and each roll pays or earns the shape of the curve."},"exit":{"routes":"Close or roll LME or COMEX futures; sell ETF units; physical cathode only by warrant and warehouse, impractical for portfolios.","activity":"LME copper traded over 170,000 lots a day in 2025 and 168,000 in Q2 2026, at 25 t a lot. LME average daily volume January–September 2026 was 16% above the prior year.","cost":"Exchange and clearing fees per lot, broker commission and margin funding. The material cost is the roll, paid on every prompt in contango; the COMEX–LME arbitrage gap was near 14 c/lb in Q2.","time":"Exit at the next trade in a continuous market; LME cash settles on a prompt two business days forward."},"why":"Exposure runs through LME and COMEX futures or ETFs, which are priced continuously and exit within days. Holding through futures carries roll costs and contango risk, the one material limit. Physical cathode is impractical for most portfolios.","regime":"ICSG has swung back to a 2026 surplus, yet the price holds within 5% of its September record: the metal is plentiful in the wrong country. Grasberg's full return has slipped to 2028.","regimeAsOf":"19 Oct 2026","since":"ICSG's 14 October forecast puts 2026 in a 104 kt surplus and 2027 at 368 kt; its April revision to surplus was missed at launch and the −150 kt headline carried here is corrected below. LME three-month $14,407.50 on 16 Oct and COMEX $6.56/lb, +32% on the year and ~5% below the 9 Sep record. The US refined-cathode tariff decision lapsed on 28 Sep with no announcement; the COMEX premium has collapsed from over $3,000/t to ~$310 while US warehouses hold ~70% of visible exchange stock. Grasberg's mill is at 67%; full capacity is now early 2028.","themes":["provenance","sanctions","custody","tax","access","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"gold","name":"Gold","why":"Exchange-traded metal"},{"slug":"rare-earths","name":"Rare Earths","why":"Energy-transition metal"},{"slug":"uranium","name":"Uranium","why":"Mine supply and contracts"}],"sources":36,"url":"/copper-dashboard","exitLabel":"futures","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"Impractical","Wrappers":"Futures; ETFs","Owns":"Contracts or warranted cathode"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Exchange","Faces":"LME or COMEX through a broker","Cost":"Fees, commission, the roll"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Paper","Where":"Futures; ETF units; cathode by warrant only","Cost":"Exchange fees, margin, and the roll on every prompt in contango","Fails":"Physical cathode impractical for portfolios"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Benchmark","Route":"Close or roll LME or COMEX; ETF units","Open":"Daily","Liquidity":"High"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"High, refining (mine Medium)","Regime":"Exchange","Who":"LME, COMEX, SHFE trades"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"Low","Claim":"—","Verifier":"Exchange warrant and registered brand"}}]},"sanctions":{"title":"Sanctions, tariffs and origin","date":"","rows":[{"section":"The register: live measures","cells":{"Instrument":"Tariff (threatened)","Measure":"US refined-cathode tariff decision lapsed 28 Sep 2026 with no announcement; COMEX premium collapsed from over $3,000/t to about $310","Effect":"Metal pulled into US warehouses on the threat, then stranded; location became a price"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"Futures: derivative contract. ETF: security. Cathode: warranted chattel","UK":"CGT on futures for a non-trader; ETCs as debt securities","US":"Section 1256, 60% long and 40% short regardless of holding period"}}]}}},"dates":{"slug":"dates","name":"Dates","family":"Crops","grade":2,"label":"Restricted","rated":"Route: farms and private operators","asof":"5 Oct 2026","method":"v1.2","axes":{"concentration":{"s":3,"band":"Medium","q":""},"liquidity":{"s":2,"band":"Low","q":""},"scarcity":{"s":2,"band":"Low","q":"Ajwa Medium"},"provenance":{"s":3,"band":"Medium","q":""}},"factors":{"Valuation":2,"Exit":2,"Custody":3,"Title and transfer":2,"Access":2,"Intangible premium":3},"horizon":{"big":"7–10 years to full yield · farms","text":"A date palm fruits commercially from year five to seven and fully from ten, then for decades; the fruit itself is sold within the season or cold-stored for a year. The route is the farm, so the horizon is agricultural land in Saudi Arabia, Egypt or the Jordan valley, held for a generation."},"exit":{"routes":"Fruit: exporters and packers under seasonal contracts, the Buraidah and Madinah wholesale markets, retail brands at Ramadan. Farm: private sale of land and trees, usually to a local operator; no listed pure play of scale, and foreign ownership of Saudi farmland is restricted.","activity":"Saudi Arabia exported 351,489 t of dates worth US$452 m in 2024 from 1.93 m t produced; FAO farm-gate price about US$3.06/kg, export unit value US$1.29/kg. Medjool from Madinah farms lists at US$5–7/kg by grade; Ajwa retails at SR 100–150/kg in the Kingdom. Farm transactions are private.","cost":"Packer and exporter margins between farm gate and export; grading losses; cold storage if held past season. Farm sale: agent and transfer costs, and a buyer who will price trees on age and variety.","time":"Fruit: sold within weeks of harvest in September–October or on Ramadan demand. Farm: months to a year to find a buyer; valuation rests on yield records and water rights."},"why":"Prices are set by exporters and seasonal contracts with no benchmark. The route is farms and private operators, most of them unlisted. Exit means selling an operating business.","regime":"Commodity grades flat and export-led; premium varieties priced by name and origin.","regimeAsOf":"5 Oct 2026","since":"The 2026/27 season is opening with a ~3% larger global table-date crop (1.67 Mt, INC). Tunisia is up 14% and Israel down 21%. Saudi exports are forecast above 220,000 t. Commodity and mid-tier Medjool face price pressure from expanding Egyptian supply, while Super Jumbo grades stay firm; Israeli Medjool was €4.39/kg EXW Poland in late July.","themes":["provenance","climate","sanctions","custody","tax","access","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"saffron","name":"Saffron","why":"Gulf and Middle East trade"},{"slug":"olive-oil","name":"Olive Oil","why":"Harvest and grade"},{"slug":"manuka-honey","name":"Mānuka Honey","why":"Origin-certified food"}],"sources":21,"url":"/dates-dashboard","exitLabel":"farms and private operators","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"The farm, locally","Wrappers":"None listed of scale; state programmes (PIF's Al Madinah Heritage) are not investable","Owns":"—"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Administered","Faces":"Wholesale markets and state programmes; the farm sells locally","Cost":"Wholesale margin"}}]},"climate":{"title":"Climate and supply shock","date":"","rows":[{"section":"The register: exposed markets","cells":{"Driver":"Water scarcity and heat; a palm takes 5–10 years to full yield","Event":"Water scarcity and climate named as the binding constraints on c. 37m Saudi palms","Storable":"Fruit cold-stored for a year; the farm is the holding"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Living / perishable","Where":"The farm; fruit cold-stored for a year at most","Cost":"Cold storage if held past season; grading losses","Fails":"Foreign ownership of Saudi farmland restricted"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Counterparty","Route":"Farm: private sale of land and trees to a local operator. Fruit: packers and the Buraidah and Madinah markets","Open":"On request; foreign ownership restricted","Liquidity":"Low"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"Medium","Regime":"Calendar auction; Dealer quote","Who":"Buraidah and Madinah wholesale markets in season; packers under contract"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"Medium","Claim":"Variety (Ajwa) and origin","Verifier":"Packer and market inspection"}}]},"sanctions":{"title":"Sanctions, tariffs and origin","date":"","rows":[{"section":"The register: live measures","cells":{"Instrument":"Ownership restriction","Measure":"Foreign ownership of Saudi farmland restricted","Effect":"The farm route is closed to most outside holders"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"Farm: land","UK":"—","US":"Saudi Arabia: no personal income tax; zakat on Saudi-owned business; foreign ownership of farmland restricted"}}]}}},"fine-wine":{"slug":"fine-wine","name":"Fine Wine","family":"Cellar & Collectibles","grade":4,"label":"Accessible","rated":"Bottles in bond","asof":"5 Oct 2026","method":"v1.2","axes":{"concentration":{"s":1,"band":"Low","q":""},"liquidity":{"s":3,"band":"Medium","q":""},"scarcity":{"s":3,"band":"Medium","q":"top Burgundy High"},"provenance":{"s":3,"band":"Medium","q":""}},"factors":{"Valuation":4,"Exit":3,"Custody":4,"Title and transfer":4,"Access":4,"Intangible premium":3},"horizon":{"big":"3–7 years","text":"Cited as typical for investment-grade wine; one platform builds its models on four- to five-year horizons. Value can fall once a wine is held well past maturity."},"exit":{"routes":"Sale through a merchant on Liv-ex, which trades only between professionals; auction; private sale; fund terms where held through a fund.","activity":"620+ merchants in 47 countries; about £100m of firm bids and offers across 16,000+ wines. Source does not date the order-book figure.","cost":"Exchange fees are a flat charge per unit; the amount is not published. Wine that leaves bond loses verifiable provenance and resells at a discount.","time":"Wine in the exchange warehouse changes hands without moving, and title transfers at once. Private holders reach it only through a member merchant."},"why":"Liv-ex mid prices give regular, independent valuation for traded wines. Stock held in bond keeps provenance and avoids duty. Exit runs through merchants or the exchange rather than an open market, and each trade carries fees.","regime":"Post-2022 correction has run back to 2015 price levels; Liv-ex says wine \"hasn't been cheaper since 2014\" as supply and demand normalise.","regimeAsOf":"5 Oct 2026","since":"Liv-ex Fine Wine 1000 has returned to its 2020 low, at levels last seen in 2015. The brief late-2025 recovery has not carried through 2026.","themes":["provenance","climate","custody","tax","access","tokenisation","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"champagne","name":"Champagne","why":"Same route, same index"},{"slug":"port","name":"Port","why":"Declared vintages"},{"slug":"rare-whisky-casks","name":"Rare Whisky Casks","why":"Where the cask pitch differs"},{"slug":"scotch-whisky","name":"Scotch Whisky","why":"Bottled spirits market"}],"sources":63,"url":"/fine-wine-dashboard","exitLabel":"bottles in bond","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"Yes: cases in bond","Wrappers":"Wine funds (\"fund terms where held through a fund\"); platforms building on 4–5 year models","Owns":"Cases in bond, selected and sold by the manager"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Both","Faces":"A merchant onto Liv-ex (professionals only) for the ordinary case; Sotheby's, Christie's, Zachys for cellars and rarities","Cost":"Merchant commission 10%+; exchange fee per unit unpublished; auction around 10% plus premium"}}]},"climate":{"title":"Climate and supply shock","date":"","rows":[{"section":"The register: exposed markets","cells":{"Driver":"Vintage weather in Bordeaux and Burgundy; frost and hail","Event":"Vintage quality is the first price variable; the 2022–25 correction ran back to 2015 levels regardless","Storable":"Yes, in bond, for the life of the wine"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Vault or bond","Where":"Cases in a UK bonded warehouse, duty suspended","Cost":"Storage a few pounds a case a year; exchange fees per unit, not published","Fails":"Wine that leaves bond loses verifiable provenance and resells at a discount"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Price list","Route":"Merchant onto Liv-ex (professionals only); auction; private sale","Open":"Daily, through a merchant","Liquidity":"Medium"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"Low","Regime":"Trade platform","Who":"Liv-ex mid-price among 620+ merchants; release prices set by the château and the Bordeaux négoce"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"Medium","Claim":"Integrity once out of bond; counterfeit rarities","Verifier":"Bonded warehouse custody record; merchant inspection; wine that leaves bond resells at a discount"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"Cases in bond: duty-suspended chattel, generally wasting","UK":"CGT-exempt as a wasting asset in the ordinary case; HMRC reserves wines that will keep beyond fifty years; duty and VAT on removal from bond","US":"28% as a collectible (\"alcoholic beverages\" are listed); state excise on import. Hong Kong: no duty since 2008"}}]}}},"fossils":{"slug":"fossils","name":"Fossils & Meteorites","family":"Cellar & Collectibles","grade":2,"label":"Restricted","rated":"Mounted dinosaur skeletons; classified meteorites","asof":"19 Oct 2026","method":"v1.2","axes":{"concentration":{"s":1,"band":"Low","q":"dispersed finders, one dominant saleroom"},"liquidity":{"s":2,"band":"Low","q":""},"scarcity":{"s":5,"band":"High","q":"at the apex; finite but still being dug"},"provenance":{"s":5,"band":"High","q":""}},"factors":{"Valuation":1,"Exit":1,"Custody":2,"Title and transfer":2,"Access":3,"Intangible premium":1},"horizon":{"big":"Years · one department, one season","text":"A mounted dinosaur comes to market once; the three records since 2020 ($31.8 m, $44.6 m, $50.1 m) were each set by a different specimen sold by a single auction department in its July natural-history sale. Buyers are institutions and a handful of billionaires, so the holding period is whatever the next such buyer's appetite dictates. Meteorites follow the same calendar at a tenth of the price."},"exit":{"routes":"Sotheby's New York natural-history sale each July (Christie's and Bonhams occasionally); private sale to a museum or collector through the same specialists; dealer sale for smaller specimens. Title turns on which side of a US ranch fence the bones lay; meteorites need export clearance from the country of fall, which Niger is now contesting.","activity":"Sotheby's, 14 July 2026: \"Gus\" the T. rex $50.13 m after 19 bids from seven bidders in ten minutes, hammer $43 m against a $20–30 m estimate; a ceratosaur made seven times its low estimate in 2025 on six bidders, and Sotheby's reported a sharp rise in registrations. The NWA 16788 Martian meteorite made $5.3 m in July 2025 against $2–4 m.","cost":"Sotheby's buyer's premium of 28% on the first $2 m, 22% to $8 m and 15% above (Gus: $7.1 m of premium on a $43 m hammer) caps the hammer; seller's commission negotiable for a trophy; excavation, preparation and mounting run to years and seven figures before the sale; crating and transport of a 38 ft skeleton.","time":"One sale a year in July; consignment many months ahead to allow preparation and promotion; payment within 45 days of the sale subject to the buyer settling. A specimen that fails to sell waits a year or goes private."},"why":"There is no price series, no comparable set and no second saleroom of weight: value is what the last billionaire paid, and estimates have been wrong by a factor of ten in both directions. Exit is one New York sale a year. Title depends on which side of a ranch fence the bones lay and which country's export law applied to a rock found in the desert, and both have been litigated. A mounted skeleton needs a building; its scientific value is contested by the field that studies it. Meteorites rate better on custody and worse on provenance.","regime":"Three dinosaur records in six years, each set against a single-digit field of bidders; a market made by one auction department and a handful of buyers, with no price below the trophy tier.","regimeAsOf":"19 Oct 2026","since":"First entry. \"Gus\", a Tyrannosaurus rex from South Dakota, made $50.1 m at Sotheby's New York on 14 July 2026 against a $20–30 m estimate, seven bidders over ten minutes, beating \"Apex\" the Stegosaurus ($44.6 m, 2024). The largest Martian meteorite on Earth, NWA 16788, made $5.3 m in the same department's July 2025 sale.","themes":["provenance","sanctions","custody","tax","access","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"old-masters","name":"Old Masters","why":"Export licence and title"},{"slug":"rare-books","name":"Rare Books","why":"Specialist auctions"},{"slug":"coins","name":"Coins","why":"Authentication and census"}],"sources":11,"url":"/fossils-dashboard","exitLabel":"dinosaurs and meteorites","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"Yes, with a building","Wrappers":"None","Owns":"—"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Auction-led","Faces":"Sotheby's natural-history sale each July; museums and collectors through the same specialists; dealers at Tucson for the rest","Cost":"Buyer 28% / 22% / 15%; seller negotiable"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Conditioned","Where":"A mounted skeleton needs a building; a meteorite a shelf","Cost":"Excavation, preparation and mounting run to years and seven figures; crating and transport of a 38 ft skeleton","Fails":"Size; title and export documentation"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Calendar auction","Route":"Sotheby's New York natural-history sale each July; private sale to a museum","Open":"Once a year","Liquidity":"Low"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"Low; dispersed finders, one dominant saleroom","Regime":"Calendar auction","Who":"One Sotheby's department, one sale a year; three records since 2020, each by a different specimen"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"High","Claim":"Title and legal export; composite specimens","Verifier":"Excavation and export documentation; the saleroom's own due diligence"}}]},"sanctions":{"title":"Sanctions, tariffs and origin","date":"","rows":[{"section":"The register: live measures","cells":{"Instrument":"Export control","Measure":"Legal export documentation from the country of excavation is the title","Effect":"Specimens from countries that bar export cannot be sold openly"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"Chattel; title depends on the land it was found on and the state's export law","UK":"CGT above £6,000","US":"28%; a specimen from US federal land cannot be privately owned; Mongolia, China, Brazil and Argentina bar export, so a title can be void at the border"}}]}}},"frankincense":{"slug":"frankincense","name":"Frankincense","family":"Aromatics","grade":1,"label":"No route","rated":"Route: none identified","asof":"5 Oct 2026","method":"v1.2","axes":{"concentration":{"s":3,"band":"Medium","q":""},"liquidity":{"s":1,"band":"Low","q":""},"scarcity":{"s":3,"band":"Medium","q":"B. papyrifera High"},"provenance":{"s":4,"band":"High","q":""}},"factors":{"Valuation":1,"Exit":1,"Custody":1,"Title and transfer":1,"Access":1,"Intangible premium":2},"horizon":{"big":"None · no route","text":"Resin keeps for years but is harvested, sorted and shipped within the season by traders who hold it for weeks, not years. There is no vehicle, no listed producer and no way to own the trees, which are communal or state land in Somaliland, Oman and Ethiopia. Σ1 because there is nothing to hold."},"exit":{"routes":"A holder of resin sells to an exporter in Berbera, Bosaso or Salalah, or to a Western ingredient house or distiller; essential-oil distillers and incense merchants buy graded lots. No exchange, no benchmark, no fund.","activity":"Exporter FOB quotes from Berbera and Mogadishu run US$6–14/kg for Boswellia sacra by grade and US$8–65/kg for frereana (maydi), with 200–500 t a season on offer from a single trader; harvesters receive US$2–5/kg while the same resin sells to Western suppliers at US$60–100/kg. Over 15,000 t trade a year.","cost":"The exit cost is the chain itself: each of four or five hands between the tree and the distiller takes a margin, and grading is by eye at the point of sale. Export licensing in Somaliland and CITES listing of Boswellia (Appendix II from 2025) add paperwork a private seller cannot easily complete.","time":"Weeks to a local trader at the trader's price in the harvest season; months to find an overseas buyer for a graded lot. No mechanism exists for a private holder to sell at a published price."},"why":"Resin trades informally through Somaliland and Omani channels with no benchmark or investable vehicle. Supply is under ecological pressure and documentation is thin. Graded Σ1 until a route is identified.","regime":"Resin prices rising against documented tree decline; the trade informal and unbenchmarked.","regimeAsOf":"5 Oct 2026","since":"Re-checked 5 Oct 2026: only retail listings for the 2026 Dhofar and Somaliland harvests found (Omani Hojari roughly €140–240/kg retail), no trade benchmark or new tree-health study. Regime and ratings unchanged.","themes":["provenance","climate","sanctions","custody","tax","access","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"oud","name":"Oud","why":"Aromatic resin and wood"},{"slug":"saffron","name":"Saffron","why":"Smallholder, no reference price"},{"slug":"vanilla","name":"Vanilla","why":"Cured natural product"}],"sources":20,"url":"/frankincense-dashboard","exitLabel":"none identified","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"No","Wrappers":"None","Owns":"—"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Dealer-led","Faces":"Exporters in Berbera, Bosaso or Salalah; ingredient houses","Cost":"Four or five hands between tree and distiller, each a margin"}}]},"climate":{"title":"Climate and supply shock","date":"","rows":[{"section":"The register: exposed markets","cells":{"Driver":"Over-tapping and drought on communal land; tree mortality","Event":"Boswellia listed on CITES Appendix II from 2025; harvesters receive $2–5/kg for resin sold on at $60–100","Storable":"Resin keeps for years; nobody holds it"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Living / perishable","Where":"Resin held by traders for weeks; trees on communal or state land","Cost":"Each of four or five hands takes a margin","Fails":"There is no way to own the trees"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"None","Route":"Exporter in Berbera, Bosaso or Salalah; ingredient houses and distillers. No exchange, no benchmark, no fund","Open":"Within the season","Liquidity":"Low"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"Medium","Regime":"Dealer quote","Who":"Exporters in Berbera, Bosaso and Salalah; no exchange, no benchmark"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"High","Claim":"Species and grade","Verifier":"Grading by eye at the point of sale; four or five hands between tree and distiller"}}]},"sanctions":{"title":"Sanctions, tariffs and origin","date":"","rows":[{"section":"The register: live measures","cells":{"Instrument":"Species listing; export control","Measure":"Boswellia listed on CITES Appendix II from 2025; export licensing in Somaliland","Effect":"Paperwork a private seller cannot easily complete"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"Trading stock","UK":"Income tax","US":"—"}}]}}},"gold":{"slug":"gold","name":"Gold","family":"Metals, Energy & Strategic Materials","grade":5,"label":"Institutional","rated":"Physical metal","asof":"19 Oct 2026","method":"v1.2","axes":{"concentration":{"s":3,"band":"Medium","q":"refining (mine Low)"},"liquidity":{"s":5,"band":"High","q":""},"scarcity":{"s":2,"band":"Low","q":""},"provenance":{"s":3,"band":"Medium","q":"doré origin"}},"factors":{"Valuation":5,"Exit":5,"Custody":5,"Title and transfer":5,"Access":5,"Intangible premium":4},"horizon":{"big":"Open-ended","text":"Gold is held as a reserve or strategic allocation rather than to a term; the World Gold Council frames it as a long-term portfolio holding. No contractual horizon applies to allocated metal or to physically backed ETF shares."},"exit":{"routes":"Allocated bars sold back through a bullion bank or dealer at the LBMA Gold Price; physically backed ETF shares on exchange; COMEX futures.","activity":"Average daily turnover across OTC, exchange and ETF venues was about US$423 bn in September 2026. London clearing alone transferred 18.6 Moz a day in August.","cost":"The largest US gold ETFs charge 0.10–0.40% a year with quoted spreads near 0.01%. Dealer spreads on physical bars are wider and depend on size and form.","time":"Loco London spot settles two business days after trade; ETF shares settle on the exchange cycle."},"why":"The LBMA Gold Price, set twice daily, deep spot and ETF markets, and allocated vault custody make gold the reference institutional holding. Exit takes days at low cost. Doré origin aside, title and transfer are standardised.","regime":"Correction stabilising: ~$4,170 in mid-October, about 25% below the January record. A hot September CPI was absorbed within a day; October hike odds have faded and official-sector buying is accelerating.","regimeAsOf":"19 Oct 2026","since":"Spot ~$4,171 on 19 Oct, up about 1% since 5 Oct and within a $4,080–4,200 range for the month. The hot September CPI print on 14 Oct knocked gold to ~$4,080 intraday; it recovered to ~$4,183 the next day as Treasury yields retreated from their highest level since 2002. Markets now price roughly an 85% chance the Fed holds at 3.75–4.00% on 28 Oct, with a hike pushed to December; the \"possible October hike\" of early October has faded. The PBoC added 23 t in September per the World Gold Council (21 t per Wind Info), its largest month since October 2023 and 103 t year to date; a secondary report puts global central-bank buying in September near 63 t, unconfirmed by the WGC at this update.","themes":["provenance","custody","tax","access","tokenisation","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"silver","name":"Silver","why":"Monetary metal, same fix"},{"slug":"pgm","name":"Platinum Group Metals","why":"Precious, industrial demand"},{"slug":"coins","name":"Coins","why":"Bullion value in collectibles"},{"slug":"copper","name":"Copper","why":"Exchange-traded base metal"}],"sources":37,"url":"/gold-dashboard","exitLabel":"physical metal","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"Yes: allocated bars","Wrappers":"Physically backed ETFs; COMEX futures; tokens (PAXG, XAUT)","Owns":"Allocated metal in LBMA vaults; a daily benchmark"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Exchange","Faces":"Bullion bank or dealer at the LBMA price; ETF on exchange","Cost":"ETF spread near 0.01%; dealer spreads wider by size and form"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Paper / Vault","Where":"ETF shares; allocated bars in LBMA vaults","Cost":"ETFs 0.10–0.40% a year, spreads near 0.01%; dealer spreads wider on physical","Fails":"Unallocated metal is a claim on the bank, not a bar"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Benchmark","Route":"Bullion bank or dealer at the LBMA Gold Price; ETF shares; COMEX","Open":"Daily","Liquidity":"High"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"Medium, refining (mine Low)","Regime":"Benchmark auction","Who":"LBMA Gold Price, IBA auction twice daily; COMEX"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"Medium (doré origin)","Claim":"Origin of doré entering refining","Verifier":"LBMA Good Delivery refiners assay the bar; origin rests on refiner due diligence"}}]},"substitutes":{"title":"Synthetic and substitute pressure","date":"","rows":[{"section":"Substitutes by sector","cells":{"Substitute":"None for the element. Substitution occurs between uses: platinum for palladium in autocatalysts, thrifting of silver in photovoltaics","Stage":"Not applicable","Pressure":"Industrial demand, not identity; the metal remains the metal","Survives":"The whole market; this is why the benchmark door (see Exit depth) exists"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"Allocated bars: chattel. Sovereigns, Britannias: legal tender. ETF: security","UK":"Bars CGT; coins exempt; investment gold VAT-exempt; ETF CGT","US":"28% on bars, coins and physically backed ETFs alike; tokens taxed as the metal where redeemable"}}]}}},"handbags":{"slug":"handbags","name":"Handbags","family":"Cellar & Collectibles","grade":3,"label":"Specialist","rated":"Hermès Birkin and Kelly, secondary market","asof":"19 Oct 2026","method":"v1.2","axes":{"concentration":{"s":5,"band":"High","q":"one house controls new supply by allocation"},"liquidity":{"s":3,"band":"Medium","q":""},"scarcity":{"s":2,"band":"Low","q":"artificial, by allocation"},"provenance":{"s":4,"band":"High","q":""}},"factors":{"Valuation":3,"Exit":3,"Custody":4,"Title and transfer":3,"Access":3,"Intangible premium":1},"horizon":{"big":"1–5 years · store-fresh","text":"The premium is highest the day the bag leaves the boutique: a pristine Birkin 25 or 30 trades at about $28,000–30,000 against $13,500–14,900 retail, and the premium decays with use. Collectors hold rare colours and exotics for longer; the quota system (two Birkin, Kelly or Constance a year per client) is what keeps the first-year premium alive."},"exit":{"routes":"Sotheby's Marketplace at a fixed price or Sotheby's online auctions (Zurich 5–19 Nov, New York 30 Nov–14 Dec 2026); Christie's and Heritage for rare pieces; direct buyers (Rebag, Privé Porter, Madison Avenue Couture) for an immediate offer; consignment platforms. Hermès itself buys nothing back.","activity":"Sotheby's Birkin sales grew over 70% in 2025 and the average Togo Birkin 30 made $22,300; neutral 25s and 30s in pristine condition sell within weeks, and Marketplace leather Birkins in 30–45 days. The original 1985 bag made $10.1 m in July 2025. Below the top, the average Birkin's premium to retail has fallen from 2.2× to 1.4× as pandemic buyers sell.","cost":"Sotheby's Marketplace pays the seller 80% of the sale price; auction adds a buyer's premium of 20–26% that caps the hammer; specialist consignment runs 20–30%; a direct buyer pays 40–70% of resale value for cash in days. Missing box, receipt or dust bag costs more than any fee.","time":"Direct buyer: offer in days, payment 3–7 days after receipt. Marketplace: 30–45 days for leather, longer for exotics. Auction: a scheduled two-week online sale, paid about 35 days after close."},"why":"A quota Birkin or Kelly in a liquid configuration has a readier market than almost any collectible: dealers and platforms quote buy prices, Sotheby's runs continuous online sales, and a store-fresh bag clears in weeks. The grade stops at Σ3 because everything that makes the market work is controlled by one company, Hermès, which sets retail prices, decides who may buy, and has no obligation to keep the premium alive; because the premium itself is narrowing; and because the bags are the most counterfeited luxury object on earth.","regime":"The top is detaching from the middle: the original Birkin made $10.1 m and Sotheby's bag sales rose 44% in 2025, while the average Birkin's premium to retail has fallen from 2.2× to 1.4× as pandemic buyers sell into a flooded resale market.","regimeAsOf":"19 Oct 2026","since":"First entry. The Jane Birkin prototype, €8.58 m at Sotheby's Paris on 10 July 2025, set the handbag record by a factor of twenty; a second Birkin-owned bag made $2.9 m in December against a $440,000 high estimate. Sotheby's reports Birkin and Kelly sales up 44% in 2025; Bernstein and Saclàb data show the average premium falling and mid-2026 average resale at €16,290.","themes":["provenance","custody","tax","access","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"watches","name":"Watches","why":"Brand-controlled supply"},{"slug":"signed-jewellery","name":"Signed Jewellery","why":"Maison premium"},{"slug":"art","name":"Art","why":"Resale through auction"}],"sources":12,"url":"/handbags-dashboard","exitLabel":"Birkin and Kelly, secondary","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"Yes","Wrappers":"Hermès equity, which owns the allocation, not the bags","Owns":"The house"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Both: fixed-price marketplace and auction under one roof","Faces":"Sotheby's Marketplace at a fixed price or Sotheby's online auction; Christie's and Heritage for the rare; resale platforms","Cost":"Marketplace pays the seller 80%; auction premium 20–26%; consignment 20–30%"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Shelf","Where":"In its box and dust bag, unused","Cost":"Nothing but restraint","Fails":"The premium decays with use; missing box, receipt or dust bag costs more than any fee"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Calendar auction","Route":"Sotheby's Marketplace at a fixed price or online auction; Christie's and Heritage for rare pieces; direct buyers (Rebag, Privé Porter)","Open":"Continuous for store-fresh; auctions seasonal","Liquidity":"Medium"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"High; one house controls new supply by allocation","Regime":"Administered (retail); Calendar auction (secondary)","Who":"Hermès sets retail and allocates two quota bags a client a year; Sotheby's and direct buyers set the resale premium"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"High","Claim":"Identity (\"superfakes\")","Verifier":"Resale platforms' own authentication; the house does not authenticate for third parties"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"Non-wasting chattel","UK":"CGT above £6,000 on a Birkin sold at a gain; the house's retail VAT is sunk","US":"28%; US customs duty on leather goods up to 10%, plus the 2025 tariff round on EU goods (see Sanctions)"}}]}}},"jade":{"slug":"jade","name":"Jade","family":"Gems & Jewellery","grade":2,"label":"Restricted","rated":"Jadeite jewellery, Type A","asof":"19 Oct 2026","method":"v1.2","axes":{"concentration":{"s":5,"band":"High","q":"one country, one state enterprise"},"liquidity":{"s":2,"band":"Low","q":""},"scarcity":{"s":3,"band":"Medium","q":"imperial grade High"},"provenance":{"s":5,"band":"High","q":""}},"factors":{"Valuation":1,"Exit":1,"Custody":4,"Title and transfer":2,"Access":2,"Intangible premium":1},"horizon":{"big":"10+ years · top grade","text":"Imperial-grade jadeite is held for decades and surfaces at Hong Kong sales a few times a year; the Hutton-Mdivani necklace record of 2014 stood until this May and was not beaten. Mid-grade jadeite bought at retail in the last five years has fallen under livestream selling and has no resale route at all."},"exit":{"routes":"Christie's, Sotheby's, Poly and Tiancheng in Hong Kong for pieces with a Hong Kong Jade & Stone Laboratory or GIA report; Hong Kong and Guangzhou dealers for the rest; no Western auction depth and no route at all for recent Myanmar material into sanctioning jurisdictions.","activity":"Christie's Hong Kong, 26 May 2026: the 61-bead Ethereal necklace made HK$200.2 m (US$25.5 m) on 18 bids, the most valuable jadeite at auction in a decade; a 68-bead necklace HK$13.9 m; the sale 90% sold by lot, HK$581.5 m, +55% y/y. Below that tier, the trade association reports top grades firm and mid and lower grades flat to easing.","cost":"Auction commission on both sides (seller around 10%, buyer 25%+), a laboratory report before consignment, and the authentication risk that a treated (Type B or C) piece is unsaleable. Dealer buy-back at a deep discount to retail; livestream resale prices have reset the mid-market downward.","time":"Two Hong Kong seasons a year, spring and autumn; consignment months ahead, payment 30–45 days after. A dealer offer in days at the dealer's price. Nothing faster exists."},"why":"There is no reference price and no exchange; each piece is valued by eye and laboratory report against a thin set of Hong Kong auction results. Exit is through a handful of Hong Kong sales a year or dealers in a market Western buyers cannot read. Treatment fraud is endemic, Western sanctions on the sole producer make import and resale of recent material legally uncertain, and almost all value rests on a cultural premium confined to one buyer base.","regime":"The market has split: imperial-grade jadeite set a decade record in Hong Kong in May while mid-grade prices fell under livestream selling, and the only legal source is a sanctioned military enterprise.","regimeAsOf":"19 Oct 2026","since":"First entry. Myanmar's military held its first Gems Emporium outside the country, in Ruili, China, on 22 July 2026, offering 500 tonnes of rough; the 61st domestic Emporium ran to 17 October. The Christie's Hong Kong record necklace in May (HK$200.2 m) and falling mid-tier prices define the year.","themes":["provenance","sanctions","custody","tax","access","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"coloured-gemstones","name":"Coloured Gemstones","why":"Treatment and origin"},{"slug":"pu-erh-tea","name":"Pu-erh Tea","why":"Chinese collector market"},{"slug":"pearls","name":"Pearls","why":"No grading standard"}],"sources":11,"url":"/jade-dashboard","exitLabel":"Type A jadeite jewellery","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"Yes: jewellery","Wrappers":"None","Owns":"—"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Auction-led for the top; dealers below","Faces":"Christie's, Sotheby's, Poly and Tiancheng in Hong Kong with a lab report; Hong Kong and Guangzhou dealers for the rest","Cost":"Seller around 10%; buyer 25%+"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Shelf","Where":"Jewellery, in a safe","Cost":"A laboratory report before consignment","Fails":"A treated (Type B or C) piece is unsaleable"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Calendar auction","Route":"Hong Kong sales with a Hong Kong Jade & Stone Laboratory or GIA report; Hong Kong and Guangzhou dealers for the rest","Open":"A few times a year, Hong Kong only","Liquidity":"Low"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"High; one country, one state enterprise","Regime":"Administered (rough); Calendar auction (jewellery)","Who":"Myanmar Gems Enterprise emporia for rough; Hong Kong hammers for imperial grade; livestream sellers for mid-grade"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"High","Claim":"Type A (untreated); Myanmar origin under sanction","Verifier":"Hong Kong Jade & Stone Laboratory or GIA report; no route at all for recent Myanmar material"}}]},"sanctions":{"title":"Sanctions, tariffs and origin","date":"","rows":[{"section":"The register: live measures","cells":{"Instrument":"Sanction","Measure":"The sole legal source is a sanctioned Myanmar military enterprise; import and resale of recent material legally uncertain in sanctioning jurisdictions","Effect":"No Western route for recent material; the market is Hong Kong and Guangzhou"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"Jewellery: chattel","UK":"CGT above £6,000","US":"28%; Myanmar-origin jadeite under US sanctions (see Sanctions); Hong Kong: no CGT, no VAT"}}]}}},"japanese-whisky":{"slug":"japanese-whisky","name":"Japanese Whisky","family":"Cellar & Collectibles","grade":3,"label":"Specialist","rated":"Physical","asof":"20 Oct 2026","method":"v1.2","axes":{"concentration":{"s":5,"band":"High","q":"two companies, two closed stills"},"liquidity":{"s":3,"band":"Medium","q":"monthly online auctions, thin at the top"},"scarcity":{"s":4,"band":"High","q":"for age statements; low for the category"},"provenance":{"s":4,"band":"High","q":"refills and counterfeits"}},"factors":{"Valuation":3,"Exit":3,"Custody":4,"Title and transfer":3,"Access":4,"Intangible premium":2},"horizon":{"big":"5–10 years","text":"Age-statement bottles are allocated by ballot and resell above release at once, so the first-year gain is the allocation, not the hold. Beyond that the horizon is the same as Scotch, five to ten years, with one addition: bottles labelled before the 2021 standard took effect carry a provenance discount that widens as the market learns to read the label."},"exit":{"routes":"The same monthly online auctions as Scotch (Whisky Auctioneer and peers), where Japanese whisky is a standing category; Bonhams and Sotheby's Hong Kong for the trophy lots; specialist retailers in Japan and Europe who buy outright.","activity":"Deep for standard Yamazaki, Hakushu and Hibiki age statements, which appear in every monthly sale; thin at the top, where a handful of lots a year set the record and where several named bottles failed to sell in 2024 before the May 2026 record of $842,169.","cost":"As for Scotch: seller's commission 5–10% plus VAT, buyer's premium 12.5–15% that caps the hammer, listing and reserve fees. Shipping spirits across borders adds duty and freight that fall on the buyer and narrow the pool.","time":"Six to ten weeks from consignment to cash through a monthly online sale; a trophy bottle waits for a Hong Kong or London sale date and is paid 30–45 days after."},"why":"Price discovery exists but is thin: a deep monthly auction record for standard age statements, and a handful of lots a year for the trophies, several of which failed to sell in 2024 before the 2026 record. The category was defined only in 2021 and enforced from 2024, so a bottle labelled before then may contain imported spirit, and the market now prices that distinction. Supply is controlled by two companies that allocate by ballot in Japan and ration export, which is both the source of the premium and the reason a holder cannot rely on it. Bottles are easy to store and insure, and the entry price is low; the exit for anything above a Yamazaki 18 is a consignment to a specialist and a wait for the right sale.","regime":"A record set in May 2026 for a single bottle, a labelling standard that finally defines the category, and a secondary market where half the famous names failed to meet reserve two years ago; the asset is the age statement, not the country.","regimeAsOf":"20 Oct 2026","since":"First entry. Bonhams Hong Kong sold Yamazaki 50 Year Old Club Natsume for a hammer of $842,169 on 30 May 2026, a record for any Japanese whisky by more than 30%, with Karuizawa 1960 Cask 5627 at $638,007 in the same two-lot sale; the JSLMA's application for geographical-indication status, announced March 2025, is pending.","themes":["provenance","custody","tax","access","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"scotch-whisky","name":"Scotch Whisky","why":"Age statements, brand owners"},{"slug":"rare-whisky-casks","name":"Rare Whisky Casks","why":"Cask ownership risk"},{"slug":"cigars","name":"Cigars","why":"Allocated supply"}],"sources":11,"url":"/japanese-whisky-dashboard","exitLabel":"bottles","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"Yes: bottles","Wrappers":"Suntory (private) and Asahi equity, heavily diluted","Owns":"Beverage groups"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Both","Faces":"The same online auctions as Scotch; Bonhams and Sotheby's Hong Kong for trophies","Cost":"Seller 5–10% plus VAT; buyer 12.5–15%"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Shelf","Where":"Sealed bottle, upright, out of light","Cost":"A few pounds a bottle a year in specialist storage; the easiest factor on the page","Fails":"Refills; cross-border duty and freight narrow the buyer pool"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Calendar auction","Route":"The same monthly online auctions; Hong Kong sales for trophy lots; specialist retailers","Open":"Monthly; thin at the top","Liquidity":"Medium"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"Very high; two companies, two closed stills","Regime":"Administered (release); Calendar auction (secondary)","Who":"Suntory and Nikka set release price and allocate by ballot; the secondary premium is the gap"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"High; refills and counterfeits","Claim":"Identity of pre-2021 \"Japanese\" whisky; refills of age statements","Verifier":"The 2021 labelling standard, going forward; auction inspection; nothing for older labels"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"Bottles: non-wasting chattel","UK":"As for Scotch","US":"28%; Japanese liquor tax is paid at release, so a bottle carries it already"}}]}}},"lab-grown-diamonds":{"slug":"lab-grown-diamonds","name":"Lab-Grown Diamonds","family":"Gems & Jewellery","grade":2,"label":"Restricted","rated":"Route: growers and retailers","asof":"20 Oct 2026","method":"v1.2","axes":{"concentration":{"s":3,"band":"Medium","q":""},"liquidity":{"s":3,"band":"Medium","q":""},"scarcity":{"s":1,"band":"Low","q":""},"provenance":{"s":3,"band":"Medium","q":""}},"factors":{"Valuation":2,"Exit":1,"Custody":4,"Title and transfer":3,"Access":2,"Intangible premium":2},"horizon":{"big":"None · a depreciating good","text":"There is no horizon at which holding pays. The wholesale price of a 1 ct stone fell from about $1,800 in mid-2018 to about $80–87 by Q3 2026, 92–95%, and retail is still falling toward it; the sellers themselves put resale at 10–20% of purchase price and the main online buyers decline the category. The route is growers and retailers, held as equity."},"exit":{"routes":"For a stone: almost none. Worthy and myGemma do not buy lab-grown; a few lab sellers offer trade-in credit at 15–20% of price. For capital: shares in the growers and retailers that are listed (mostly in India and the US), few of them liquid; private sale of a grower.","activity":"Volume rises as price falls: India's polished lab-grown exports were up 41% in September 2026 while natural fell; lab-grown is 61% of US centre stones. Wholesale for 1–3 ct rounds rose about 2% in Q3 2026, the first uptick, led by 3 ct; retail asking for a 1 ct averaged $502–508 in mid-October, down 19% in three months, listings $245–1,288.","cost":"The spread between retail and wholesale is the whole holding: a stone bought at $700–1,100 retail has a wholesale value near $80–90 and a trade-in value of $100–200. Grading reports (IGI) cost more than the stone is worth at resale.","time":"Immediate, at a price close to zero; or never, since most buyers decline the category. Equity exits the same day."},"why":"Retail and wholesale prices fall year after year, so held stones lose value and resale is close to nil. The practical route is growers and retailers, and few of them are listed or liquid. Custody and title are simple; price discovery and exit are the binding limits.","regime":"The wholesale floor has been found; retail is still falling toward it. Volume is the growth story: India's polished lab-grown exports +41% in September while natural fell.","regimeAsOf":"20 Oct 2026","since":"Wholesale and retail have split: Edahn Golan has 1–3 ct round wholesale up ~2% in Q3 2026, the first rise after years of decline, while StoneAlgo's average 1 ct retail asking price fell ~20% in three months to $502 on 14 Oct (natural $3,820). StoneAlgo's 1 ct lab average has fallen 31% from $732 in December 2023; listings now run $245–1,273 against $805–9,850 for natural. India's polished lab-grown exports rose 40.7% to $151m in September and 17.1% to $685m for April–September on 26.5% more carats, while natural polished exports fell 5.4% and 7.0%.","themes":["provenance","substitutes","sanctions","custody","tax","access","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"polished-diamonds","name":"Polished Diamonds","why":"The natural it competes with"},{"slug":"rough-diamonds","name":"Rough Diamonds","why":"Mine supply it displaces"},{"slug":"coloured-gemstones","name":"Coloured Gemstones","why":"Synthetic vs natural premium"}],"sources":35,"url":"/lab-grown-diamonds-dashboard","exitLabel":"growers and retailers","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"Yes, but it depreciates","Wrappers":"Grower and retailer equity, few listed or liquid","Owns":"Operating companies in a falling-price industry"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Dealer-led, and the dealers decline","Faces":"Worthy and myGemma do not buy; a few sellers offer trade-in credit at 15–20% of price","Cost":"Wholesale near $80–90 on a $700–1,100 retail stone"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Shelf","Where":"A stone; or grower and retailer equity","Cost":"A grading report costs more than the stone is worth at resale","Fails":"The holding has no horizon at which it pays"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Counterparty / None","Route":"For a stone: almost none; trade-in credit at 15–20% of price from a few sellers. For capital: listed growers and retailers","Open":"Equity daily; the stone, effectively never","Liquidity":"Medium (equity)"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"Medium","Regime":"Asking list","Who":"Growers' wholesale quotes in Surat and Henan; retail asking prices tracked by aggregators; no floor but marginal cost"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"Medium","Claim":"Disclosure when resold","Verifier":"Laboratory inscription; detection equipment at the trade level"}}]},"sanctions":{"title":"Sanctions, tariffs and origin","date":"","rows":[{"section":"The register: live measures","cells":{"Instrument":"Sanction","Measure":"G7 ban extended to Russian synthetic diamonds and diamond-set jewellery and watches at 0.5 ct from 1 Sep 2024","Effect":"Growers' origin now a compliance item; Indian and Chinese output unaffected"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"Stone: chattel","UK":"A loss on a chattel bought and sold under £6,000 is not allowable; above that, allowable against chattel gains only","US":"A collectible loss is a capital loss; the depreciation is the holding (see Substitutes)"}}]}}},"manuka-honey":{"slug":"manuka-honey","name":"Mānuka Honey","family":"Crops","grade":3,"label":"Specialist","rated":"Route: listed producer","asof":"5 Oct 2026","method":"v1.2","axes":{"concentration":{"s":5,"band":"High","q":""},"liquidity":{"s":2,"band":"Low","q":""},"scarcity":{"s":3,"band":"Medium","q":""},"provenance":{"s":3,"band":"Medium","q":"High outside NZ"}},"factors":{"Valuation":3,"Exit":3,"Custody":4,"Title and transfer":4,"Access":3,"Intangible premium":2},"horizon":{"big":"Equity · no fixed term","text":"The route is a listed producer, so the horizon is an equity holding; the honey itself keeps for years but has been sitting in warehouses since the 2020 stockpile. Comvita's shareholders have had the horizon chosen for them: a failed 80c takeover in 2025, a 65c rights issue in 2026, and a stock that traded between 43c and 82c over the year."},"exit":{"routes":"Comvita (NZX: CVT) is the only sizeable listed pure play; shares sell on the NZX through any broker. Honey: sale of drums to a packer or exporter at the MGO-graded price, or of an apiary business privately. Comvita itself now buys 68% of its honey from outside its own hives.","activity":"Comvita's market capitalisation is about NZ$100 m; daily volume on the NZX runs in the tens to hundreds of thousands of shares. The May 2026 rights issue raised NZ$25 m at 65c with 44% take-up and brought in Fraser and Neave at 19.99%. The physical market behind it is oversupplied, with 15–30,000 t in storage against about 10,000 t of annual sales.","cost":"Brokerage and the bid–offer spread on a thinly traded small cap; the material cost is price impact, since a block of any size moves the stock. Drum honey sells at a discount that widens with the stockpile; UMF/MGO testing and licensing fees fall on the seller.","time":"Shares: same-day on exchange, settled T+2, but a large holding takes weeks to work. Drums: weeks to months to place with a packer in an oversupplied market; an apiary business, months."},"why":"UMF and MGO grading supports valuation, but there is no exchange. The route is listed producers, chiefly in New Zealand. Authentication outside New Zealand remains a material risk.","regime":"Unit prices sliding as the 2020 stockpile is worked off; export value below the 2020 peak, grade premia set by MGO rating.","regimeAsOf":"5 Oct 2026","since":"Re-checked 5 Oct 2026: no new export statistics found since the last update. Ratings unchanged.","themes":["provenance","climate","custody","tax","access","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"olive-oil","name":"Olive Oil","why":"Grade and adulteration"},{"slug":"dates","name":"Dates","why":"Origin-protected food"},{"slug":"tea","name":"Tea","why":"Premium agricultural product"}],"sources":11,"url":"/manuka-honey-dashboard","exitLabel":"listed producer","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"Drums, at a discount","Wrappers":"Comvita (NZX: CVT), the only sizeable listed pure play","Owns":"A producer that failed an 80c takeover, raised at 65c and traded 43–82c in a year"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Exchange (equity); administered (drums)","Faces":"NZX broker; packer or exporter at the MGO-graded price","Cost":"Price impact on a thin small cap; drums at a discount"}}]},"climate":{"title":"Climate and supply shock","date":"","rows":[{"section":"The register: exposed markets","cells":{"Driver":"Weather in a narrow flowering window; land access; hive numbers","Event":"Hive numbers down 42% since 2019; 15–30,000 t in storage against c. 10,000 t annual sales after the 2020 harvest of 27,000 t","Storable":"Yes, for years, which is the problem: the glut is stored"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Paper (equity)","Where":"Comvita shares; drums in warehouses since the 2020 stockpile","Cost":"Brokerage and price impact on a small cap; UMF/MGO testing on drums","Fails":"15–30,000 t in storage against about 10,000 t of annual sales"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Counterparty","Route":"Comvita shares on the NZX; drums to a packer at the MGO-graded price; an apiary business privately","Open":"Equity daily; honey on request","Liquidity":"Low"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"High","Regime":"Exchange (equity); Dealer quote (honey)","Who":"NZX for Comvita; packers' MGO-graded bids for drums"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"Medium; High outside NZ","Claim":"Identity and MGO grade","Verifier":"New Zealand's science definition and export testing; nothing comparable abroad"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"Comvita equity; drums are trading stock","UK":"CGT at share rates","US":"Share rates; New Zealand has no general capital gains tax"}}]}}},"maple-syrup":{"slug":"maple-syrup","name":"Maple Syrup","family":"Crops","grade":2,"label":"Restricted","rated":"Commodity","asof":"20 Oct 2026","method":"v1.2","axes":{"concentration":{"s":5,"band":"High","q":"Québec 72% of world output under one seller"},"liquidity":{"s":2,"band":"Low","q":"outside the plan; administered price"},"scarcity":{"s":2,"band":"Low","q":"Weather-driven year to year; none structurally"},"provenance":{"s":2,"band":"Low","q":"graded and inspected on delivery"}},"factors":{"Valuation":2,"Exit":1,"Custody":3,"Title and transfer":4,"Access":1,"Intangible premium":4},"horizon":{"big":"None · administered","text":"There is nothing to hold. Bulk syrup in Québec must be delivered to the Federation in the season it is made, graded and paid at an administered price; the Federation, not the producer, decides whether it ships or goes into the reserve. The only holding is a sugar bush with quota, a farming business whose horizon is the trees."},"exit":{"routes":"Québec bulk: sale only to a PPAQ-authorised buyer at the Federation price; direct retail sales of small containers are the sole exception. Outside Québec, US bulk buyers (Bascom in New Hampshire is the largest) set their own prices, anchored to Québec's. A sugar bush with quota sells as farmland.","activity":"The reserve's 133 m lb capacity has been run to zero and remaining contracted syrup is expected gone by February 2027; the Federation has added 21 m taps in five years. US bulk buyers paid US$2.60/lb for top grades in 2026, Québec about US$2.60; USDA reports US bulk at $2.80/lb for 2025. Quota itself is allocated by the Federation, not traded.","cost":"Levies of about 14¢/lb on all bulk syrup graded fund the Federation, plus promotion and reserve charges; cash authorised buyers pay C$1,450 a barrel on receipt, credit buyers pay over months with carrying charges at prime plus 1%. Producers who sell outside the system have faced seizure and fines.","time":"Delivery to the buyer within the season; payment on receipt from a cash buyer or spread over months from a credit buyer, with the Federation paying producers gradually as inventory sells. A sugar bush takes months to sell and the quota transfers with the land at the Federation's discretion."},"why":"There is no way to hold maple syrup. Bulk production in Québec must be sold through the Federation at a price it sets, graded on delivery, and either shipped or barrelled into the reserve the Federation owns; a producer cannot store and sell later, and an outsider cannot buy a barrel. The only route to exposure is a sugar bush with quota, which is a farming business in one Canadian province whose output is sold to a single buyer and whose expansion depends on the Federation issuing taps. Valuation is therefore administrative, exit is to the plan, and access is land and a licence. The reserve going to zero is a supply story that a holder cannot trade.","regime":"The world's only agricultural cartel with a strategic reserve has just run it to zero: two record harvests, tariff front-running and a 16% export surge emptied 133 million pounds of capacity, and the price is still set by the Federation, not the market.","regimeAsOf":"20 Oct 2026","since":"First entry. PPAQ's president said on 19 October 2026 that the Strategic Reserve \"has been reduced to zero\" and remaining contracted syrup will be gone by end-February; 2026 production was 229.5 m lb on 58.6 m taps; exports rose 15.8% in 2025 ahead of US tariffs and 2.5% January–August 2026.","themes":["provenance","climate","custody","tax","access","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"manuka-honey","name":"Mānuka Honey","why":"Grade standards, cooperative"},{"slug":"cocoa","name":"Cocoa","why":"Weather and crop"},{"slug":"parmigiano","name":"Parmigiano Reggiano","why":"Quota and reserve"}],"sources":12,"url":"/maple-syrup-dashboard","exitLabel":"administered market","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"No","Wrappers":"None; a sugar bush with quota","Owns":"—"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Administered","Faces":"A PPAQ-authorised buyer at the Federation price, the only lawful bulk buyer in Québec","Cost":"Levies of about 14¢/lb; reserve and promotion charges"}}]},"climate":{"title":"Climate and supply shock","date":"","rows":[{"section":"The register: exposed markets","cells":{"Driver":"Freeze–thaw nights in a six-week spring window","Event":"The Global Strategic Reserve is empty after short seasons; the Federation decides what ships and what is held","Storable":"Yes, for years, but only the Federation holds it"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Living / perishable (the sugar bush)","Where":"Bulk syrup goes to the Federation; the Federation holds the reserve","Cost":"Levies of about 14¢/lb plus promotion and reserve charges","Fails":"Producers who sell outside the system have faced seizure and fines"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"None","Route":"Québec bulk: only to a PPAQ-authorised buyer at the Federation price. Outside Québec: US bulk buyers at their own price","Open":"Delivery in the season made","Liquidity":"None outside the plan; administered price"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"Very high; Québec 72% of world output under one seller","Regime":"Administered","Who":"The Fédération des producteurs acéricoles du Québec sets the bulk price, grades on delivery and decides what ships or goes to reserve"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"Low; graded and inspected on delivery","Claim":"—","Verifier":"Federation grading on delivery"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"A sugar bush with Federation quota: land and a licence","UK":"—","US":"Canada: 50% of a capital gain taxable; the quota is an eligible capital property of the farm; lifetime farm exemption"}}]}}},"oil-gas":{"slug":"oil-gas","name":"Oil & Gas","family":"Metals, Energy & Strategic Materials","grade":4,"label":"Accessible","rated":"Route: futures","asof":"19 Oct 2026","method":"v1.2","axes":{"concentration":{"s":3,"band":"Medium","q":""},"liquidity":{"s":5,"band":"High","q":""},"scarcity":{"s":1,"band":"Low","q":""},"provenance":{"s":1,"band":"Low","q":""}},"factors":{"Valuation":5,"Exit":4,"Custody":5,"Title and transfer":4,"Access":3,"Intangible premium":5},"horizon":{"big":"Contract-bounded","text":"Futures expire monthly and must be rolled; the roll yield, not the spot move, decides the return on any holding longer than one contract. Long-only oil ETFs roll on a published schedule and are not built for multi-year holds."},"exit":{"routes":"ICE Brent, NYMEX WTI and Henry Hub futures and options; futures-based ETFs; no practical physical route for a portfolio.","activity":"ICE Brent options averaged over 437,200 contracts a day in Q3 2026, a record; average daily volume across Brent futures and options is up 23% year to date. Brent futures open interest set a record 7.5 m lots on 26 January 2026.","cost":"Exchange and clearing fees per contract, broker commission and margin funding. For a long holder the dominant cost is the monthly roll when the curve is in contango.","time":"Exit at the next trade in a market open for most of each 24 hours; positions are cleared and marked the same day."},"why":"Brent, WTI and Henry Hub futures give continuous pricing and the deepest commodity liquidity available. The route is futures, so roll yield and margin are the limits on holding. Physical barrels or cargoes are not a portfolio asset.","regime":"The September reopening has reversed: Hormuz crude flows back to ~70% of pre-war after nine tanker attacks in a week, Brent at $110 for the first time since May, diesel the binding constraint.","regimeAsOf":"19 Oct 2026","since":"Brent closed $109.86 on 16 Oct, touching $110 intraday, +5% on the week and ~$9 above the last update; WTI $101.41. Kpler puts Hormuz crude exports at 9.4 mb/d for the week to 14 Oct, ~70% of pre-war, after topping pre-war levels in September. IEA's 14 Oct report: September supply +2.5 mb/d to 102.3; 2026 demand now −2.6 mb/d; 2027 still 0.6% below 2025. EIA's October STEO lifted 4Q26 Brent to $105 (+$14) and 2026 to $96.32. Gas cards (X) refreshed for the first time since July.","themes":["provenance","custody","tax","access","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"uranium","name":"Uranium","why":"Energy commodity, contracts"},{"slug":"copper","name":"Copper","why":"Futures, inventories"},{"slug":"gold","name":"Gold","why":"Macro hedge"}],"sources":28,"url":"/oil-gas-dashboard","exitLabel":"futures","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"No","Wrappers":"Futures; futures-based ETFs; producer equity","Owns":"A rolling contract position"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Exchange","Faces":"Futures broker; fund on exchange","Cost":"The roll"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Paper","Where":"Futures; futures-based ETFs","Cost":"The monthly roll in contango is the dominant cost","Fails":"No physical route; ETFs not built for multi-year holds"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Benchmark","Route":"ICE Brent, NYMEX WTI, Henry Hub futures; futures-based ETFs","Open":"Daily","Liquidity":"High"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"Medium","Regime":"Exchange","Who":"ICE Brent, NYMEX WTI and Henry Hub trades; OPEC+ output decisions behind them"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"Low","Claim":"Sanctioned origin in physical cargoes","Verifier":"Exchange-cleared contracts; no physical claim for a portfolio"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"Futures; futures-based fund; producer equity","UK":"CGT; a US-listed commodity fund without reporting status is taxed as income","US":"Section 1256 on futures; commodity pools issue K-1s; MLPs and royalties as income"}}]}}},"old-masters":{"slug":"old-masters","name":"Old Masters","family":"Cellar & Collectibles","grade":3,"label":"Specialist","rated":"Physical","asof":"19 Oct 2026","method":"v1.2","axes":{"concentration":{"s":1,"band":"Low","q":"fixed, dispersed"},"liquidity":{"s":2,"band":"Low","q":""},"scarcity":{"s":5,"band":"High","q":"finite"},"provenance":{"s":5,"band":"High","q":""}},"factors":{"Valuation":1,"Exit":2,"Custody":3,"Title and transfer":2,"Access":3,"Intangible premium":1},"horizon":{"big":"10+ years · fixed supply","text":"Nothing more will be painted and museums remove works permanently, so a picture is held for decades and its value moves with attribution and condition more than with the cycle. The 2024 low and the 2026 records show the horizon can be set by a single reattribution: a \"Dutch school\" picture bought for €1.5 m sold as a Rembrandt for £8 m in July."},"exit":{"routes":"Christie's and Sotheby's Old Masters evening and day sales (London July and December, New York January and May, Paris June); Bonhams and Dorotheum; specialist dealers who buy or consign; private sale through the houses. A fresh condition report and, where attribution is contested, scholarly opinion are expected before consignment.","activity":"London, July 2026: Christie's evening sale £38.9 m, 90% sold by lot, its highest sell-through ever in the category; Sotheby's £37.8 m, 78% sold, ten lots unsold and five of twelve pictures under £200,000 failing. New York, February 2026: Christie's $54.1 m, 84% by lot, the best since 2012; a Canaletto $30.5 m, a Michelangelo drawing $27 m. Sector auction sales $1.2 bn in 2025, +30%.","cost":"Seller's commission around 10%, waived for trophy consignments; buyer's premium 28% to $2 m, 22% to $8 m, 15% above, capping the hammer; guarantees and third-party irrevocable bids on the top lots; shipping, insurance, conservation and export licences. An unsold lot is \"burned\" for several years.","time":"Consignment three to six months before the right sale; two London and two New York seasons a year; payment within 45 days of the sale subject to the buyer settling. Six to twelve months from decision to cash for a significant picture."},"why":"Every work is unique and most have not traded in a generation, so value rests on attribution, condition and a thin set of comparables. Exit runs through a few major auction sales a year or a dealer's private placement that may take months to arrange, with guarantees now common at the top. A change of attribution can move a picture's value by an order of magnitude or more in either direction, and export licences can block the sale altogether.","regime":"After a fifteen-year low in 2024, the category posted its strongest two seasons in a decade, but only for works with a name, a condition report and no competing attribution.","regimeAsOf":"19 Oct 2026","since":"First entry. Sotheby's has announced a $60 m single-owner sale, \"Magnum Opus\", 600 lots across four sales, 21–23 October 2026 in New York; the result will be the first test of autumn depth after the July London split between trophy lots and unsold middle.","themes":["provenance","sanctions","custody","tax","access","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"art","name":"Art","why":"Living and modern market"},{"slug":"rare-books","name":"Rare Books","why":"Provenance and scholarship"},{"slug":"fossils","name":"Fossils & Meteorites","why":"Export controls"}],"sources":12,"url":"/old-masters-dashboard","exitLabel":"physical","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"Yes","Wrappers":"None of scale","Owns":"—"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Auction-led","Faces":"Christie's and Sotheby's evening sales (London July and December, New York January, Paris June); Bonhams, Dorotheum; specialist dealers at TEFAF","Cost":"Seller around 10%; buyer 28% / 22% / 15% by band"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Conditioned","Where":"Climate-controlled, with a conservator","Cost":"Conservation, insurance, shipping and export licences","Fails":"Condition and attribution move the price more than the cycle"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Calendar auction","Route":"Old Masters sales: London July and December, New York January and May, Paris June; Dorotheum; dealers","Open":"Five or six sale weeks a year","Liquidity":"Low"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"Low (fixed, dispersed)","Regime":"Calendar auction","Who":"London, New York and Paris hammers; attribution, not supply, moves the price"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"High","Claim":"Attribution, which can move a price from €1.5m to £8m or back","Verifier":"Scholarly opinion and technical analysis; a fresh condition report before consignment"}}]},"sanctions":{"title":"Sanctions, tariffs and origin","date":"","rows":[{"section":"The register: live measures","cells":{"Instrument":"Export control; restitution","Measure":"Italy's pre-emption of the Antonello; the UK deferral system; restitution claims and Nazi-era provenance gaps","Effect":"Can delay, block or reprice a sale after the hammer"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"Chattel; often a conditionally exempt heritage asset or subject to an export licence deferral","UK":"CGT above £6,000; a conditionally exempt work pays the deferred inheritance tax on sale; export licence may be deferred under the Waverley criteria","US":"28%; Italy and France: export licences and the state's pre-emption right at the auction price"}}]}}},"olive-oil":{"slug":"olive-oil","name":"Olive Oil","family":"Crops","grade":3,"label":"Specialist","rated":"Route: groves and listed producers","asof":"5 Oct 2026","method":"v1.2","axes":{"concentration":{"s":5,"band":"High","q":""},"liquidity":{"s":3,"band":"Medium","q":""},"scarcity":{"s":2,"band":"Low","q":""},"provenance":{"s":4,"band":"High","q":""}},"factors":{"Valuation":3,"Exit":2,"Custody":3,"Title and transfer":3,"Access":3,"Intangible premium":3},"horizon":{"big":"Grove 5–7 yrs to yield · oil one season","text":"Oil oxidises and is sold within the campaign; no one holds it. A grove yields commercially from year five to seven, in super-high-density systems from year three, and for decades after. Listed producers add a third horizon: Deoleo, the largest bottler, was the object of a €470 m takeover contest in August 2026."},"exit":{"routes":"Oil: bulk sale to a bottler or cooperative at the weekly origin price (Poolred, Infaoliva in Jaén; ISMEA in Italy). Grove: sale of farmland with trees, in Andalusia an active market with institutional buyers. Equity: Deoleo (Madrid), a few Greek and Italian listings, Spanish cooperatives are unlisted.","activity":"Poolred recorded Spanish extra virgin at €3.20/kg for 3–9 October 2026 (Infaoliva €3.10 on 13 October), down about 20% in a year and less than half the 2024 peak; Spain's first 2026/27 estimate is 1.6 m t, Jaén alone 575,000 t. Italian stocks closed the campaign at 195,044 t, up 47%. Deoleo trades about €0.35 a share with a 52-week range of €0.18–0.50.","cost":"Oil: mill and bottler margins, quality downgrades (virgin and lampante trade €0.20–0.30/kg below extra virgin), and storage losses if held. Grove: agency and transfer costs; valuation on yield, water and planting system. Equity: brokerage and a thin order book.","time":"Bulk oil sells in days at the weekly price; a grove takes months; listed shares exit the same day. The campaign calendar (harvest October–January) sets when sellers have oil to sell."},"why":"Bulk prices are published weekly but there is no futures market. The route is groves and listed producers, both of which carry operating and weather risk. Oil degrades and cannot be stored long.","regime":"Origin prices retreating from the 2023–24 drought peak as Spanish supply recovers.","regimeAsOf":"5 Oct 2026","since":"Spanish 2026/27 crop estimates have been cut from up to 1.8 Mt to 1.4–1.5 Mt after a hot, dry summer (42–44°C in Andalusia). Spanish EVOO at origin averaged €4.65/kg on 28 Sep, up 18% in ten days, reversing the summer low near €3.40. October rain now decides the harvest.","themes":["provenance","climate","sanctions","custody","tax","access","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"manuka-honey","name":"Mānuka Honey","why":"Adulteration risk"},{"slug":"dates","name":"Dates","why":"Mediterranean and Gulf crop"},{"slug":"cocoa","name":"Cocoa","why":"Weather-driven price"}],"sources":14,"url":"/olive-oil-dashboard","exitLabel":"groves and listed producers","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"The grove","Wrappers":"Deoleo (Madrid), the largest bottler, object of a €470m takeover contest in 2026","Owns":"A bottling business"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Administered","Faces":"Bottler or cooperative at the weekly Poolred or Infaoliva price","Cost":"Mill and bottler margins; quality downgrades €0.20–0.30/kg"}}]},"climate":{"title":"Climate and supply shock","date":"","rows":[{"section":"The register: exposed markets","cells":{"Driver":"Spanish drought and heat at flowering; alternate bearing","Event":"Spanish stocks 70,000 t below the long-term average at end-Sept 2025; 70% of the 2025/26 crop sold within seven months; a c. 37% flowering-fertility decline reported for 2026/27","Storable":"Oil oxidises and is sold within the campaign; only the grove is held"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Living / perishable","Where":"The grove; oil sold within the campaign","Cost":"Storage losses if oil is held; grove valuation on yield, water and planting system","Fails":"Oil oxidises; quality downgrades trade €0.20–0.30/kg below extra virgin"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Price list","Route":"Bulk to a bottler or cooperative at the weekly origin price; grove as farmland; Deoleo equity","Open":"Weekly price; oil within the campaign","Liquidity":"Medium"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"High","Regime":"Trade platform","Who":"Poolred and Infaoliva in Jaén, ISMEA in Italy, weekly origin prices; Deoleo as the largest bottler"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"High","Claim":"Grade (extra virgin) and origin","Verifier":"Chemical and panel tests at the mill; downgrades trade €0.20–0.30/kg below"}}]},"sanctions":{"title":"Sanctions, tariffs and origin","date":"","rows":[{"section":"The register: live measures","cells":{"Instrument":"Tariff","Measure":"25% US country tariff on Tunisian oil introduced in 2025; US tariffs on EU oil","Effect":"Shifts the origin mix bottlers buy for the US market"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"A grove: land. Deoleo: equity","UK":"Agricultural property relief for UK farmland, restricted from April 2026","US":"Spain: rural land under regional transfer tax and plusvalía; Deoleo at share rates"}}]}}},"oud":{"slug":"oud","name":"Oud","family":"Aromatics","grade":2,"label":"Restricted","rated":"Wood and oil","asof":"5 Oct 2026","method":"v1.2","axes":{"concentration":{"s":3,"band":"Medium","q":""},"liquidity":{"s":1,"band":"Low","q":""},"scarcity":{"s":4,"band":"High","q":"wild); Low (plantation)"},"provenance":{"s":5,"band":"High","q":""}},"factors":{"Valuation":1,"Exit":1,"Custody":3,"Title and transfer":2,"Access":2,"Intangible premium":1},"horizon":{"big":"Years · oil improves, wood does not","text":"Distilled oud oil matures in the bottle and dealers price vintage oils at multiples of fresh; wild sinking-grade chips hold value but gain little. Plantation trees take 10–15 years to reach commercial sinking grade and 15–25 for the premium tier, so a planter's horizon is two decades. Nothing in this market has a published term or a benchmark to mark against."},"exit":{"routes":"Private sale to attar dealers in the Gulf, Mumbai and Singapore, who also buy back; specialist online dealers; Japanese kōdō houses for the finest wood; Gulf bakhoor wholesalers for plantation chips. No auction depth outside occasional Hong Kong and Japanese incense sales, and CITES permits on every cross-border move.","activity":"Dealer price ladders rather than turnover: wild authenticated chips US$800–15,000+/kg and plantation US$30–400 at wholesale; wild oil US$30,000–80,000/kg against plantation oil US$2,000–10,000; top Hindi oil retails at £400–1,200 a tola (12 g). Plantation sinking-grade chips trade at US$120–350/kg on 50 kg minimums. The same grade is quoted at prices an order of magnitude apart.","cost":"Dealer spread and the authentication gap are the cost: there is no laboratory standard, grading is by nose and the water test, and the Gulf and East Asian buyers who can tell wild from plantation in seconds discount everything they cannot verify. CITES export permits and, for wild material, legal provenance that often does not exist.","time":"Weeks to a dealer at the dealer's price; months to place a large or unusual lot with a collector or house. Permits add weeks for any border crossing."},"why":"Wild agarwood is priced by expert assessment with no benchmark, and CITES permits govern trade. Wood and oil can be stored, but authentication is hard and adulteration common. Exit is private and slow.","regime":"No benchmark; wild-sourced material commanding rising premia while plantation grades expand supply.","regimeAsOf":"5 Oct 2026","since":"Re-checked 5 Oct 2026: no new benchmark, CITES listing change or market data found since the last update. Ratings unchanged.","themes":["provenance","substitutes","climate","sanctions","custody","tax","access","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"frankincense","name":"Frankincense","why":"Aromatic, Gulf trade"},{"slug":"saffron","name":"Saffron","why":"No reference price"}],"sources":16,"url":"/oud-dashboard","exitLabel":"wood and oil","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"Yes: wood and oil","Wrappers":"None of scale","Owns":"—"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Dealer-led","Faces":"Attar dealers in the Gulf, Mumbai and Singapore, who also buy back; kōdō houses for the finest wood","Cost":"Dealer spread and the authentication gap"}}]},"climate":{"title":"Climate and supply shock","date":"","rows":[{"section":"The register: exposed markets","cells":{"Driver":"Wild tree loss; 10–25 years for plantation resin","Event":"c. 70% of trade from wild-harvested threatened species 2010–20; most harvesting destroys the whole tree","Storable":"Oil improves in bottle; wood holds"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Conditioned (oil); Shelf (chips)","Where":"Oil in bottle, which matures; wild chips, which hold","Cost":"Dealer spread and the authentication gap; CITES permits on every cross-border move","Fails":"Plantation trees take 10–25 years; wild material often lacks legal provenance"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Counterparty","Route":"Attar dealers in the Gulf, Mumbai and Singapore, who also buy back; kōdō houses for the finest wood","Open":"On request; no benchmark","Liquidity":"Low"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"Medium","Regime":"Asking list","Who":"Dealer price ladders (wild US$800–15,000+/kg, plantation US$30–400); no benchmark"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"High","Claim":"Wild or plantation; species; dilution of oil","Verifier":"Nose and the water test; no laboratory standard; Gulf and East Asian buyers discount everything they cannot verify"}}]},"sanctions":{"title":"Sanctions, tariffs and origin","date":"","rows":[{"section":"The register: live measures","cells":{"Instrument":"Species listing","Measure":"CITES export permits on every cross-border move; legal provenance for wild material often does not exist","Effect":"The wild tier, rated High scarcity, is the tier hardest to move legally"}}]},"substitutes":{"title":"Synthetic and substitute pressure","date":"","rows":[{"section":"Substitutes by sector","cells":{"Substitute":"Plantation agarwood, inoculated to produce resin in 10–25 years; synthetic oud accords in commercial perfumery","Stage":"Advanced","Pressure":"The commercial oil and chip market; the sector page rates plantation scarcity Low","Survives":"Wild sinking-grade wood and vintage oils, rated High; the Gulf and Japanese connoisseur trade"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"Wood and oil: chattel, or trading stock; CITES Appendix II permits on export","UK":"CGT above £6,000 for a private holder; CITES paperwork is the binding constraint","US":"28% where a collectible; Gulf: no personal tax"}}]}}},"parmigiano":{"slug":"parmigiano","name":"Parmigiano Reggiano","family":"Rare Foods","grade":2,"label":"Restricted","rated":"Whole wheels, 12–36 months","asof":"19 Oct 2026","method":"v1.2","axes":{"concentration":{"s":3,"band":"Medium","q":"one consortium sets output and grades every wheel"},"liquidity":{"s":3,"band":"Medium","q":"trade only"},"scarcity":{"s":2,"band":"Low","q":"supply responds within two years"},"provenance":{"s":2,"band":"Low","q":"for whole wheels; High for grated"}},"factors":{"Valuation":3,"Exit":2,"Custody":1,"Title and transfer":3,"Access":1,"Intangible premium":4},"horizon":{"big":"12–36 months · the wheel","text":"A wheel is inspected and fire-branded at twelve months and gains value with every month of ageing to 36 and beyond; the Parma price list quotes six maturities, so the horizon is chosen by the holder and priced weekly. Credito Emiliano lends against wheels for the ageing period, typically 18–24 months, and has done since 1953."},"exit":{"routes":"Sale to a wholesaler, ageing house or packer at the Parma Borsa Merci price for the maturity; the Consorzio's numbered wheels are the standard unit. A bank-held wheel is sold by the bank's warehouse subsidiary if the loan is not repaid. No retail or exchange route for a private holder.","activity":"The Borsa Merci of 16 October 2026 raised every maturity by €0.10: 12 months €15.15–15.40/kg, 24 months €18.00–18.25, 30 months €18.70–19.05, 36 months and over up to €19.65, with trade described as good; 24-month wheels are 12% dearer than a year ago. About 4.2 m wheels are made a year; Credem's warehouses hold up to 440,000.","cost":"Warehouse rent and turning, insurance and the Consorzio's inspection; a wheel that fails at twelve months is downgraded or scored. Wholesaler margin between the origin price and the €21.80–24.90/kg a whole 24–36 month wheel fetches at retail. Bank finance on wheels runs at ordinary commercial rates plus storage.","time":"A certified wheel sells to the trade within days at the published price; the ageing itself is the wait. The price list is set weekly in Parma and tracked by ISMEA across Mantua, Reggio, Milan and Modena, so there is no discovery delay."},"why":"A whole wheel is a standardised, consortium-certified, individually numbered unit with a published price by age, and one Italian bank has lent against it for seventy years without a loss. That is more financial infrastructure than most markets on this site. The grade is still Σ2 because the holder must be in the trade: the wheel has to be kept turning in a climate-controlled warehouse, sold into a wholesale market that a private holder cannot reach, and eaten within a few years. There is no route for anyone else.","regime":"Prices at origin rose a fifth to a quarter in 2025 as exports passed half of sales and Italians bought less; the only food on this site that a bank will lend against.","regimeAsOf":"19 Oct 2026","since":"First entry. 2025 production 4.19 m wheels (+2.7%); exports 50.5% of sales for the first time; 12-month wheels €13.22/kg (+20.6%), 24-month €15.59/kg (+24.8%); Italian volumes sold −10%. Fortune reports the summer 2026 heat as a threat to maturation and to the cheese banks' stock.","themes":["provenance","climate","custody","tax","access","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"wagyu","name":"Wagyu","why":"Protected designation"},{"slug":"maple-syrup","name":"Maple Syrup","why":"Reserve and quota"},{"slug":"fine-wine","name":"Fine Wine","why":"Ageing as value"}],"sources":10,"url":"/parmigiano-dashboard","exitLabel":"whole wheels","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"Trade only","Wrappers":"Bank lending against wheels (Credem) is the only financial structure","Owns":"The bank owns a lien, not the holder a share"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Administered","Faces":"Wholesaler or ageing house at the Borsa Merci price for the maturity","Cost":"Wholesaler margin; inspection; downgrades"}}]},"climate":{"title":"Climate and supply shock","date":"","rows":[{"section":"The register: exposed markets","cells":{"Driver":"Heat in the ageing warehouses; feed rules; animal disease","Event":"The 2026 heat waves are the live concern for the cheese banks; supply responds within two years","Storable":"Yes, 12–36 months, turned and inspected"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Conditioned","Where":"Wheels in an ageing warehouse, including bank-owned warehouses at Reggio Emilia and Modena","Cost":"Warehouse rent and turning, insurance and the Consorzio's inspection; bank finance at commercial rates plus storage","Fails":"A wheel that fails at twelve months is downgraded or scored; 2026 heat waves are the live concern"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Price list","Route":"Wholesaler, ageing house or packer at the Parma Borsa Merci price for the maturity; a bank's warehouse subsidiary if pledged","Open":"Weekly price; trade buyers only","Liquidity":"Medium, trade only"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"Medium; one consortium sets output and grades every wheel","Regime":"Trade platform; Administered (output)","Who":"Parma Borsa Merci weekly list by maturity; the Consorzio sets production quotas"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"Low for whole wheels; High for grated","Claim":"Identity of grated product","Verifier":"Consorzio inspection and fire-brand on every whole wheel; nothing follows the cheese once grated"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"Trading stock of a dairy or ageing house; a bank's pledge over wheels","UK":"Not a private holding; income tax on the trade","US":"—; Italy: corporate tax; the Credem pledge is a pegno on specified wheels"}}]}}},"pearls":{"slug":"pearls","name":"Pearls","family":"Gems & Jewellery","grade":2,"label":"Restricted","rated":"Physical","asof":"5 Oct 2026","method":"v1.2","axes":{"concentration":{"s":3,"band":"Medium","q":""},"liquidity":{"s":2,"band":"Low","q":""},"scarcity":{"s":3,"band":"Medium","q":"natural High"},"provenance":{"s":3,"band":"Medium","q":""}},"factors":{"Valuation":2,"Exit":1,"Custody":3,"Title and transfer":3,"Access":2,"Intangible premium":2},"horizon":{"big":"10+ years · natural","text":"Natural pearls are held for generations and surface at auction once a decade or less; a strand bought at Christie's or Sotheby's is priced against a handful of prior sales. Cultured pearls do not hold value in the trade; the only investable holding is a producer, where Atlas Pearls on the ASX is the sole listed pure play."},"exit":{"routes":"Natural: Christie's and Sotheby's Geneva, Hong Kong and New York jewellery sales, with a laboratory report confirming natural origin; specialist dealers. Cultured: wholesale auctions in Hong Kong (Paspaley's sealed-bid sale) and Kobe for the trade; jewellers and platforms at a steep discount for the private holder; Atlas Pearls shares on the ASX.","activity":"Christie's Geneva sold a two-strand natural pearl necklace for CHF 4.15 m against CHF 0.8–1.2 m in May 2026; a 16-pearl natural necklace made HK$11.4 m in Hong Kong the same month. China buys about 75% of the world's pearls and its pullback has softened South Sea and left Akoya spring auctions flat. Atlas Pearls booked A$28.7 m of revenue in FY25.","cost":"Auction: seller's commission around 10% negotiable, a buyer's premium above 25% that caps the hammer, and a GIA or SSEF report before consignment. Cultured strands resell at a fraction of retail: a matched 12–13 mm South Sea necklace lists at about $2,000 farm-direct against five figures in a boutique.","time":"Natural pieces wait for a Geneva or Hong Kong sale date (May and November) and are paid 35–45 days after; lab testing adds weeks. Cultured: a dealer offer in days at the dealer's price. Shares: same day."},"why":"Natural pearls trade through a handful of auction houses; cultured goods have a thin resale market. Valuation needs laboratory confirmation of natural origin. Exit is slow and selective.","regime":"Volume abundant, value concentrated: natural and large South Sea pearls firm, commodity freshwater flat.","regimeAsOf":"5 Oct 2026","since":"Re-checked 5 Oct 2026: no new auction, Paspaley or Japanese Akoya production data found since the last update; only retail price guides. Regime and ratings unchanged.","themes":["provenance","substitutes","climate","custody","tax","access","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"coloured-gemstones","name":"Coloured Gemstones","why":"Laboratory report as title"},{"slug":"jade","name":"Jade","why":"Natural vs cultured"},{"slug":"signed-jewellery","name":"Signed Jewellery","why":"Set stones"}],"sources":19,"url":"/pearls-dashboard","exitLabel":"natural and fine cultured","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"Yes: a strand","Wrappers":"Atlas Pearls (ASX), the sole listed pure play","Owns":"A cultured-pearl farmer"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Both: natural at auction, cultured to dealers","Faces":"Geneva, Hong Kong and New York jewels sales for natural pearls with a report; wholesalers and jewellers for cultured strands","Cost":"Seller around 10%; buyer above 25%; cultured strands resell at a steep discount"}}]},"climate":{"title":"Climate and supply shock","date":"","rows":[{"section":"The register: exposed markets","cells":{"Driver":"Warming, disease and red tide on open-water farms","Event":"Supply \"can be wiped out in a season\"; a red tide destroyed Mikimoto's stock in 1892","Storable":"Yes; a strand lasts generations"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Shelf","Where":"A strand, restrung periodically","Cost":"A GIA or SSEF report before consignment","Fails":"Nacre wears; cosmetics and heat damage"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Calendar auction","Route":"Natural: Geneva, Hong Kong, New York jewellery sales with a report confirming natural origin. Cultured: wholesale sealed-bid sales, trade only","Open":"Natural strands surface once a decade or less","Liquidity":"Low"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"Medium","Regime":"Calendar auction","Who":"Natural: Geneva and Hong Kong hammers. Cultured: Paspaley's and others' sealed-bid wholesale sales, trade only"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"Medium","Claim":"Natural vs cultured","Verifier":"X-ray and radiocarbon at GIA or SSEF; a report confirming natural origin is required at auction"}}]},"substitutes":{"title":"Synthetic and substitute pressure","date":"","rows":[{"section":"Substitutes by sector","cells":{"Substitute":"Cultured pearls, commercial from the 1920s (Section II)","Stage":"Complete","Pressure":"All but the top; natural pearl diving ceased to be viable in the Gulf by the 1930s","Survives":"Natural strands with a laboratory report, at auction, once a decade"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"Strand: chattel; Atlas Pearls: equity","UK":"CGT above £6,000","US":"28%"}}]}}},"pgm":{"slug":"pgm","name":"Platinum Group Metals","family":"Metals, Energy & Strategic Materials","grade":5,"label":"Institutional","rated":"Physical metal","asof":"19 Oct 2026","method":"v1.2","axes":{"concentration":{"s":5,"band":"High","q":""},"liquidity":{"s":5,"band":"High","q":""},"scarcity":{"s":3,"band":"Medium","q":""},"provenance":{"s":1,"band":"Low","q":""}},"factors":{"Valuation":5,"Exit":4,"Custody":4,"Title and transfer":5,"Access":4,"Intangible premium":5},"horizon":{"big":"Open-ended","text":"No term applies to metal or ETF shares. Investment holdings are the swing factor in the published balances: H1 2026 ETF outflows alone turned the 2026 platinum forecast from deficit to surplus, so holding periods in this market are short and price-reactive."},"exit":{"routes":"Dealer at the LBMA Platinum or Palladium Price, set twice daily in IBA auctions; NYMEX futures; physically backed ETFs. Rhodium only through dealers, with no benchmark.","activity":"LBMA trade reporting, 12-week average to 9 Oct 2026: US$15.95 bn a week in platinum and US$7.26 bn in palladium, against US$961 bn in gold. Platinum spot turnover June–August was 49% below the same period of 2025.","cost":"Spot liquidity is a fraction of gold or silver, so dealer spreads widen with size; sponge and ingot price differently, and ETF fees run above gold equivalents.","time":"Loco London and Zurich spot settle two business days after trade, as for gold; ETF shares on the exchange cycle."},"why":"Platinum and palladium have twice-daily LBMA benchmark auctions, administered by ICE Benchmark Administration since 1 July 2026, plus NYMEX futures and physically backed ETFs. Spot liquidity is thinner than gold or silver, and rhodium has no exchange benchmark. Custody is standard; supply is concentrated in South Africa and Russia.","regime":"The platinum deficit has become a forecast surplus, made entirely of investors leaving; above-ground stocks are the thinnest in the series. Both metals near 2026 lows.","regimeAsOf":"19 Oct 2026","since":"WPIC's 9 September report, missed at the last update, flipped 2026 from a 297 koz deficit to a 265 koz surplus on H1 investment outflows, and deepened the 2025 deficit to 1,440 koz. Platinum ~$1,630–1,650 on 18–19 Oct, −9% on the month and flat on the year; palladium ~$1,114–1,140, at the bottom of its 52-week range. The deficit claim carried on 5 October is corrected below.","themes":["provenance","sanctions","custody","tax","access","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"gold","name":"Gold","why":"Precious, same vaults"},{"slug":"silver","name":"Silver","why":"Industrial and monetary"},{"slug":"rare-earths","name":"Rare Earths","why":"Strategic supply"}],"sources":31,"url":"/pgm-dashboard","exitLabel":"physical metal","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"Yes: bars and sponge","Wrappers":"Physically backed ETFs; NYMEX","Owns":"Allocated metal; ETF flows are the swing factor in the balance"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Exchange","Faces":"Dealer at the LBMA price; rhodium dealer-only with no benchmark","Cost":"Spreads widen with size; rhodium a dealer's market"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Paper / Vault","Where":"ETF shares; sponge and ingot","Cost":"ETF fees above gold equivalents; dealer spreads widen with size","Fails":"Sponge and ingot price differently; rhodium has no benchmark"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Benchmark","Route":"Dealer at the LBMA Platinum or Palladium Price; NYMEX; ETFs. Rhodium: dealers only, no benchmark","Open":"Daily","Liquidity":"High"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"High","Regime":"Benchmark auction","Who":"LBMA Platinum and Palladium Prices; rhodium by dealer quote, no benchmark"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"Low","Claim":"—","Verifier":"Assay; LBMA/LPPM accredited bars"}}]},"sanctions":{"title":"Sanctions, tariffs and origin","date":"","rows":[{"section":"The register: live measures","cells":{"Instrument":"Tariff (feared)","Measure":"Metal flowed into CME-approved US warehouses on tariff fears in 2025, then reversed","Effect":"The swing factor in the published balances for a year"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"Bars and sponge: chattel. ETF: security","UK":"CGT; 20% VAT on physical; Britannia platinum coins CGT-exempt","US":"28% on physical and physically backed ETFs"}}]}}},"polished-diamonds":{"slug":"polished-diamonds","name":"Polished Diamonds","family":"Gems & Jewellery","grade":3,"label":"Specialist","rated":"Polished stones","asof":"20 Oct 2026","method":"v1.2","axes":{"concentration":{"s":3,"band":"Medium","q":"~90% cut in India, retail fragmented"},"liquidity":{"s":3,"band":"Medium","q":"dealer network and auction, wide spread"},"scarcity":{"s":3,"band":"Medium","q":"large and coloured stones High"},"provenance":{"s":3,"band":"Medium","q":"certificate, undisclosed LGD, country of cutting"}},"factors":{"Valuation":2,"Exit":2,"Custody":4,"Title and transfer":3,"Access":3,"Intangible premium":2},"horizon":{"big":"10+ years · to recover the spread","text":"A polished stone bought at retail starts a third or more under water, because the dealer bid sits far below the asking price. The Rapaport list fell for three years to 2025 and the 1 ct index has only just turned up; natural prices are down about 40% per carat since 2016. Jewellery is held for decades and that is the horizon that lets the spread close."},"exit":{"routes":"Dealers and the Rapaport Trade (RapNet) network, where 1.7 m stones are listed by trade members; consignment to a jeweller; online buyers (Worthy, myGemma); auction for stones over about 2 ct with a GIA report. Signet and the chains do not buy back.","activity":"The Rapaport Trade Diamond Index for 1 ct rose 0.3% in September 2026, a second monthly gain, with 0.30 ct up 15.1% year to date; the Rapaport Price List was raised on 11 September for small high-quality rounds. StoneAlgo's average asking price for a 1 ct natural was $3,820 on 14 October, listings $805–9,850.","cost":"The spread: trade asking prices run 20–40% below the Rapaport list and a dealer bid sits below that, so a private seller realises perhaps 40–60% of retail. Auction adds a seller's commission and 25%+ buyer's premium. Since 24 July 2026 the US has taxed natural polished by country of cutting (India 10%; Russia barred), which widens the gap for stones cut abroad.","time":"A dealer or online buyer quotes in days and pays on receipt; consignment and auction take two to four months. The grading report is the passport, and a stone without one must be re-graded first (two to four weeks)."},"why":"Polished stones are valued stone by stone against dealer price lists, with no independent daily price; a certificate fixes the grade, not the value. Exit runs through dealers or auction over months at a spread that can exceed a third of retail. Custody is simple and grading certificates support title. Access is wide, from a jeweller to a dealer to an auction room. The specific risk is the natural premium: lab-grown is physically identical, retails at a fifth of the price or less, and demand for natural now rests on branding, disclosure rules and buyers who care about the difference.","regime":"A 1 ct natural retails at about $4,200 against $1,000 or less for lab-grown; the US now taxes a polished stone by where it was cut, not mined; and the houses have stayed natural while the mass market went lab-grown. The natural premium is the asset.","regimeAsOf":"20 Oct 2026","since":"Rebuilt as a separate brief from Natural Diamonds, 20 Oct 2026. US duty on natural polished has applied by country of cutting since 24 July 2026 under Section 301: India 10%, South Africa and Russia 12.5% (Russian origin barred regardless), EU and the southern African producers exempt. Signet reported lab-grown at 40% of bridal-band sales and 15% of fashion in Q3 FY26; De Beers put LGD wholesale at about $100/ct in June 2026, down 93% since 2020.","themes":["provenance","substitutes","sanctions","custody","tax","access","tokenisation","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"rough-diamonds","name":"Rough Diamonds","why":"Upstream supply and pricing"},{"slug":"lab-grown-diamonds","name":"Lab-Grown Diamonds","why":"Competing supply"},{"slug":"coloured-gemstones","name":"Coloured Gemstones","why":"Specialist graded stones"},{"slug":"signed-jewellery","name":"Signed Jewellery","why":"Where the stones sell"}],"sources":52,"url":"/polished-diamonds-dashboard","exitLabel":"certified polished","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"Yes: a stone","Wrappers":"Diamond Standard coins and tokens; proposals in Dubai (see Tokenisation)","Owns":"A pooled or single stone priced by the issuer"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Dealer-led; auction for exceptional stones","Faces":"RapNet dealers (1.7 m stones listed); consignment to a jeweller; Worthy and myGemma online; auction above a few carats of fine colour","Cost":"A private seller realises perhaps 40–60% of retail"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Shelf","Where":"A stone with its certificate, in a safe","Cost":"Insurance; custody is simple and the certificate supports title","Fails":"The spread, not the keeping"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Price list","Route":"Dealers and RapNet (asking prices, trade members); consignment to a jeweller; online buyers; auction above a threshold","Open":"On request; dealer bid well below list","Liquidity":"Medium; wide spread"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"Medium; ~90% cut in India, retail fragmented","Regime":"Asking list","Who":"The Rapaport list, sellers' asking prices; trade prices 20–40% below, dealer bids below that"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"Medium; certificate, undisclosed LGD, country of cutting","Claim":"Identity (undisclosed lab-grown); the grade on the certificate","Verifier":"GIA and other laboratories; the same laboratories grade both natural and lab-grown"}}]},"sanctions":{"title":"Sanctions, tariffs and origin","date":"","rows":[{"section":"The register: live measures","cells":{"Instrument":"Tariff; sanction","Measure":"Since 24 Jul 2026 the US taxes natural polished by country of cutting (India 10%); Russian-origin barred regardless of rate","Effect":"Widens the dealer-bid gap for stones cut abroad; a stone's cutting country becomes a priced attribute"}}]},"substitutes":{"title":"Synthetic and substitute pressure","date":"","rows":[{"section":"Substitutes by sector","cells":{"Substitute":"Laboratory-grown (CVD, HPHT), at scale from about 2018 (Section III)","Stage":"Advanced","Pressure":"Commercial white stones, 0.5–3 ct; the US engagement ring first, other jewellery following","Survives":"Large, coloured and provenance-tracked stones; the sector page already rates these High"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"Stone: chattel; Diamond Standard coin: a regulated commodity in the US","UK":"CGT above £6,000; 20% VAT on retail purchase, which the resale does not recover","US":"28%; loose polished enters duty-free, set jewellery does not; India: 1% TCS on purchases over ₹10 lakh"}}]}}},"port":{"slug":"port","name":"Port","family":"Cellar & Collectibles","grade":3,"label":"Specialist","rated":"Bottles","asof":"5 Oct 2026","method":"v1.2","axes":{"concentration":{"s":5,"band":"High","q":"benefício and two family groups"},"liquidity":{"s":3,"band":"Medium","q":""},"scarcity":{"s":3,"band":"Medium","q":"Vintage High"},"provenance":{"s":2,"band":"Low","q":""}},"factors":{"Valuation":3,"Exit":2,"Custody":4,"Title and transfer":4,"Access":3,"Intangible premium":3},"horizon":{"big":"15–30 years","text":"Vintage Port is declared about three years in ten and is drunk twenty to forty years after; the trade buys on declaration and sells to drinkers as the wine approaches maturity. The Liv-ex Port 50 has moved slowly in both directions, up 2.2% in 2026 to August but down 7.2% over five years, so the horizon is set by the wine's own clock rather than the cycle."},"exit":{"routes":"Specialist merchants and brokers (Farr Vintners, BBR, Justerini) for cases in bond; Liv-ex through a member merchant; auction at Sotheby's, Christie's and Bonhams, usually inside a mixed wine sale; iDealwine for older bottles. Shipper-bottled stock with provenance is what the channel wants.","activity":"Thin and concentrated: the Port 50 tracks the ten most recent vintages of five houses (Dow, Fonseca, Graham, Taylor, Warre) because those are the only Ports that trade with any regularity. Fewer lots appear at major auctions than five years ago and spreads have widened.","cost":"Merchant commission of 10% or more on a brokered sale; exchange fees per unit; storage in bond of a few pounds a case a year; auction seller's commission around 10% with a buyer's premium of 25% or more capping the hammer. Bottles out of bond lose duty-suspended status and part of their provenance.","time":"A merchant offer within days for well-known declared vintages; weeks to list and sell through a broker or the exchange; three to six months through auction, paid 35–45 days after the sale."},"why":"Vintage Port trades on a narrow secondary market with occasional auction prices. Bottles keep well in bond, but buyers are concentrated and exit is slow. Provenance is good for shipper-bottled stock.","regime":"Grower crisis at the base while Vintage Port at the apex holds; a thin collectible channel.","regimeAsOf":"5 Oct 2026","since":"Applications for the €12m Douro support scheme for unharvested grapes opened 28 Sep and close 12 Oct; IVDP inspects plots before payment.","themes":["provenance","climate","custody","tax","access","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"fine-wine","name":"Fine Wine","why":"Same merchants"},{"slug":"champagne","name":"Champagne","why":"House-declared vintage"},{"slug":"scotch-whisky","name":"Scotch Whisky","why":"Aged, bonded"}],"sources":33,"url":"/port-dashboard","exitLabel":"bottles","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"Yes: in bond","Wrappers":"None specific; shipper equity private","Owns":"—"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Both","Faces":"Specialist merchants and brokers (Farr, BBR, Justerini); auction for old vintages","Cost":"Merchant 10%+; auction around 10% plus premium"}}]},"climate":{"title":"Climate and supply shock","date":"","rows":[{"section":"The register: exposed markets","cells":{"Driver":"Douro heat and drought; vintage declared three years in ten","Event":"A €12m Douro support scheme for unharvested grapes opened Sept 2026; the benefício system \"in open crisis\"","Storable":"Yes, for decades; a declared vintage is the stored shock"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Vault or bond","Where":"Cases in bond for 15–30 years","Cost":"A few pounds a case a year; merchant commission 10%+","Fails":"Out of bond loses duty-suspended status and part of its provenance"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Price list","Route":"Specialist merchants and brokers for cases in bond; Liv-ex via a member; auction inside mixed wine sales","Open":"Daily, through a merchant","Liquidity":"Medium"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"High, benefício and two family groups","Regime":"Trade platform; Administered (benefício)","Who":"Liv-ex Port 50 via merchants; the IVDP sets the benefício, the shippers declare vintages"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"Low","Claim":"Shipper-bottled status","Verifier":"Shipper and merchant records; the channel wants shipper-bottled stock"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"Bottles in bond: chattel","UK":"HMRC's own example of a wine that may exceed fifty years: chattel rules, not the wasting exemption, for vintage port","US":"28%"}}]}}},"pu-erh-tea":{"slug":"pu-erh-tea","name":"Pu-erh Tea","family":"Cellar & Collectibles","grade":2,"label":"Restricted","rated":"Physical","asof":"20 Oct 2026","method":"v1.2","axes":{"concentration":{"s":5,"band":"High","q":"for factory tea (Dayi); dispersed for mountain tea"},"liquidity":{"s":3,"band":"Medium","q":"for current Dayi; very low above"},"scarcity":{"s":4,"band":"High","q":"for antique; none for new production"},"provenance":{"s":5,"band":"High","q":"wrappers, storage, forgery"}},"factors":{"Valuation":2,"Exit":2,"Custody":2,"Title and transfer":4,"Access":3,"Intangible premium":2},"horizon":{"big":"10–30 years","text":"Raw pu-erh is bought young and held while it ferments; the trade's own data show that only pre-2007 factory cakes have reliably appreciated, while younger 7542s have fallen with the extra years. The horizon is decades, the storage must be right throughout, and the price of a cake is set by its age only once it is old."},"exit":{"routes":"For modern Dayi factory tea, the Fangcun wholesale market in Guangzhou and the Donghe quotation platform, where whole tongs and jian trade between dealers; Taobao and dealer networks for single cakes. For antique and state-era cakes, a handful of Hong Kong specialists and the auction houses (L&H, Poly, Sotheby's), a few dozen lots a year.","activity":"Donghe posts daily quotes for hundreds of Dayi productions: the 2020 7542 peaked near RMB 50,000 a jian (42 cakes) and had fallen to about RMB 29,000 by February 2024. The 7542 is the market's reference; its 20–30% swings set everything else. Antique cakes: a century-old Song Pin Hao made HK$3.5 m this year.","cost":"Dealer spread at Fangcun on the quoted price; auction commissions of 20–25% to the buyer and 10–15% to the seller for antique lots; authentication risk borne by the seller, since Dayi is the most counterfeited tea in the world and a rejected cake is unsaleable. Storage for decades is the hidden cost.","time":"Factory tea in a tong can be sold at Fangcun in days at the quoted price less spread; a single cake or an unusual production takes weeks. Antique cakes wait for a Hong Kong sale and are paid 30–45 days after."},"why":"Two markets share a name. Antique and state-era cakes are valued by a handful of Hong Kong specialists on wrapper, ticket, compression and taste, trade a few dozen lots a year, and are forged at every tier. Modern Dayi factory tea has daily quoted prices on the Donghe platform and a wholesale market at Fangcun, which looks like price discovery until one notices that 95% of it is bought to store, not drink, and that the quotes have halved twice in twenty years. Custody is the asset: a cake stored too dry does not age, too wet is ruined, and the storage history cannot be verified from the outside. Exit for anything but current Dayi is a consignment into a thin Hong Kong sale. Title is simple; everything else is not.","regime":"A century-old cake sells for HK$3.5 m while the factory tea that the speculative market actually trades has lost four-fifths of its value since 2021; the asset appreciates only if stored correctly for decades and is the most counterfeited tea in the world.","regimeAsOf":"20 Oct 2026","since":"First entry. L&H Auction's autumn 2025 sale carried the first complete seven-cake stack of Red Mark Song Pin Hao offered at auction, following its HK$3.5 m hammer for a single cake in spring 2024; Dayi's Xuan Yuan series, the speculative benchmark, had fallen to 380,000 yuan a unit by mid-2025 from 1.88 m in 2021.","themes":["provenance","custody","tax","access","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"tea","name":"Tea","why":"The wider leaf market"},{"slug":"cigars","name":"Cigars","why":"Aged, vintage-dated"},{"slug":"jade","name":"Jade","why":"Chinese collector market"}],"sources":13,"url":"/pu-erh-tea-dashboard","exitLabel":"dry-stored cakes","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"Yes: cakes","Wrappers":"None","Owns":"—"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Dealer-led; auction for antique cakes","Faces":"Fangcun wholesale market and the Donghe quotation platform; Hong Kong auction for pre-1970s tea","Cost":"Dealer spread on the quote; auction 20–25% buyer, 10–15% seller"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Conditioned","Where":"Dry-stored cakes, tongs and jian, for 10–30 years","Cost":"Storage for decades is the hidden cost","Fails":"Wet or careless storage, and a rejected cake is unsaleable"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Counterparty","Route":"Fangcun wholesale market and the Donghe quotation platform for modern Dayi; a handful of dealers for antique cakes","Open":"Daily for current Dayi; rarely above","Liquidity":"Medium for current Dayi; very low above"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"High for factory tea (Dayi); dispersed for mountain tea","Regime":"Trade platform (Dayi); Dealer quote (antique)","Who":"Donghe quotation platform and Fangcun dealers for Dayi; a handful of dealers for antique cakes"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"Very high; wrappers, storage, forgery","Claim":"Identity and age of the cake; storage","Verifier":"Dealer expertise on wrapper, leaf and taste; no laboratory standard; the most counterfeited tea in the world"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"Cakes: chattel","UK":"CGT above £6,000; tea is zero-rated for VAT as food","US":"28% if a collectible; China: 13% VAT in the trade, none on a private sale"}}]}}},"racehorses":{"slug":"racehorses","name":"Racehorses","family":"Cellar & Collectibles","grade":3,"label":"Specialist","rated":"Living asset","asof":"20 Oct 2026","method":"v1.2","axes":{"concentration":{"s":3,"band":"Medium","q":"Kentucky, two stallion fees"},"liquidity":{"s":3,"band":"Medium","q":"calendar-bound"},"scarcity":{"s":2,"band":"Low","q":"renewed yearly"},"provenance":{"s":2,"band":"Low","q":""}},"factors":{"Valuation":2,"Exit":3,"Custody":1,"Title and transfer":4,"Access":4,"Intangible premium":2},"horizon":{"big":"1–4 years · racing","text":"A horse bought as a yearling is resold as a two-year-old in training, raced for two or three seasons, then sold on as a stallion prospect, broodmare or horse of racing age. The holding is bounded by the animal: training costs run from the day of purchase and most horses never cover them, so the horizon is set by results, not by the owner."},"exit":{"routes":"A fixed calendar of auctions: Keeneland (September yearlings; November breeding stock, 3–11 Nov 2026 with 3,397 catalogued; horses of racing age 12 Nov) and Tattersalls (October yearlings; December mares). Private sale, claiming races and syndication of shares sit alongside.","activity":"Keeneland September 2025 grossed a record $531.5 m; Tattersalls October Book 1 2026 set a European yearling record at 4.6 m guineas and one buyer signed for 21% of the sale. Depth is in yearlings and breeding stock; the horses-of-racing-age sale catalogues 125 lots a year.","cost":"Tattersalls charges the vendor 5% of hammer plus an entry fee; Keeneland 5% on bids over $10,000 (minimum $500) and a $1,000 entry fee, with 2.5% on a horse bought back. Vetting, transport, sales preparation and the consignor's fee sit on top. Carry cost while waiting is the heaviest on this site.","time":"Entries close two to three months before a sale; Tattersalls pays the vendor on the 35th day after the lot is sold, provided the buyer has paid. From decision to cash, three to five months if the horse sells at the next suitable sale."},"why":"A racehorse is valued by opinion until it runs, and by its last race afterwards; there is no index, and the same yearling can be worth a tenth or ten times its purchase price within eighteen months. Exit is through a fixed calendar of auctions or a private sale, usually within months, but the asset eats, ages and can break while it waits. Custody is the heaviest on this site: training alone runs to tens of thousands a year, and most horses never earn it back. Title is clean, the registries are old and reliable, and syndication makes a share available to almost anyone.","regime":"Record prices at the top of the yearling market for a sixth year, on a foal crop that shrinks every year and with a buyer base narrow enough that one owner wrote a fifth of Europe's premier sale.","regimeAsOf":"20 Oct 2026","since":"First entry. Keeneland September 2026 closed on 3 October with records for gross, average and median and seventy yearlings at $1 m or more; Tattersalls October Books 1–4 closed on 16 October past 210 m guineas for the first time, with a European record 4.6 m guineas for a yearling colt.","themes":["provenance","climate","custody","tax","access","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"breeding-stallions","name":"Breeding Stallions","why":"Where value ends up"},{"slug":"classic-cars","name":"Classic Cars","why":"Auction, upkeep cost"}],"sources":18,"url":"/racehorses-dashboard","exitLabel":"living asset","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"Yes","Wrappers":"Syndication of shares; racing clubs","Owns":"A share in one horse, its training bill and its results"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Auction-led","Faces":"Keeneland and Tattersalls on a fixed calendar; private sale between trainers in between","Cost":"Vendor 5% of hammer plus entry fee; 2.5% on a buy-back"}}]},"climate":{"title":"Climate and supply shock","date":"","rows":[{"section":"The register: exposed markets","cells":{"Driver":"Fertility, injury and disease; a living asset","Event":"Fertility insurance limited, mortality cover priced per horse; a falcon's value falls after the first moult","Storable":"No; the asset is alive"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Living","Where":"In training, with a trainer","Cost":"Training alone tens of thousands a year; the heaviest carry on the site","Fails":"Most horses never earn it back; the horizon is set by results"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Calendar auction","Route":"Keeneland (September, November), Tattersalls (October, December); horses-in-training sales; claiming races; private sale","Open":"Fixed sale weeks","Liquidity":"Medium, calendar-bound"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"Medium; Kentucky, two stallion fees","Regime":"Calendar auction","Who":"Keeneland and Tattersalls hammer; every yearling price is a derivative of a stallion fee"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"Low","Claim":"—","Verifier":"Stud book, DNA typing, microchip; title is clean and the registries are old and reliable"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"Animal in training: wasting chattel; syndicate share: co-ownership","UK":"CGT-exempt; prize money tax-free for an owner not trading; registered owners reclaim VAT under the Racehorse Owners' scheme","US":"Three-year depreciation for horses placed in service; hobby-loss rules; sale after 24 months as Section 1231"}}]}}},"rare-books":{"slug":"rare-books","name":"Rare Books","family":"Cellar & Collectibles","grade":3,"label":"Specialist","rated":"Printed books and manuscripts","asof":"19 Oct 2026","method":"v1.2","axes":{"concentration":{"s":1,"band":"Low","q":""},"liquidity":{"s":3,"band":"Medium","q":"top manuscripts Low"},"scarcity":{"s":4,"band":"High","q":"fixed stock"},"provenance":{"s":3,"band":"Medium","q":""}},"factors":{"Valuation":2,"Exit":2,"Custody":4,"Title and transfer":3,"Access":4,"Intangible premium":2},"horizon":{"big":"10+ years · libraries never sell","text":"Books are held for a collecting lifetime and sold by the estate; the auction record stretches back centuries and sixteen million results make the price history unusually legible. Supply only falls, because institutional buyers absorb copies permanently, and the market below $10,000 has thinned and moved online while million-dollar lots doubled in two years."},"exit":{"routes":"Christie's and Sotheby's books and manuscripts departments (London, New York, Paris) for lots over about $10,000; specialist houses (Bonhams, Swann, Forum, Dominic Winter); ABAA/ILAB dealers who buy outright or consign; online marketplaces for the trade below.","activity":"Auction sales of books and manuscripts were $1.23 bn in 2025, up 8.2%, with 26 lots over $1 m against 12 two years earlier; the record stands at $43.2 m for a first printing of the US Constitution and $38.1 m for the Codex Sassoon. Rare Book Hub indexes sixteen million auction records.","cost":"Sotheby's standard seller's commission 10%, negotiable above $500,000; buyer's premium 28% to $2 m, which caps the hammer; collation, condition reports and, for manuscripts, provenance research before consignment. Dealers buy at a third to a half below retail.","time":"Consignment closes two to three months before a sale; marquee sales in spring and autumn; payment within 45 days of the sale subject to the buyer settling. Dealer sale in days at a lower price."},"why":"Every copy is unique in condition, binding and provenance, so valuation is by specialist comparison against a deep but uneven record of past sales. Exit is through two or three auction seasons a year or a dealer's placement over months, at commissions of 15–25%. Custody is simple; the risks are condition, completeness and, for the top of the market, theft and forgery.","regime":"A $1.2 billion auction market growing at the top: million-dollar lots doubled in two years while the trade below $10,000 thins and moves online.","regimeAsOf":"19 Oct 2026","since":"First entry. Rare Book Hub's 2025 tally put auction sales of books and collectible paper at $1.23 bn, up 8.2%, with 26 lots above $1 m against 12 in 2023. Sotheby's names books among the categories with \"continued strength\" in a record first half of 2026.","themes":["provenance","custody","tax","access","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"old-masters","name":"Old Masters","why":"Provenance and condition"},{"slug":"stamps","name":"Stamps","why":"Catalogue-driven rarity"},{"slug":"art","name":"Art","why":"Same auction calendar"}],"sources":10,"url":"/rare-books-dashboard","exitLabel":"printed books and manuscripts","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"Yes","Wrappers":"None of scale","Owns":"—"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Both: threshold about $10,000","Faces":"Christie's and Sotheby's above it; Bonhams, Swann, Forum, Dominic Winter; ABA and ILAB dealers for the rest","Cost":"Seller 10%; buyer 28% to $2 m"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Shelf","Where":"A library, dry, dark and stable","Cost":"Collation and condition reports before consignment; insurance","Fails":"Damp, light and handling; completeness"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Calendar auction","Route":"Books and manuscripts departments for lots over about $10,000; specialist houses; dealers","Open":"Several sales a year per house","Liquidity":"Medium; top manuscripts Low"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"Low","Regime":"Calendar auction","Who":"Auction hammers, sixteen million of them on record; dealer asking prices above"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"Medium","Claim":"Completeness and state; manuscript provenance","Verifier":"Collation and condition reports before consignment; provenance research for manuscripts"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"Chattel","UK":"CGT above £6,000; printed books zero-rated for VAT, antiquarian included; manuscripts standard-rated under the margin scheme","US":"28%"}}]}}},"rare-earths":{"slug":"rare-earths","name":"Rare Earths","family":"Metals, Energy & Strategic Materials","grade":3,"label":"Specialist","rated":"Physical oxides and metals","asof":"19 Oct 2026","method":"v1.2","axes":{"concentration":{"s":5,"band":"High","q":"separation (mining lower)"},"liquidity":{"s":3,"band":"Medium","q":""},"scarcity":{"s":3,"band":"Medium","q":""},"provenance":{"s":3,"band":"Medium","q":""}},"factors":{"Valuation":3,"Exit":2,"Custody":3,"Title and transfer":3,"Access":2,"Intangible premium":4},"horizon":{"big":"Years, by contract","text":"There is no exchange and no roll. Supply is sold under multi-year offtake agreements between producers and magnet makers; Arafura's Nolans contract runs five years at 850 t of NdPr a year, and the US floor for MP Materials runs ten. A private holder of oxide has no such counterparty and no stated horizon."},"exit":{"routes":"Sale to a separator, metal maker or magnet producer, almost all in China; a few specialist dealers sell small lots to private buyers and offer buy-back at their own quote. No listed physical vehicle; equities are the practical proxy.","activity":"Price reporting rather than turnover: SMM quoted Pr-Nd oxide at RMB 738,000–740,000/t on 21 October 2026 and recorded one enterprise selling 30 t that day. Western dealer quotes for the same material run $180–240/kg, roughly double the Chinese benchmark.","cost":"The spread between the Chinese benchmark and the ex-China dealer price is the exit cost for a private holder: buy at the dealer tier, sell back at a discount to it. Chinese export licensing, in force since April 2025, governs whether material can move at all.","time":"Weeks to months to find an industrial counterparty for a non-standard lot; dealer buy-backs settle faster at a wider spread. Offtake deliveries are scheduled by contract, not by the holder."},"why":"There is no exchange benchmark. Chinese domestic quotes and the US-floored ex-China tier diverge. Physical oxides and metals can be held, but buyers are few and specialist, and Chinese licensing governs flows. Exit depends on finding an industrial counterparty.","regime":"The two-tier market has inverted: ex-China NdPr now trades below the Chinese benchmark and below the $110 floor. Three weeks to the 10 Nov pause expiry, no extension announced.","regimeAsOf":"19 Oct 2026","since":"Benchmark assesses ex-China NdPr oxide at $95/kg CIF Europe and North America, below the Chinese domestic price (~$107.5) for the first time in the series, as new Western separation output meets thin demand; the 63% ex-China premium carried here since March is withdrawn. SMM Pr-Nd oxide $97.30/kg on 30 Sep, a third cycle under the floor; the CRIA index rose to 263.6 on 9 Oct. As of 11 Oct, Beijing has not extended the suspension of the October 2025 controls past 10 Nov; MOFCOM's 28 Sep statement extended US trade arrangements to 10 Jan 2027 without mentioning rare earths.","themes":["provenance","sanctions","custody","tax","access","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"copper","name":"Copper","why":"Energy-transition metal"},{"slug":"uranium","name":"Uranium","why":"Strategic, state-shaped"},{"slug":"pgm","name":"Platinum Group Metals","why":"Catalyst demand"}],"sources":30,"url":"/rare-earths-dashboard","exitLabel":"physical oxides and metals","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"Small dealer lots","Wrappers":"Equities as the practical proxy; no listed physical vehicle","Owns":"Miners and separators, mostly outside China"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Dealer-led (lots); exchange (equity)","Faces":"Specialist metal dealers for small lots; brokers for shares","Cost":"Dealer spread on oxides; no public bid"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Living / perishable (lots)","Where":"Oxide or metal lots with a dealer; equities as proxy","Cost":"The dealer-tier premium on entry and discount on exit","Fails":"Chinese export licensing since April 2025 governs whether material moves at all"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Counterparty","Route":"Sale to a separator, metal maker or magnet producer, almost all in China; dealer buy-back at the dealer's own quote","Open":"On request","Liquidity":"Medium"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"High, separation (mining lower)","Regime":"Asking list","Who":"Chinese price reporters (SMM) and the two state groups; ex-China dealers quote at a premium and buy back at a discount"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"Medium","Claim":"Purity and origin of oxide lots","Verifier":"Buyer's own assay; no accredited chain outside China"}}]},"sanctions":{"title":"Sanctions, tariffs and origin","date":"","rows":[{"section":"The register: live measures","cells":{"Instrument":"Export control; sanction","Measure":"Chinese export licensing on seven elements since April 2025; US defence ban on Chinese-origin rare earths from 1 Jan 2027; Malaysia raw-ore export ban","Effect":"Whether material can move at all; the ex-China dealer premium is the price of the licence"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"Equity; small dealer lots are chattels","UK":"CGT at share rates","US":"Capital gains at share rates; export controls, not tax, are the constraint (see Sanctions)"}}]}}},"rare-whisky-casks":{"slug":"rare-whisky-casks","name":"Rare Whisky Casks","family":"Cellar & Collectibles","grade":2,"label":"Restricted","rated":"Physical, in bond","asof":"20 Oct 2026","method":"v1.2","axes":{"concentration":{"s":1,"band":"Low","q":"at the cask level; high in the trade (Diageo, Pernod, Edrington)"},"liquidity":{"s":2,"band":"Low","q":"no market, no price list"},"scarcity":{"s":2,"band":"Low","q":"22 m casks and rising"},"provenance":{"s":4,"band":"High","q":"title, duplication, existence"}},"factors":{"Valuation":1,"Exit":1,"Custody":2,"Title and transfer":2,"Access":4,"Intangible premium":2},"horizon":{"big":"10–15 years","text":"Brokers themselves say ten years is the minimum and fifteen for new-make, because value comes from age and the first years add little. The angels take about 2% a year and the strength falls; below 40% abv the cask can no longer be bottled as Scotch. The firms that sold that horizon in 2021–22 were insolvent by 2025."},"exit":{"routes":"Sale through a broker, usually the one that sold the cask; sale to an independent bottler or blender at a bulk price; a handful of dedicated cask auctions; or bottling at the owner's cost and selling the bottles. The Scotch Whisky Association states there is no established market or mechanism for selling a cask.","activity":"A few hundred independent prints a year against 22 million casks in bond: cask auctions report hundreds of thousands of pounds sold in total, and bottle auctions carry the occasional cask lot (a Macallan 1988 hogshead at $266,345).","cost":"Broker commission on sale (10% and up, often undisclosed), annual warehouse rent and insurance, regauge and sample fees, and, on bottling, duty at the full rate plus bottling and labelling before a single bottle is sold. Distillery name restrictions can bar the use of the brand on the label.","time":"Months to find a buyer through a broker; auction cycles are infrequent and lots can be withdrawn unsold. Transfer is a delivery order re-registering the cask at the warehouse, which takes days once a buyer exists."},"why":"There is no regulated market for casks of Scotch whisky, no published price list, and no established mechanism for selling one; the Scotch Whisky Association says so in those words. Valuation is therefore whatever the seller's brochure asserts, and the only independent prints are a few hundred auction lots a year. Exit is through the same brokers who sold the cask, or to a blender at a bulk price, or by bottling at the owner's cost and selling the bottles. Title is the specific hazard: a cask exists only as an entry in a warehousekeeper's records, and a certificate from an intermediary is not a delivery order; when the intermediary fails, the certificate is a claim in its insolvency. Access is the one easy factor, and the industry has made it so.","regime":"Twenty-two million casks in Scottish warehouses, no published price for any of them, and a retail investment industry built on selling the difference; its largest operator collapsed in 2025 with £80 m of client money and casks that could not be found.","regimeAsOf":"20 Oct 2026","since":"First entry. The administrators of Whisky Merchants Trading (Cask 88, Braeburn Whisky) completed the sale of the business to Edinburgh Cask Management (Resolution) in 2026 and are reuniting casks with owners who can prove title; the Scotch Whisky Association reports 2025 exports of £5.36 bn, down 1%, and several distillers have paused production into a stock the Financial Times puts at 1.4 bn litres.","themes":["provenance","custody","tax","access","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"scotch-whisky","name":"Scotch Whisky","why":"The bottled market"},{"slug":"japanese-whisky","name":"Japanese Whisky","why":"Cask demand"},{"slug":"fine-wine","name":"Fine Wine","why":"Bonded storage, title"}],"sources":13,"url":"/rare-whisky-casks-dashboard","exitLabel":"casks in bond","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"Yes: a cask in bond","Wrappers":"Cask-investment firms selling casks and portfolios to retail","Owns":"A certificate from the firm; the firms raised £80m and were insolvent by 2025"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Both: broker-led, a few cask auctions","Faces":"Usually the broker that sold the cask; a bottler or blender at bulk; a handful of cask auctions","Cost":"Broker 10% and up, often undisclosed"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Vault or bond","Where":"A cask in a Scottish bonded warehouse, in the warehouse keeper's records","Cost":"Annual rent and insurance, regauge and sample fees; about 2% a year evaporates; duty at full rate on bottling","Fails":"Below 40% abv it can no longer be bottled as Scotch; title depends on the warehouse keeper's records, not the broker's certificate"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Counterparty","Route":"Broker, usually the one that sold the cask; independent bottler or blender at a bulk price; a few cask auctions; bottling at own cost","Open":"On request, at the broker's quote","Liquidity":"Very low; no market, no price list"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"Low at the cask level; high in the trade (Diageo, Pernod, Edrington)","Regime":"Dealer quote","Who":"The broker, usually the one that sold the cask; no market, no price list"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"Very high; title, duplication, existence","Claim":"Title: a certificate is a claim against the seller, a delivery order is ownership","Verifier":"The bonded warehouse, directly; the broker's paperwork is not verification"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"Cask in an excise warehouse: duty-suspended chattel; title evidenced by the warehouse's records","UK":"The cask firms sold the wasting-asset exemption as a feature; HMRC's position is that it is a question of fact and not to be assumed. Bottling triggers duty at the full rate","US":"28% as alcoholic beverage; no US bond route for a retail holder"}}]}}},"rough-diamonds":{"slug":"rough-diamonds","name":"Rough Diamonds","family":"Gems & Jewellery","grade":2,"label":"Restricted","rated":"Rough stones","asof":"20 Oct 2026","method":"v1.2","axes":{"concentration":{"s":5,"band":"High","q":"De Beers and Alrosa half of world value, rough distribution administered"},"liquidity":{"s":2,"band":"Low","q":"sight and tender calendar, trade buyers only"},"scarcity":{"s":4,"band":"High","q":"Rising; lowest output since 1987, no major new mines"},"provenance":{"s":3,"band":"Medium","q":"KP certificate, G7 sanctions on Russian origin"}},"factors":{"Valuation":1,"Exit":1,"Custody":4,"Title and transfer":4,"Access":2,"Intangible premium":4},"horizon":{"big":"Weeks · processed, not held","text":"Rough is bought at a sight or tender and cut within months; nobody holds it. De Beers sells about 90% of its output to 45–50 sightholders at ten scheduled sights a year; the rest, and all other miners' goods, go by sealed tender on a calendar. The only long horizon is equity in a miner."},"exit":{"routes":"A buyer at tender resells to a manufacturer or on the secondary rough market in Antwerp, Dubai or Surat, where sight boxes change hands at a premium or discount to De Beers' price. Tenders (Petra, Okavango, TAGS, Lucara) are open to registered Kimberley Process buyers; sights only to sightholders. Listed miners: Anglo American (De Beers, for sale), Petra, Lucara, Gem Diamonds.","activity":"De Beers sold 7.1 m ct for $665 m at three sights in Q2 2026 and 4.5 m ct in the fifth cycle at $154/ct; H1 rough sales $1.3 bn, down 23%, with an EBITDA loss of $113 m. In July it made its deepest official price cuts on record and moved to one-line invoicing, so no clean box-by-box comparison exists.","cost":"The secondary rough premium or discount is the exit cost: before July, De Beers boxes ran 5–50% above the secondary market by category, so a sightholder reselling took the loss. Tender buyers pay the house's fee and carry Kimberley certification, insurance and transport.","time":"Sights run five days, ten times a year; tenders close on fixed dates with results in days. Resale of a box in Antwerp or Dubai takes days to weeks. Equity exits the same day."},"why":"Rough is not held; it is processed. Price is set by De Beers at each sight and by sealed tender elsewhere, with no public index and no negotiation; parcels are viewed and bid on by manufacturers and dealers who will cut or re-sell within months. A party outside the sight system can buy at tender, which is why this is Σ2 and not Σ1, but it needs a Kimberley Process-registered importer, the capital for a parcel, a cutter and a route to the polished market, and the exit is the same tender room or a Surat factory. Title is clean (KP certificate, invoice) and custody simple; valuation is the problem, since a parcel's worth depends on what it will yield once cut, and that is the buyer's judgement against the seller's price. The practical route to rough exposure is mining equity or a sightholder's business, neither of which is the stone.","regime":"The De Beers sale is converging: Botswana near a deal to settle at ~25%, leaving the consortium in control and Anglo aiming to exit by year-end. Rough prices still unrepaired; the sightholder list cut to 45–50.","regimeAsOf":"20 Oct 2026","since":"Rebuilt as a separate brief from Natural Diamonds, 20 Oct 2026. Bloomberg (13 Oct): Botswana and the Global Diamond Consortium are near agreement on a structure that lifts Gaborone's stake from 15% to about 25%, with Botswana, Namibia and Angola together below 50%, so control stays private; Botswana had sought a majority in September 2025. Anglo's CEO said last week he hopes to complete by end-2026. De Beers' Q2 sight revenue was $665m (−44%) at $110/ct (−37%); H1 realised price $105/ct, −32%; 2026 guidance 21–26 Mct unchanged. Sight 9 runs 26–30 Oct. Ekati is on care and maintenance.","themes":["provenance","climate","sanctions","custody","tax","access","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"polished-diamonds","name":"Polished Diamonds","why":"Downstream market"},{"slug":"lab-grown-diamonds","name":"Lab-Grown Diamonds","why":"Competing supply"},{"slug":"coloured-gemstones","name":"Coloured Gemstones","why":"Mined stone, tender"}],"sources":57,"url":"/rough-diamonds-dashboard","exitLabel":"tender and sight","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"Trade only","Wrappers":"Mining equity (De Beers via Anglo, Petra, Lucara); a sightholder's business","Owns":"Miners, three of which have failed or been written down since 2023"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Administered (sight) and tender","Faces":"De Beers sights and producer tenders on the way in; the secondary rough market in Antwerp, Dubai and Surat on the way out","Cost":"The secondary premium or discount to the box price, 5–50% by category"}}]},"climate":{"title":"Climate and supply shock","date":"","rows":[{"section":"The register: exposed markets","cells":{"Driver":"Flooding in alluvial ground","Event":"Lucapa entered administration May 2025, hit by falling prices, flooding in higher-grade ground and a blockade","Storable":"Yes; but rough is cut within months"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Vault (in transit)","Where":"Sight box or tender parcel, cut within months","Cost":"Kimberley certification, insurance and transport","Fails":"Nobody holds it; custody is simple and short"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Price list","Route":"Secondary rough market in Antwerp, Dubai or Surat; tenders open to Kimberley Process registrants only","Open":"Ten sights a year; tenders on a calendar","Liquidity":"Low; trade buyers only"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"High; De Beers and Alrosa half of world value, rough distribution administered","Regime":"Administered (sights); Calendar auction (tenders)","Who":"De Beers prices and allocates ten sights a year to 45–50 sightholders; other miners by sealed tender; a secondary box market trades at a premium or discount to the sight price"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"Medium; KP certificate, G7 sanctions on Russian origin","Claim":"Origin, once mixed in Antwerp, Dubai or Surat","Verifier":"Kimberley Process certificate per export (conflict status, not mine); De Beers Tracr for its own goods"}}]},"sanctions":{"title":"Sanctions, tariffs and origin","date":"","rows":[{"section":"The register: live measures","cells":{"Instrument":"Sanction; certification","Measure":"G7 ban on Russian-origin diamonds, phased from 1 Jan 2024; Kimberley Process certificate on every export","Effect":"Origin must be documented at 0.5 ct and above; Antwerp made the verification node; Alrosa's goods excluded from G7 markets"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"Trading stock of a sightholder; Kimberley Process certificate per parcel","UK":"Income tax on the trade; 20% VAT, reverse-charged between registered dealers","US":"—; Botswana and Namibia: royalty and export levy; Dubai: 5% VAT reverse-charged in the trade"}}]}}},"saffron":{"slug":"saffron","name":"Saffron","family":"Aromatics","grade":1,"label":"No route","rated":"Route: none identified","asof":"5 Oct 2026","method":"v1.2","axes":{"concentration":{"s":5,"band":"High","q":""},"liquidity":{"s":1,"band":"Low","q":""},"scarcity":{"s":3,"band":"Medium","q":""},"provenance":{"s":4,"band":"High","q":""}},"factors":{"Valuation":1,"Exit":1,"Custody":1,"Title and transfer":1,"Access":1,"Intangible premium":2},"horizon":{"big":"Under two years · the spice","text":"Saffron loses colouring strength from the day it is dried and is graded on it, so a holding of threads depreciates; the trade turns stock within a season or two. There is no vehicle, no farm route that is practical from outside Iran, and no term to speak of. Σ1 because there is nothing to hold.33"},"exit":{"routes":"A holder of physical saffron sells to a spice trader, packer or re-exporter (Spain, UAE) at the grade the buyer's own test assigns; no exchange, no fund, no listed producer of scale. Iranian supply is sanctioned at the banking layer, which is why so much passes through Dubai and La Mancha labels.33 34","activity":"Price reporting only: Iranian Super Negin wholesale quoted at about US$3,700–3,800/kg in October 2026 by one exporter, US$1,750–1,850/kg on the Iranian exchange-linked dashboard a year earlier, and customs transaction values from US$1,335/kg (Afghanistan) to US$1,731/kg (Spain) in April 2026. The same grade differs twofold between sources in the same week.33 34 35","cost":"The spread between the grade you were sold and the grade the buyer's lab assigns is the exit cost, and it can be the whole premium: ISO 3632 cannot detect common adulterants at low levels, so buyers discount for the doubt. Re-exporters capture the Spanish or Kashmiri label premium the seller never sees.35","time":"Days to weeks to a trader, at the trader's price; the product cannot wait, since colour strength falls with time. No mechanism exists for a private holder to exit at a published price."},"why":"No practical route to exposure exists: no exchange, no investable vehicle, and the spice degrades in storage. Adulteration is widespread and sanctions affect Iranian supply. Graded Σ1 until a route is identified.","regime":"Iranian farm-gate weakness against stable re-export pricing; grade and adulteration set the spread.31","regimeAsOf":"5 Oct 2026","since":"Iranian Super Negin wholesale is quoted around $3,700–3,800/kg in mid-September, little changed year on year (single vendor). In Kashmir, GI-tagged saffron reached Rs 350–400/g by June against Rs 200–250 a year earlier, on Iran-related disruption and a poor local crop. The 2026 harvest begins in late October.3132","themes":["provenance","climate","sanctions","custody","tax","access","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"vanilla","name":"Vanilla","why":"Hand-harvested spice"},{"slug":"frankincense","name":"Frankincense","why":"Smallholder resin"},{"slug":"oud","name":"Oud","why":"No reference price"},{"slug":"dates","name":"Dates","why":"Iranian and Gulf trade"}],"sources":35,"url":"/saffron-dashboard","exitLabel":"none identified","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"No","Wrappers":"None: no exchange, no fund, no listed producer of scale","Owns":"—"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Dealer-led","Faces":"Spice trader, packer or re-exporter at the grade the buyer's own test assigns","Cost":"The grade gap, which can be the whole premium"}}]},"climate":{"title":"Climate and supply shock","date":"","rows":[{"section":"The register: exposed markets","cells":{"Driver":"Winter rain and drought in Khorasan; a one-country crop","Event":"Record c. 422 t in 2021 to c. 272 t in 2022 under prolonged drought, −36%, recovering toward 300 t","Storable":"No: colouring strength falls from the day it is dried"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Living / perishable","Where":"Threads with a trader, for a season or two","Cost":"The grade the buyer's laboratory assigns","Fails":"Colouring strength falls from the day it is dried; a holding depreciates"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"None","Route":"Spice trader, packer or re-exporter at the grade the buyer's own test assigns. No exchange, no fund, no listed producer of scale","Open":"Within a season or two","Liquidity":"Low"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"High","Regime":"Asking list","Who":"Iranian exporters' quotes and an exchange-linked dashboard; the buyer's laboratory sets the grade, and so the price"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"High","Claim":"Grade, adulteration, Iranian origin relabelled","Verifier":"Buyer's laboratory under ISO 3632, which cannot detect common adulterants at low levels"}}]},"sanctions":{"title":"Sanctions, tariffs and origin","date":"","rows":[{"section":"The register: live measures","cells":{"Instrument":"Sanction (banking)","Measure":"Iranian supply is sanctioned at the banking layer","Effect":"Trade re-routes through Dubai and Spanish labels; re-exporters capture the label premium the grower never sees"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"Trading stock","UK":"Income tax; no private holding form exists","US":"—; Iran: sanctions bar US persons entirely"}}]}}},"scotch-whisky":{"slug":"scotch-whisky","name":"Scotch Whisky","family":"Cellar & Collectibles","grade":3,"label":"Specialist","rated":"Bottles","asof":"5 Oct 2026","method":"v1.2","axes":{"concentration":{"s":5,"band":"High","q":""},"liquidity":{"s":3,"band":"Medium","q":"bottles); Low (casks)"},"scarcity":{"s":3,"band":"Medium","q":"closed distilleries High"},"provenance":{"s":4,"band":"High","q":"casks"}},"factors":{"Valuation":3,"Exit":2,"Custody":4,"Title and transfer":3,"Access":3,"Intangible premium":2},"horizon":{"big":"5–10 years · bottles","text":"Bottle collectors and auctioneers describe five- to ten-year holds; the 2023–25 correction means bottles bought at the 2022 peak are mostly still below cost. A sealed bottle does not improve with time, so the horizon is set by scarcity and fashion, not maturation. Casks are a different asset with a different page."},"exit":{"routes":"Monthly online auctions (Whisky Auctioneer, Whisky.Auction, Scotch Whisky Auctions, Whisky Hammer); specialist retailers who buy or consign; Sotheby's and Bonhams for the rarest bottles. No exchange and no dealer bid outside these.","activity":"Whisky Auctioneer alone listed 4,486–5,766 lots a month through 2026 and has sold over 810,000 lots worth more than £300 m since 2013. Depth is in standard releases from live distilleries; trophy bottles appear a few times a year and, in 2024, many failed to meet reserve.","cost":"Seller's commission 5% plus VAT at Whisky Auctioneer, 10% at others; £6 listing and £10 reserve fees; the buyer pays 12.5–15% on top of hammer, which caps the bid. Insured shipping to the auctioneer and, for overseas sales, the buyer's duty and freight sit outside the hammer.","time":"Bottles are received, authenticated and photographed, then listed in the next monthly sale (ten days live); payment within 21 working days of close. From decision to cash, six to ten weeks if the first auction clears the reserve."},"why":"Bottles trade at auction with visible prices, but cask valuation is opaque and cask schemes carry real fraud risk. Exit through auction takes months and incurs fees. Title to casks depends on the warehouse keeper's records.","regime":"Collector bottle market correcting, not collapsing; exports flat in value and down in volume.","regimeAsOf":"5 Oct 2026","since":"Tariff-free US access for Scotch was restored on 24 July 2026, ending the 10% levy in place since April 2025 (and the threatened 25% on single malts). The SWA put the cost at close to £20m a month; no post-tariff export data has been published yet.","themes":["provenance","sanctions","custody","tax","access","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"japanese-whisky","name":"Japanese Whisky","why":"Age and allocation"},{"slug":"rare-whisky-casks","name":"Rare Whisky Casks","why":"Cask ownership risk"},{"slug":"champagne","name":"Champagne","why":"Brand-owner pricing"}],"sources":19,"url":"/scotch-whisky-dashboard","exitLabel":"bottles","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"Yes: bottles","Wrappers":"Diageo and Pernod equity as a diluted proxy","Owns":"Brands and maturing stock among much else"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Both: online auction standard, Sotheby's and Bonhams for trophies","Faces":"Whisky Auctioneer and peers monthly (4,486–5,766 lots a month); specialist retailers who buy or consign","Cost":"Seller 5% plus VAT to 10%; buyer 12.5–15% caps the hammer; £6 listing, £10 reserve"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Shelf (bottles)","Where":"Sealed bottles at home or in specialist storage","Cost":"Low; insured shipping to the auctioneer; buyer pays duty and freight abroad","Fails":"Fill level and seal; a sealed bottle does not improve with time"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Calendar auction","Route":"Monthly online auctions; specialist retailers who buy or consign; Sotheby's and Bonhams for the rarest","Open":"Monthly","Liquidity":"Medium (bottles); Low (casks)"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"High","Regime":"Calendar auction (bottles); Dealer quote (casks)","Who":"Monthly online auctions; distillers' release prices; cask brokers' own quotes"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"High (casks)","Claim":"Bottles: refills and fakes. Casks: title and existence","Verifier":"Auction-house inspection on receipt; radiocarbon dating at SSEF-grade laboratories for age; warehouse delivery order for casks"}}]},"sanctions":{"title":"Sanctions, tariffs and origin","date":"","rows":[{"section":"The register: live measures","cells":{"Instrument":"Tariff","Measure":"10% US levy from April 2025 (25% threatened on single malts); tariff-free access restored 24 Jul 2026","Effect":"Fifteen months of a priced origin in the largest export market; 2025 exports flat in value, down in volume"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"Duty-paid bottles: non-wasting chattel","UK":"CGT above £6,000 a bottle or set; auction houses charge VAT on commission, not on hammer, for private sellers","US":"28%; three-tier distribution law restricts private resale in most states"}}]}}},"signed-jewellery":{"slug":"signed-jewellery","name":"Signed Jewellery","family":"Gems & Jewellery","grade":3,"label":"Specialist","rated":"Period and contemporary pieces by named houses","asof":"19 Oct 2026","method":"v1.2","axes":{"concentration":{"s":3,"band":"Medium","q":"the houses control new supply"},"liquidity":{"s":3,"band":"Medium","q":""},"scarcity":{"s":3,"band":"Medium","q":"period pieces High"},"provenance":{"s":4,"band":"High","q":""}},"factors":{"Valuation":2,"Exit":3,"Custody":4,"Title and transfer":3,"Access":4,"Intangible premium":1},"horizon":{"big":"10+ years · two seasons a year","text":"Signed pieces are held for decades and resurface in Geneva in May and November, Hong Kong and New York in between; the archive number that makes them verifiable also makes them easy to track, so the trade knows when a piece last sold. The premium over materials, often several times, is a fashion premium and moves by house and period over a cycle of years."},"exit":{"routes":"Christie's and Sotheby's Magnificent Jewels (Geneva, Hong Kong, New York) and their online jewels sales; Phillips and Bonhams; specialist dealers in period jewellery; the houses themselves buy back archive pieces selectively. A maker's archive letter or certificate of authenticity is expected before consignment.","activity":"Christie's Geneva, 13 May 2026: CHF 51.9 m ($66.5 m), 99% sold, 84% over high estimate, bidders from 40 countries; Cartier Art Deco tiara CHF 698,500, nearly three times low estimate, Cartier Tiger cuffs CHF 863,600. The November Geneva sale lists nearly 300 lots expected to exceed $25 m, including eight Van Cleef & Arpels mystery-set pieces. Hong Kong Luxury Week H1 2026: HK$958 m live, 95% sold by lot, +32% y/y.","cost":"Sotheby's standard seller's commission 10%, negotiable above $500,000; buyer's premium 28% on the first $2 m since February 2026, which caps the hammer; authentication and, for older pieces, a gem lab report. Dealers buy at a third to a half below auction value.","time":"Consignment closes two to three months before a sale; marquee sales twice a year; payment within 45 days of the sale, subject to the buyer settling. Four to eight months from decision to cash; a dealer sale in days at a lower price."},"why":"A signed piece has a maker, a date and often an archive number, which gives it something a loose stone lacks: an identity that can be verified. But the premium that identity carries, frequently several times the value of the materials, is set by sentiment and fashion. Valuation is by specialist against recent auction comparables; exit is two Geneva seasons a year or a dealer; and the risks are forged signatures, replaced stones and pieces the house will not confirm.","regime":"The maker's name is now most of the price: white-glove sales for Cartier, Van Cleef & Arpels and JAR while unsigned period jewellery sells for its stones.","regimeAsOf":"19 Oct 2026","since":"First entry. Christie's Geneva Magnificent Jewels on 13 May 2026 made $66.5 m with 99% of lots sold and 84% above high estimate; Cartier's 1920 tiara made nearly three times its low estimate and a Tutti Frutti clip $1.35 m. Sotheby's reports luxury sales up 22% to $2.7 bn for 2025.","themes":["provenance","custody","tax","access","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"polished-diamonds","name":"Polished Diamonds","why":"The stones inside"},{"slug":"coloured-gemstones","name":"Coloured Gemstones","why":"Named stones"},{"slug":"watches","name":"Watches","why":"Maison resale"},{"slug":"handbags","name":"Handbags","why":"Brand premium"}],"sources":11,"url":"/signed-jewellery-dashboard","exitLabel":"signed pieces","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"Yes","Wrappers":"Richemont and LVMH equity, heavily diluted","Owns":"The houses, not the pieces"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Auction-led","Faces":"Magnificent Jewels in Geneva, Hong Kong and New York; period-jewellery dealers; the houses' own buy-back for recent pieces","Cost":"Seller 10%, negotiable above $500,000; buyer 28% on the first $2 m"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Shelf","Where":"In a safe, with the archive letter","Cost":"Insurance; authentication and a gem report for older pieces","Fails":"Portable and anonymous once stones are unset; insurance registers are the control"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Calendar auction","Route":"Magnificent Jewels in Geneva (May, November), Hong Kong, New York; the houses themselves buy","Open":"Two seasons a year","Liquidity":"Medium"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"Medium; the houses control new supply","Regime":"Administered (new); Calendar auction (secondary)","Who":"The houses set retail and production; Geneva, Hong Kong and New York hammers set the secondary comparable"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"High","Claim":"Signature and period; replaced stones","Verifier":"The maker's archive letter or certificate (Cartier, Van Cleef), expected before consignment; the archive number makes pieces trackable"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"Piece: chattel; a watch set in it does not make it machinery","UK":"CGT above £6,000; dealers sell under the VAT margin scheme, so no VAT is shown on the price","US":"28%; Switzerland: no capital gains tax on private movables, which is one reason Geneva sells jewels"}}]}}},"silver":{"slug":"silver","name":"Silver","family":"Metals, Energy & Strategic Materials","grade":5,"label":"Institutional","rated":"Physical metal","asof":"19 Oct 2026","method":"v1.2","axes":{"concentration":{"s":3,"band":"Medium","q":""},"liquidity":{"s":5,"band":"High","q":""},"scarcity":{"s":3,"band":"Medium","q":""},"provenance":{"s":1,"band":"Low","q":""}},"factors":{"Valuation":5,"Exit":5,"Custody":4,"Title and transfer":5,"Access":5,"Intangible premium":5},"horizon":{"big":"Open-ended","text":"Held as metal or ETF shares with no term. Storage and insurance cost more per dollar than gold because of weight and volume, which argues against short holds in physical form."},"exit":{"routes":"Dealer or bullion bank at the LBMA Silver Price; physically backed ETFs, the largest of which held 491 Moz at 31 March 2026; COMEX futures.","activity":"LBMA trade reporting averaged 485 Moz a day in Q2 2026, worth US$35.8 bn. London clearing transferred 175.1 Moz a day in August.","cost":"Wholesale spreads on 1,000 oz bars are narrow; retail bar and coin premiums over spot are materially wider, and vaulting is charged on weight.","time":"Loco London spot settles two business days after trade; ETF shares on the exchange cycle."},"why":"The LBMA Silver Price, set once daily at noon in London, and liquid ETFs give daily valuation and quick exit. Storage costs more than gold per dollar held because of weight and volume, but custody is standard. Title and transfer are standardised.","regime":"Through $60: ~$57 in mid-October, down a tenth on the month after the Fed's September hike took 10-year yields past 5%. The year-on-year gain has shrunk to single digits.","regimeAsOf":"19 Oct 2026","since":"Silver $57.26 on 18 Oct, from $61.4 at the last update; −9% on the month, +7% on the year as the October 2025 squeeze drops into the base. LBMA's Q3 report puts the quarter at +4.3% inside a $55–70 range and the gold:silver ratio at 69. COMEX registered stock has rebuilt to 103 Moz; London vaults hold 28,985 t, up 3.2% on the quarter. Two inventory figures carried since launch are corrected below.","themes":["provenance","custody","tax","access","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"gold","name":"Gold","why":"Monetary metal, same fix"},{"slug":"pgm","name":"Platinum Group Metals","why":"Industrial demand"},{"slug":"copper","name":"Copper","why":"Exchange-traded"}],"sources":28,"url":"/silver-dashboard","exitLabel":"physical metal","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"Yes: bars and coins","Wrappers":"Physically backed ETFs (largest held 491 Moz); COMEX","Owns":"Allocated metal"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Exchange","Faces":"Dealer or bullion bank at the LBMA Silver Price","Cost":"Narrow on 1,000 oz bars; retail coin premiums materially wider"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Paper / Vault","Where":"ETF shares; 1,000 oz bars in vault","Cost":"Vaulting charged on weight; storage and insurance cost more per dollar than gold","Fails":"Bulk; retail bar and coin premiums materially wider"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Benchmark","Route":"Dealer at the LBMA Silver Price; ETFs; COMEX","Open":"Daily","Liquidity":"High"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"Medium","Regime":"Benchmark auction","Who":"LBMA Silver Price; COMEX"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"Low","Claim":"—","Verifier":"Assay; accredited vault chain"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"Bars: chattel. Britannias: legal tender. ETF: security","UK":"Bars CGT and 20% VAT on purchase; coins CGT-exempt but VAT-able","US":"28%; the VAT gap is why UK retail silver sits in Guernsey or bond"}}]}}},"stamps":{"slug":"stamps","name":"Stamps","family":"Cellar & Collectibles","grade":2,"label":"Restricted","rated":"Classic issues and rarities","asof":"19 Oct 2026","method":"v1.2","axes":{"concentration":{"s":1,"band":"Low","q":""},"liquidity":{"s":2,"band":"Low","q":""},"scarcity":{"s":4,"band":"High","q":"at the apex; abundant below"},"provenance":{"s":3,"band":"Medium","q":""}},"factors":{"Valuation":2,"Exit":1,"Custody":5,"Title and transfer":3,"Access":4,"Intangible premium":1},"horizon":{"big":"10+ years · a generation","text":"Great rarities change hands once a decade or less; the 1c Magenta sold in 1970, 1980, 2014 and 2021, and fell in price only on the last occasion. Ordinary classic material is held for a collecting lifetime and sold by the estate, into a buyer base that is shrinking and ageing, which is why the middle of the market has fallen for two decades."},"exit":{"routes":"Specialist auction houses (Siegel in New York, Spink and Stanley Gibbons in London, Corinphila, David Feldman) for rarities with expertising certificates; Sotheby's for the very top; dealer purchase or consignment; postal and online auctions for the rest. Stanley Gibbons fractionalised the 1c Magenta into shares in 2021.","activity":"The 1c Magenta made $8.3 m at Sotheby's in June 2021 against a $10–15 m estimate, down from $9.48 m in 2014; the Inverted Jenny plate block $4.9 m against $5–7 m. Below the trophies, stamps typically realise 10–30% of catalogue value at auction, and a 2026 postal sale priced a lifetime Stanley Gibbons collection at 30–35% of catalogue against the 80% originally paid.","cost":"Auction seller's commission around 10–15% plus a buyer's premium of 20–25% that caps the hammer; expertising certificates for anything valuable; dealer buy-in at a fraction of catalogue. The gap between catalogue value and realised price is the real cost of exit.","time":"Dealer sale in days at the dealer's price; specialist auctions run on a seasonal calendar with consignment two to four months ahead and payment 30–45 days after. Rarities are timed to the one sale a year that will draw the two or three bidders who matter."},"why":"Catalogue prices exist for every stamp ever issued, which gives the illusion of a benchmark; actual realisations for all but the rarest items run at a fraction of catalogue and fall as collectors die faster than they are replaced. Exit for a serious collection means a specialist auction, months of preparation and 15–25% in fees, and a weak result is common. Custody is trivial; the risks are condition, regumming and forgery, which only a certificate from an expert committee controls.","regime":"A shrinking collector base and an ageing one: the great rarities still make seven figures, but the only stamp ever to sell for less than its previous price did so in 2021, and the middle of the market has fallen for two decades.","regimeAsOf":"19 Oct 2026","since":"First entry. The British Guiana 1c Magenta, bought by Stanley Gibbons for $8.3 m in June 2021 and fractionalised into 80,000 \"Pieces\" at £100, remains on loan to the Smithsonian National Postal Museum; no sale above $5 m has occurred since. Chinese classic material continues to set the running in Hong Kong.","themes":["provenance","custody","tax","access","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"coins","name":"Coins","why":"Graded and catalogued"},{"slug":"rare-books","name":"Rare Books","why":"Census-based rarity"},{"slug":"fossils","name":"Fossils & Meteorites","why":"Specialist auctions"}],"sources":11,"url":"/stamps-dashboard","exitLabel":"classic issues and rarities","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"Yes","Wrappers":"A dealer's share scheme in one $8.6m stamp (Stanley Gibbons, £8m total, 2021)","Owns":"A share in one stamp, the dealer bearing vault and insurance"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Auction-led","Faces":"Siegel, Spink, Stanley Gibbons, Corinphila, Feldman with expertising certificates; dealers buy at a fraction","Cost":"Seller 10–15%; buyer 20–25%; dealer buy-in far below"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Shelf","Where":"Albums and stockbooks, dry and dark","Cost":"Expertising certificates for anything valuable","Fails":"Humidity, light, gum damage; a dealer's vault scheme is the fractional precedent"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Calendar auction","Route":"Specialist houses (Siegel, Spink, Stanley Gibbons, Corinphila, Feldman) with expertising certificates; dealers","Open":"Rarities once a decade; the 1c Magenta sold in 1970, 1980, 2014 and 2021","Liquidity":"Low"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"Low","Regime":"Calendar auction","Who":"Specialist house hammers; Stanley Gibbons catalogue as an asking list"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"Medium","Claim":"Regumming, repairs, forged overprints","Verifier":"Expertising certificates (Philatelic Foundation, RPSL, BPA) required for rarities"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"Chattel; the Stanley Gibbons share scheme a contractual fractional interest","UK":"CGT above £6,000; a collection may be a set; dealers under the margin scheme","US":"28%"}}]}}},"tea":{"slug":"tea","name":"Tea","family":"Crops","grade":3,"label":"Specialist","rated":"Route: listed plantation companies","asof":"5 Oct 2026","method":"v1.2","axes":{"concentration":{"s":5,"band":"High","q":""},"liquidity":{"s":3,"band":"Medium","q":""},"scarcity":{"s":2,"band":"Low","q":"Uji tencha High"},"provenance":{"s":3,"band":"Medium","q":""}},"factors":{"Valuation":3,"Exit":3,"Custody":4,"Title and transfer":3,"Access":3,"Intangible premium":2},"horizon":{"big":"Equity · bushes 5 yrs to tencha","text":"The route is listed plantation companies, so the horizon is an equity holding. The scarce tier cannot be held: tencha is auctioned in May and milled within months, and a new field needs about five years before its leaf is matcha-grade, which is why the 2024–26 price tripling has no quick supply answer."},"exit":{"routes":"Shares in listed tea groups (Ito En in Tokyo; Indian and Kenyan plantation companies for bulk grades) through any broker. Leaf itself exits only through the prefectural auctions (Kyoto, Kagoshima) or the Mombasa and Kolkata bulk auctions, both trade-only.","activity":"Kyoto first-flush tencha averaged ¥17,797/kg to 19 June 2026 against ¥14,144 in 2025 and ¥5,402 in 2024, even with a 21% larger first flush; the Kyoto opening auction on 13 May 2026 printed ¥13,972/kg, 1.7× the 2025 record, and Kagoshima ¥19,095. Bulk CTC at Mombasa and Kolkata trades in the low single dollars a kilo.","cost":"Equity: brokerage and spread. Leaf: auction commission and the grower's share of handling; for buyers abroad, Uji ceremonial wholesale runs US$200–500/kg at 10–25 kg minimums, with everything below about US$100 a counterfeit signal.","time":"Shares exit the same day. Tencha is sold at a dated spring auction and allocated for the year; heritage makers have moved to allocation-only sales, so a buyer outside the trade waits a season or pays the dealer tier."},"why":"No exchange benchmark exists for premium tea; the route is listed plantation companies, which carry broad operating exposure. Auction prices cover bulk grades only. The scarce tier, Uji tencha, cannot be held directly.","regime":"Bulk auction grades flat while the matcha and Uji tencha tier runs short; a two-speed market.","regimeAsOf":"5 Oct 2026","since":"Kyoto’s Uji tea market closed its 2026 season on 31 July with machine-harvested tencha averaging a record ¥17,250/kg, highest since records began in 1996 and above the ¥13,972 opening. Fields shifted to tencha pushed sencha, gyokuro and bancha prices up ~30% to more than double: the matcha squeeze has become a wider Japanese tea squeeze.","themes":["provenance","climate","sanctions","custody","tax","access","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"pu-erh-tea","name":"Pu-erh Tea","why":"Aged collector tea"},{"slug":"coffee","name":"Coffee","why":"Auction-priced crop"},{"slug":"manuka-honey","name":"Mānuka Honey","why":"Premium origin"}],"sources":18,"url":"/tea-dashboard","exitLabel":"listed plantation companies","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"No: leaf is milled within months","Wrappers":"Listed plantation groups (Ito En; Indian and Kenyan producers)","Owns":"Operating companies; Ito En is a beverage group"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Exchange (equity); auction (leaf, trade only)","Faces":"Broker for shares; the prefectural tea auction for leaf, licensed buyers only","Cost":"Brokerage; auction commission on leaf"}}]},"climate":{"title":"Climate and supply shock","date":"","rows":[{"section":"The register: exposed markets","cells":{"Driver":"Spring frost and shading in Uji; a five-year lag on new fields","Event":"Kyoto tencha auction average ¥5,402/kg (2024) to ¥14,541 (2025), +169%; one of the strongest harvests in decades \"and prices do not fall\"","Storable":"Tencha is milled within months; the holding is plantation equity"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Paper (equity); perishable (leaf)","Where":"Plantation shares; tencha milled within months","Cost":"Brokerage; auction commission on leaf","Fails":"The scarce tier cannot be held"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Calendar auction","Route":"Leaf through prefectural auctions (Kyoto, Kagoshima) or Mombasa and Kolkata; capital through listed plantation groups","Open":"Tencha once a year in May; equity daily","Liquidity":"Medium"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"High","Regime":"Calendar auction","Who":"Prefectural auctions (Kyoto, Kagoshima) for tencha; Mombasa and Kolkata for bulk"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"Medium","Claim":"Uji origin of ceremonial matcha","Verifier":"Prefectural auction records; price itself is the signal (below about US$100/kg is a counterfeit flag)"}}]},"sanctions":{"title":"Sanctions, tariffs and origin","date":"","rows":[{"section":"The register: live measures","cells":{"Instrument":"Tariff","Measure":"15% US tariff on Japanese imports adds to café costs for matcha","Effect":"Landed cost in the largest matcha export market"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"Equity in plantation and beverage groups","UK":"CGT at share rates","US":"Share rates; Japanese withholding on dividends"}}]}}},"truffles":{"slug":"truffles","name":"Truffles","family":"Rare Foods","grade":2,"label":"Restricted","rated":"Route: truffle orchards","asof":"5 Oct 2026","method":"v1.2","axes":{"concentration":{"s":3,"band":"Medium","q":""},"liquidity":{"s":1,"band":"Low","q":"white); Medium (black)"},"scarcity":{"s":5,"band":"High","q":"white); Low (black)"},"provenance":{"s":4,"band":"High","q":""}},"factors":{"Valuation":1,"Exit":1,"Custody":2,"Title and transfer":2,"Access":2,"Intangible premium":2},"horizon":{"big":"5–8 years to first yield · orchards","text":"The truffle perishes in days, so the only thing that can be held is the orchard. Black truffle orchards first yield five to eight years after planting and reach full production after ten to fifteen; white truffle cultivation has produced only experimental harvests. The horizon is agricultural: a land holding with a decade before cash flow."},"exit":{"routes":"Sale of the orchard as farmland with trees; produce sold weekly through wholesale markets (Richerenches in Vaucluse, Saturdays, mid-November to mid-March; Carpentras; Alba's weekend market from 10 October to 6 December) or to dealers and restaurants direct. The charity auction at Alba is publicity, not a route.","activity":"Alba white truffle averaged €4,727/kg on 21 October 2026 (€3,200 for small, €6,000 for over 50 g); black truffle wholesale on the Carpentras mercuriale ran €150–700/kg across the 2025–26 season, €700–1,000 in peak weeks at Richerenches. Orchard sales are private and unrecorded.","cost":"Produce: market and dealer margins between the €700–1,000 wholesale and €800–1,500 retail for black; grading and spoilage losses fall on the seller. Orchard: agent and legal fees on a land sale, and a buyer who will discount unproven yield.","time":"Produce: sold within the week it is dug, cash at market. Orchard: months to a year, as for any specialist agricultural property; valuation depends on yield history the seller may not yet have."},"why":"White truffles are priced weekly at Alba and other markets and perish within days. Black truffle orchards first yield five to eight years after planting; white truffle cultivation has produced only small experimental harvests, first recorded in France in 2019. The route is truffle orchards, so exit means selling land.","regime":"White Alba prices set weekly by season and weather; cultivated black supply expanding and softening.","regimeAsOf":"5 Oct 2026","since":"The 96th Alba White Truffle Fair opens 10 October and runs to 6 December. No 2026 season prices have been published yet; the regime line stands until the first weekly Alba boards are posted.","themes":["provenance","substitutes","climate","custody","tax","access","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"caviar","name":"Caviar","why":"Perishable, grade-priced"},{"slug":"bluefin-tuna","name":"Bluefin Tuna","why":"Season and auction"},{"slug":"saffron","name":"Saffron","why":"Hand-gathered"}],"sources":15,"url":"/truffles-dashboard","exitLabel":"truffle orchards","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"The orchard","Wrappers":"None","Owns":"—"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Administered; a charity auction for show","Faces":"Wholesalers and restaurant buyers at weekly market prices; the Alba auction sets headlines, not the price","Cost":"Wholesaler margin; the perishability clock"}}]},"climate":{"title":"Climate and supply shock","date":"","rows":[{"section":"The register: exposed markets","cells":{"Driver":"Summer rain and autumn temperature; white truffle not cultivable","Event":"White truffle cultivation has produced only small experimental harvests, first recorded in 2019","Storable":"No: the truffle perishes in days; only the orchard is held"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Living / perishable","Where":"The orchard; the truffle perishes in days","Cost":"Grading and spoilage losses fall on the seller; a decade before cash flow","Fails":"Nothing but the orchard can be held"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Counterparty","Route":"Orchard sold as farmland with trees; produce weekly through Richerenches, Carpentras, Alba in season","Open":"Orchard on request; produce weekly, November to March","Liquidity":"Low (white); Medium (black)"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"Medium","Regime":"Calendar auction","Who":"Weekly wholesale markets (Richerenches, Carpentras, Alba) in season"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"High","Claim":"Species (Alba white vs lookalikes); origin","Verifier":"Market inspectors at Alba and Richerenches; dealer expertise"}}]},"substitutes":{"title":"Synthetic and substitute pressure","date":"","rows":[{"section":"Substitutes by sector","cells":{"Substitute":"Cultivated black truffle orchards (first yield 5–8 years); synthetic truffle aroma in oils and sauces. White truffle cultivation remains experimental","Stage":"Advanced (black); Latent (white)","Pressure":"Black truffle, rated Low scarcity on the sector page for this reason","Survives":"White Alba truffle, rated High: no orchard produces it"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"Orchard: land; the truffle is trading stock","UK":"Agricultural property relief on the land; income on the crop","US":"Farm assets; France: cash sales of wild truffles at markets largely sit outside the recorded economy"}}]}}},"uranium":{"slug":"uranium","name":"Uranium","family":"Metals, Energy & Strategic Materials","grade":4,"label":"Accessible","rated":"Route: physical trust (U3O8 in licensed storage)","asof":"19 Oct 2026","method":"v1.2","axes":{"concentration":{"s":5,"band":"High","q":"Kazatomprom and Cameco; Russia in enrichment"},"liquidity":{"s":3,"band":"Medium","q":"spot thin, term deep"},"scarcity":{"s":3,"band":"Medium","q":"new mines 7–10 years out"},"provenance":{"s":2,"band":"Low","q":"licensed custody and material accounting"}},"factors":{"Valuation":4,"Exit":4,"Custody":3,"Title and transfer":4,"Access":3,"Intangible premium":5},"horizon":{"big":"Open-ended, via the trust","text":"The trust has no term and pays no distribution; return is the uranium price plus the change in the unit's discount or premium to the metal. Utilities contract for five to ten years; the trust's holders are the only short-horizon money in the market, and their exit shows up as the discount."},"exit":{"routes":"Sell units of the Sprott Physical Uranium Trust on the TSX (U.U in US dollars, U.UN in Canadian) through any broker; Yellow Cake plc in London; CME futures, which are thin. The trust does not redeem units for metal in practice.","activity":"The trust held 81,697,348 lb of U3O8 worth about US$7.35 bn on 16 October 2026, 0.2367 lb per unit. Spot activity behind it is a handful of transactions a week: three in the week to 10 October at $89.70/lb.","cost":"Management expense ratio 0.71% a year, plus brokerage. The material cost is the discount: units closed 12.95% below the value of their uranium on 16 October, after 63 straight discount days in Q3, so a seller realises roughly $14/lb less than spot.","time":"Exchange trade, settled on the standard equity cycle. Exiting the uranium itself, rather than the unit, is not available to a private holder."},"why":"An individual cannot hold uranium: it is licensed material, stored only at converters' facilities in Canada, France and the United States. But a listed closed-end trust holds 82 million pounds there and prices it daily, so exposure is a brokerage trade with full transparency on what is owned. The grade stops at Σ4 because the trust's unit can trade 10–15% away from the metal it holds, because the published spot price is a consultants' estimate from a thin market, and because the material is subject to export control and, for Russian-origin supply, sanction.","regime":"Spot has sat at $89–90/lb for three weeks while the long-term contract price holds at $97, its highest since 2007; the physical trust trades at a 13% discount to the uranium it holds.","regimeAsOf":"19 Oct 2026","since":"First entry. Spot $89.90/lb on 17 Oct 2026; TradeTech long-term $97/lb since June, the highest since July 2007; SPUT 81.7 m lb, NAV $21.61, unit price $18.81, a 12.95% discount. Cameco's first-half Canadian production fell 5% on Saskatchewan flooding; Paladin's Langer Heinrich output fell 19% quarter on quarter.","themes":["provenance","climate","sanctions","custody","tax","access","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"oil-gas","name":"Oil & Gas","why":"Energy, long contracts"},{"slug":"rare-earths","name":"Rare Earths","why":"Strategic supply"},{"slug":"copper","name":"Copper","why":"Mine supply cycle"}],"sources":12,"url":"/uranium-dashboard","exitLabel":"physical trust","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"No: licensed custody only","Wrappers":"Sprott Physical Uranium Trust; Yellow Cake plc; miners","Owns":"U3O8 in converter storage; units trade 10–15% from the metal and are not redeemed"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Exchange (wrapper)","Faces":"Any broker for trust units; the metal itself trades by private bilateral deal, a handful a week","Cost":"0.71% a year; a 13% discount to the metal"}}]},"climate":{"title":"Climate and supply shock","date":"","rows":[{"section":"The register: exposed markets","cells":{"Driver":"Flooding at Saskatchewan mines","Event":"Cameco H1 2026 production −5% on Saskatchewan flooding","Storable":"Yes, indefinitely, in licensed custody"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Paper (trust)","Where":"U3O8 in licensed converter storage, held by the trust","Cost":"0.71% a year; the unit's discount to metal (12.95% on 16 Oct 2026)","Fails":"The trust does not redeem for metal; export control on the material"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Benchmark","Route":"Sell Sprott Physical Uranium Trust units on the TSX; Yellow Cake in London. The trust does not redeem for metal","Open":"Daily, at a discount or premium to metal","Liquidity":"Medium; spot thin, term deep"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"High; Kazatomprom and Cameco; Russia in enrichment","Regime":"Exchange (units); consultants' estimate (metal)","Who":"The published spot price is a consultants' estimate from a thin market; term contracts are bilateral"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"Low; licensed custody and material accounting","Claim":"Russian-origin material under sanction","Verifier":"Licensed converters; state material accounting"}}]},"sanctions":{"title":"Sanctions, tariffs and origin","date":"","rows":[{"section":"The register: live measures","cells":{"Instrument":"Sanction; export control","Measure":"US ban on Russian enriched uranium imports from 2028, with waivers until then; material subject to export control","Effect":"Enrichment, not mining, is the choke point; the trust holds material in licensed custody"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"Trust unit (Canadian closed-end trust); Jersey plc; physical only under licence","UK":"CGT on units; reporting-fund status to check","US":"PFIC: a QEF election is offered by the trust; without it, gains taxed as ordinary income with an interest charge"}}]}}},"vanilla":{"slug":"vanilla","name":"Vanilla","family":"Aromatics","grade":2,"label":"Restricted","rated":"Route: flavour houses and exporters","asof":"5 Oct 2026","method":"v1.2","axes":{"concentration":{"s":5,"band":"High","q":""},"liquidity":{"s":1,"band":"Low","q":""},"scarcity":{"s":2,"band":"Low","q":""},"provenance":{"s":3,"band":"Medium","q":""}},"factors":{"Valuation":2,"Exit":2,"Custody":2,"Title and transfer":3,"Access":2,"Intangible premium":4},"horizon":{"big":"One to two seasons · beans","text":"Cured vanilla keeps its vanillin for a year or two under vacuum and then loses it; the trade turns stock within the season and speculators who held through 2018–23 took the $600-to-$50 round trip. The route is flavour houses and exporters, whose horizon is a procurement contract, not a hold."},"exit":{"routes":"Beans: sale to an exporter in Madagascar at or above the official minimum, or to an importer or flavour house abroad. Equity: shares in diversified flavour and ingredient groups (Symrise, Givaudan, IFF), where vanilla is a fraction of revenue; no listed pure play.","activity":"Madagascar's 2026 crop is projected at 3,000–3,500 t against inventories built over several years. Grade A FOB is quoted anywhere from $60–120/kg (one importer) to $140–260/kg (indicative 2026 export ranges) and $188–218/kg (a price-reporting forecast); extraction grades near $30/kg. The spread between sources is itself the market.","cost":"Official minimum export prices ($50/kg black, $25 long red, $15 cuts) set a floor that is not always respected; exporter and importer margins between FOB and the $150–280/kg landed-to-retail ladder; grading disputes on vanillin content and moisture fall on the seller.","time":"Beans move within weeks of curing when an exporter will take them; in an oversupplied year a seller waits a season or discounts. Equity exposure exits on exchange the same day."},"why":"Exporters set prices with no exchange, and cured beans lose quality over time. The most direct route is flavour houses and exporters, few of them pure exposure. Madagascar's regulatory changes add to the uncertainty.","regime":"Third price cycle of structural oversupply: exports ~$40/kg average; green-vanilla floor reinstated at ~$2.34/kg in June 2026.","regimeAsOf":"5 Oct 2026","since":"In late June 2026 Madagascar set a green-vanilla floor of 10,000 Ariary/kg (~$2.34) for pods over 13 cm. Trade reference prices: $15 cuts, $25 long, $50 gourmet. A 3,000–3,500 t crop is projected for 2026.","themes":["provenance","substitutes","climate","custody","tax","access","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"saffron","name":"Saffron","why":"Hand-pollinated spice"},{"slug":"cocoa","name":"Cocoa","why":"Tropical crop, futures contrast"},{"slug":"frankincense","name":"Frankincense","why":"Cured natural product"}],"sources":18,"url":"/vanilla-dashboard","exitLabel":"flavour houses and exporters","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"No","Wrappers":"Symrise, Givaudan, IFF equity, where vanilla is a fraction of revenue","Owns":"Diversified flavour groups"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Administered","Faces":"Exporters and the flavour houses on contract","Cost":"Exporter margin; curing and grading risk"}}]},"climate":{"title":"Climate and supply shock","date":"","rows":[{"section":"The register: exposed markets","cells":{"Driver":"Cyclones over Madagascar's SAVA region; a single-origin crop","Event":"$35–65/kg before 2014; $500–800 in 2016–19 on cyclone losses, hoarding and early harvesting; $250 floor 2020–23; $50 minimum now not always respected","Storable":"A year or two under vacuum, then vanillin is lost; the 2018–23 holders took the round trip"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Living / perishable","Where":"Cured beans under vacuum, one to two seasons","Cost":"Exporter and importer margins; grading disputes fall on the seller","Fails":"Vanillin is lost after a year or two"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Counterparty","Route":"Exporter in Madagascar at or above the official minimum; importer or flavour house abroad; diversified flavour-group equity","Open":"Within the season","Liquidity":"Low"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"High","Regime":"Administered (floor); Dealer quote","Who":"Madagascar's official minimum export prices; importers' and flavour houses' bids above them"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"Medium","Claim":"Grade and moisture; vanillin content","Verifier":"Importer's inspection and assay"}}]},"substitutes":{"title":"Synthetic and substitute pressure","date":"","rows":[{"section":"Substitutes by sector","cells":{"Substitute":"Synthetic vanillin, from guaiacol or lignin; fermentation-derived \"natural\" vanillin more recently. Natural pods supply under 1% of the flavour market, about 50 t of vanillin a year","Stage":"Complete","Pressure":"The entire industrial flavour market, a century ago. Natural vanilla is a premium-label ingredient, which is why its price could run from $20 to $600 a kilo and back without the flavour market noticing","Survives":"Madagascar Bourbon pods for \"natural\" labelling; a speculative bean market with no floor"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"Trading stock; flavour-house equity","UK":"Income tax on stock; CGT on shares","US":"Share rates"}}]}}},"vintage-guitars":{"slug":"vintage-guitars","name":"Vintage Guitars & Instruments","family":"Cellar & Collectibles","grade":3,"label":"Specialist","rated":"Physical","asof":"20 Oct 2026","method":"v1.2","axes":{"concentration":{"s":1,"band":"Low","q":"fixed stock dispersed among private owners"},"liquidity":{"s":3,"band":"Medium","q":"for guitars; low for fine strings"},"scarcity":{"s":4,"band":"High","q":"at the top (643 Bursts shipped in 1959; c. 650 Stradivari extant)"},"provenance":{"s":4,"band":"High","q":"originality, refinishing, celebrity attribution"}},"factors":{"Valuation":3,"Exit":3,"Custody":4,"Title and transfer":3,"Access":3,"Intangible premium":2},"horizon":{"big":"10+ years · originality is the asset","text":"A 1959 Burst or a pre-war Martin is held for decades by players and collectors alike; the registry tracks each survivor by serial number, so the trade knows when a guitar last changed hands and what was replaced in between. Every non-original part is a permanent discount, which rewards long, careful holding over trading."},"exit":{"routes":"Specialist dealers (Gruhn, Carter, Norman's, Vintage 'n' Rare) who buy outright or consign; Reverb for the broad market; Heritage, Christie's and Julien's for celebrity-provenance and record-setting instruments; private sale between collectors through the registry community.","activity":"A 1959 Les Paul Standard with no famous owner set a record of $781,250 in October 2026; dealer retail for Bursts runs $200,000–600,000+ by figure and condition. Reverb lists tens of thousands of vintage instruments at any time and publishes a price guide from completed sales; Heritage's collectibles turnover reached a record $1.4 bn in H1 2026 across categories.","cost":"Dealer consignment 15–25% or a buy-in a third or more below retail; Reverb 5% selling fee plus payment processing; auction seller's commission around 10% with a buyer's premium of 25%+ capping the hammer. Appraisal, originality inspection and insured shipping of a fragile instrument on top.","time":"Dealer sale in days at the dealer's price; consignment or Reverb listing weeks to months; auction on a scheduled calendar with payment 30–45 days after. A top Burst waits for the right buyer and the trade is patient."},"why":"Valuation is by expert appraisal against a thin but well-documented record: dealer price guides, the Burst serial registry, Tarisio's Cozio archive of every known Cremonese instrument. Exit for a guitar is through a handful of dealers and two or three auction houses with regular sales, in weeks to months; for a Stradivari it is a private placement through a London or New York dealer to a foundation or a patron, which can take a year. Custody is simple but not free: humidity control, insurance, and for bowed instruments regular playing and maintenance. The specific risk is originality: a refinish, a changed pickup or a re-graduated top can halve the price, and the market's certificate is a dealer's letter, not a laboratory report.","regime":"A 1959 Les Paul with no famous owner set a record of $781,250 last week; a Stradivari made $11.25 m last year below its estimate. Two markets, one logic: originality is the asset, and every replaced part is a discount.","regimeAsOf":"20 Oct 2026","since":"First entry. Heritage Auctions sold a 1959 Gibson Les Paul Standard from the Ichiro Kato collection for $781,250 on 15 October 2026, a record for a vintage guitar without celebrity provenance, in a $2.15 m sale with 848 bidders; the 1714 Joachim-Ma Stradivari made $11.25 m at Sotheby's New York in February 2025 against a $12–18 m estimate.","themes":["provenance","climate","sanctions","custody","tax","access","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"classic-cars","name":"Classic Cars","why":"Originality sets value"},{"slug":"watches","name":"Watches","why":"Dealer and auction"},{"slug":"art","name":"Art","why":"Collector market"}],"sources":12,"url":"/vintage-guitars-dashboard","exitLabel":"physical","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"Yes","Wrappers":"None of scale; instrument-lending foundations for fine strings","Owns":"—"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Dealer-led; auction for provenance pieces","Faces":"Gruhn, Carter, Norman's, Vintage 'n' Rare buying or consigning; Reverb; Heritage, Christie's, Julien's for celebrity instruments","Cost":"Consignment 15–25% or buy-in a third below retail; Reverb 5%"}}]},"climate":{"title":"Climate and supply shock","date":"","rows":[{"section":"The register: exposed markets","cells":{"Driver":"Humidity swings on the instrument itself","Event":"Cracks, lifted bridges and finish checking from humidity swings","Storable":"Yes, under humidity control"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Conditioned","Where":"Humidity-controlled; bowed instruments played and maintained","Cost":"Humidity control, insurance, maintenance; insured shipping of a fragile instrument","Fails":"Every non-original part is a permanent discount; CITES on Brazilian rosewood and tortoiseshell"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Calendar auction","Route":"Specialist dealers who buy or consign; Reverb; Heritage, Christie's and Julien's for celebrity provenance","Open":"Dealers on request; auctions a few times a year","Liquidity":"Medium; fine strings Low"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"Low; fixed stock dispersed among private owners","Regime":"Dealer quote; Calendar auction","Who":"A handful of specialist dealers' asking prices; Heritage and Christie's hammers for records"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"High; originality, refinishing, celebrity attribution","Claim":"Original parts and finish; attribution","Verifier":"Serial-number registries and specialist dealers; every non-original part is a permanent discount"}}]},"sanctions":{"title":"Sanctions, tariffs and origin","date":"","rows":[{"section":"The register: live measures","cells":{"Instrument":"Species listing","Measure":"Brazilian rosewood on CITES Appendix I since 1992 (pre-1969 Martins and Gibsons); tortoiseshell; pre-convention certificates needed for cross-border sale","Effect":"A 1950s guitar needs a certificate to cross a border; the best material is the most restricted"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"Non-wasting chattel: an instrument is not machinery","UK":"CGT above £6,000; a professional player's instrument used in the trade is treated differently","US":"28%; CITES on rosewood and ivory parts for cross-border sale (musical-instrument certificates)"}}]}}},"wagyu":{"slug":"wagyu","name":"Wagyu","family":"Rare Foods","grade":3,"label":"Specialist","rated":"Route: herds, land and listed producers","asof":"5 Oct 2026","method":"v1.2","axes":{"concentration":{"s":5,"band":"High","q":""},"liquidity":{"s":3,"band":"Medium","q":""},"scarcity":{"s":2,"band":"Low","q":""},"provenance":{"s":3,"band":"Medium","q":""}},"factors":{"Valuation":3,"Exit":2,"Custody":3,"Title and transfer":3,"Access":3,"Intangible premium":2},"horizon":{"big":"28–30 months · the animal","text":"A black wagyu steer is bought as a calf at 8–10 months and finished at about 30, so the production holding is two years and the cash is tied to a live animal that is graded only once, after slaughter. Herds and land are held for decades; a listed producer is an ordinary equity."},"exit":{"routes":"Finished cattle sell at one of about 170 licensed carcass auctions in Japan to registered wholesalers, after JMGA grading; calves at prefectural calf markets. Herds and feedlots change hands privately; a handful of producers and traders are listed in Tokyo. Outside Japan, Australian and US wagyu operations sell as farms.","activity":"A5 carcasses auctioned at ¥3,200–4,000/kg in 2026; the Tokyo wholesale weighted average for A5 was about ¥2,450/kg in August 2025 after a four-year low of ¥2,377 in July 2024. Black wagyu calves averaged ¥1,733/kg in mid-2024. Exports reached a record 12,628 t in 2025, with A5 striploin at US$120–190/kg FOB.","cost":"Auction and processing fees (an agent quotes ¥250–550/kg for cutting a half carcass), feed over 20 months of finishing, and the grading risk that an A4 result cuts the price by a quarter. Farm sales carry agency and transfer costs; export adds freezing, certification and 15–25% to FOB.","time":"A finished animal sells at the next weekly auction and is paid within days; a calf the same at its monthly market. A herd or farm takes months to place with an operating buyer, since the asset must be fed in the meantime."},"why":"Japanese carcass grading supports wholesale price discovery. Since 2020 Japanese law has made unauthorised resale or export of wagyu genetic material a criminal offence, so the breed cannot be replicated abroad from Japanese stock. The route is herds, land and listed producers; exit is slow and needs an operating buyer.","regime":"Branded premia widening as export volumes grow, while the A5 grade itself loses its scarcity.","regimeAsOf":"5 Oct 2026","since":"Re-checked 5 Oct 2026: no new export or price data found since the last update. Ratings unchanged.","themes":["provenance","climate","custody","tax","access","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"bluefin-tuna","name":"Bluefin Tuna","why":"Japanese grading and export"},{"slug":"parmigiano","name":"Parmigiano Reggiano","why":"Protected designation"},{"slug":"caviar","name":"Caviar","why":"Farmed luxury food"}],"sources":12,"url":"/wagyu-dashboard","exitLabel":"herds, land and listed producers","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"The animal or herd","Wrappers":"A handful of listed producers and traders in Tokyo","Owns":"Operating producers"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Administered auction (trade only)","Faces":"Regional carcass and calf markets in Japan; listed producers for capital","Cost":"Market commission; grade sets the price"}}]},"climate":{"title":"Climate and supply shock","date":"","rows":[{"section":"The register: exposed markets","cells":{"Driver":"Feed prices; calf supply; disease","Event":"Three-quarters of the Japanese market now A5; growth is in export","Storable":"No; herds and land are the holding"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Living / perishable","Where":"The animal for 28–30 months; herds and land for decades","Cost":"Feed over 20 months of finishing; processing ¥250–550/kg","Fails":"Graded once, after slaughter; an A4 result cuts the price by a quarter"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Calendar auction","Route":"About 170 licensed carcass auctions in Japan after JMGA grading; calf markets; herds privately; a handful of listed producers","Open":"Regular, trade buyers only","Liquidity":"Medium"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"High","Regime":"Calendar auction","Who":"About 170 licensed carcass auctions after JMGA grading; an A4 result cuts the price by a quarter"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"Medium","Claim":"Breed and brand (Kobe); grade","Verifier":"JMGA grading of every carcass; individual cattle ID; Kobe certification"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"Animals: livestock, wasting; listed producers: equity","UK":"A hobby animal is a wasting chattel; a herd is trading stock under the herd basis","US":"Breeding cattle held two years are Section 1231; Japan: export of live animals and genetics is prohibited"}}]}}},"watches":{"slug":"watches","name":"Watches","family":"Cellar & Collectibles","grade":3,"label":"Specialist","rated":"Physical","asof":"5 Oct 2026","method":"v1.2","axes":{"concentration":{"s":5,"band":"High","q":""},"liquidity":{"s":3,"band":"Medium","q":""},"scarcity":{"s":2,"band":"Low","q":""},"provenance":{"s":3,"band":"Medium","q":""}},"factors":{"Valuation":3,"Exit":3,"Custody":4,"Title and transfer":3,"Access":4,"Intangible premium":2},"horizon":{"big":"5–10 years","text":"Dealers and platforms cite a five- to ten-year hold for references expected to appreciate; anything shorter is exposed to the dealer spread on both legs. The 2022–24 bust showed the horizon can be dictated by the cycle: a watch bought at the 2022 peak is still under water in 2026 for most references."},"exit":{"routes":"Sale to a dealer for an immediate offer; consignment to a dealer or platform; listing on a marketplace such as Chrono24 (over 500,000 listings, buyers in 150 countries); auction at Phillips, Sotheby's, Christie's or Antiquorum for rare references.","activity":"The pre-owned market turned over about $17 bn in 2025, Rolex alone $5.7 bn. On Chrono24 a correctly priced listing typically sells in two to eight weeks; instant-offer dealers pay in one to five days at 70–85% of retail.","cost":"Private marketplace sale 6.5% commission; platform consignment 13–19%; dealer buy-in priced at a discount of 15–30% to retail; auction seller's commission negotiable plus a buyer's premium of 25%+ that caps the hammer. Service history and box-and-papers move the price by more than the fee.","time":"Dealer sale: days, payout one to three business days after receipt. Marketplace: weeks to sell, then escrow release about seven days after delivery. Auction: consignment deadlines run two to four months ahead of sale, payment about 35 days after."},"why":"Secondary prices are visible through auction results and dealer platforms. Exit within weeks is possible for leading references, slower for others. Custody is simple; authentication and service history decide value.","regime":"Secondary prices stabilising after the 2022–24 bust; primary export value held by the top of the pyramid.","regimeAsOf":"5 Oct 2026","since":"Swiss watch exports rose 9.1% in August to CHF 1.79bn, the fourth straight monthly gain, turning the 12-month average positive for the first time in two years; year to date +1.7%. The US, still the largest market, fell 19.4%; the UK (+46%) and China (+16%) led. France’s +113% likely reflects logistics routing, per FH.","themes":["provenance","sanctions","custody","tax","access","exit-depth","auction-vs-dealer","price-setters"],"related":[{"slug":"handbags","name":"Handbags","why":"Brand-controlled supply"},{"slug":"signed-jewellery","name":"Signed Jewellery","why":"Maison resale"},{"slug":"classic-cars","name":"Classic Cars","why":"Condition and originality"},{"slug":"art","name":"Art","why":"Auction cycle"}],"sources":18,"url":"/watches-dashboard","exitLabel":"physical","themeRows":{"access":{"title":"Fractional and fund access","date":"","rows":[{"section":"The register, market by market","cells":{"Direct":"Yes","Wrappers":"Swatch, Richemont equity; platforms are marketplaces, not funds","Owns":"Manufacturers"}}]},"auction-vs-dealer":{"title":"Auction or dealer","date":"","rows":[{"section":"The register, market by market","cells":{"Config":"Dealer-led; auction for rarities","Faces":"A dealer for an immediate offer; consignment; Chrono24 (500,000+ listings); Phillips, Christie's, Sotheby's for the rare","Cost":"Dealer buy-in 15–30% below retail; marketplace 6.5%; consignment 13–19%"}}]},"custody":{"title":"Storage, custody and insurance","date":"","rows":[{"section":"The register, market by market","cells":{"Regime":"Shelf","Where":"In a safe, with box and papers","Cost":"Servicing; insurance","Fails":"Service history and box-and-papers move the price by more than any fee"}}]},"exit-depth":{"title":"Exit depth: who buys when you sell","date":"","rows":[{"section":"The register, market by market","cells":{"Door":"Calendar auction","Route":"Dealer for an immediate offer; consignment; Chrono24 (500,000+ listings); Phillips, Sotheby's, Christie's, Antiquorum for rare references","Open":"Dealer any day; auctions Geneva May and November","Liquidity":"Medium"}}]},"price-setters":{"title":"Who sets the price","date":"","rows":[{"section":"The register, market by market","cells":{"Concentration":"High","Regime":"Administered (retail); Trade platform (secondary)","Who":"Four brands hold 49% of industry sales and allocate references; Chrono24 and dealers set the secondary price"}}]},"provenance":{"title":"Provenance and verification","date":"","rows":[{"section":"The register, market by market","cells":{"Risk":"Medium","Claim":"Originality of parts and dial; service history","Verifier":"Brand archive extracts where offered; dealer and platform inspection"}}]},"sanctions":{"title":"Sanctions, tariffs and origin","date":"","rows":[{"section":"The register: live measures","cells":{"Instrument":"Tariff","Measure":"Patek Philippe rolled back some US prices by up to c. 8% after tariff and currency moves","Effect":"Retail price by market, and so the grey-market arbitrage"}}]},"tax":{"title":"Tax and legal wrappers","date":"","rows":[{"section":"The register, market by market","cells":{"Form":"Machinery: wasting chattel","UK":"CGT-exempt, including antique and vintage pieces; HMRC names clocks and watches expressly","US":"28%; import duty by movement and case; Switzerland: none for a private seller"}}]}}}}};